import { useState, useEffect, useCallback } from "preact/hooks";
import { getTranslation } from "@/utils/i18n.js";
import type { Language } from "@/domain/value-objects/Language.js";
import { useTodos } from "@/presentation/hooks/useTodos.js";
import { useSync } from "@/presentation/hooks/useSync.js";
import { useSettings } from "@/presentation/hooks/useSettings.js";
import { useUI } from "@/presentation/hooks/useUI.js";
import { useAppInit } from "@/presentation/hooks/useAppInit.js";
import { useAppTodoInput } from "@/presentation/hooks/useAppTodoInput.js";
import { useAppConfirmActions } from "@/presentation/hooks/useAppConfirmActions.js";
import { ChromeStorageTodoRepository } from "@/infrastructure/persistence/repositories/ChromeStorageTodoRepository.js";
import { ChromeStorageSyncRepository } from "@/infrastructure/persistence/repositories/ChromeStorageSyncRepository.js";
import { ChromeStorageSettingsRepository } from "@/infrastructure/persistence/repositories/ChromeStorageSettingsRepository.js";
import { createSyncPort } from "@/application/ports/createSyncPort.js";
import { LocalToSyncMigration } from "@/infrastructure/persistence/migrations/LocalToSyncMigration.js";
import type { ITodoSyncPort } from "@/application/ports/ITodoSyncPort.js";
import type { ISyncRepository } from "@/domain/repositories/ISyncRepository.js";
import type { GoogleSyncSettings } from "@/domain/repositories/ISyncRepository.js";
import type { ISettingsRepository } from "@/domain/repositories/ISettingsRepository.js";
import type { AppInitDependencies } from "@/presentation/hooks/useAppInit.js";
import { kpssService } from "@/services/kpss/kpssService.js";

import { Sidebar } from "@/components/Sidebar.js";
import { ViewRouter } from "@/components/ViewRouter.js";
import { ConfirmModal } from "@/components/ConfirmModal.js";
import { SettingsDrawer } from "@/components/SettingsDrawer.js";
import { HeroHeader } from "@/components/HeroHeader.js";
import { FooterQuote } from "@/components/FooterQuote.js";
import { AppTopHeader } from "@/components/AppTopHeader.js";
import { KpssNotesDashboard } from "@/components/kpss/wiki/KpssNotesDashboard.js";
import type { Todo } from "@/types/types.js";

// Singleton instances â€” created once outside component to avoid re-instantiation
const todoRepository = new ChromeStorageTodoRepository();
const syncRepo: ISyncRepository = new ChromeStorageSyncRepository();
const syncPort: ITodoSyncPort = createSyncPort();
const settingsRepo: ISettingsRepository = new ChromeStorageSettingsRepository();
const migration = new LocalToSyncMigration();
const appInitDeps: AppInitDependencies = {
  settingsRepo,
  todoRepo: todoRepository,
  syncRepo,
  syncPort,
  migration,
};

export function App() {
  // â”€â”€â”€ Settings Hook â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const {
    lang,
    setLangState,
    sidebarOpen,
    setSidebarOpenState,
    freeGamesNotificationsEnabled,
    calendarNotificationsEnabled,
    pomoBlockEnabled,
    universalInfoBoxEnabled,
    universalInfoBoxHotkey,
    autoGroupTabsEnabled,
    aiProvider,
    aiApiKey,
    aiModel,
    aiEndpoint,
    aiShowThinking,
    kpssGoalType,
    kpssTargetNet,
    kpssTargetScore,
    detoxLimits,
    loadSettings,
    handleToggleLang,
    handleSidebarToggle,
    handleToggleFreeGamesNotifications,
    handleToggleCalendarNotifications,
    handleTogglePomoBlock,
    handleToggleUniversalInfoBox,
    handleUniversalInfoBoxHotkeyChange,
    whatsappBridgeEnabled,
    telegramBridgeEnabled,
    handleToggleWhatsappBridge,
    handleToggleTelegramBridge,
    handleToggleAutoGroupTabs,
    handleClearAllData,
    handleUpdateAIConfig,
    handleUpdateAIShowThinking,
    handleKpssGoalTypeChange,
    handleKpssTargetNetChange,
    handleKpssTargetScoreChange,
    handleDetoxLimitsChange,
  } = useSettings();

  // â”€â”€â”€ UI Hook â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const {
    activeView,
    setActiveView,
    sidebarOrder,
    setSidebarOrder,
    activeTab,
    setActiveTab,
    settingsOpen,
    setSettingsOpen,
    settingsInitialTab,
    clockText,
    dateText,
    quoteText,
    confirmDialog,
    setConfirmDialog,
    alertDialog,
    setAlertDialog,
    googleUserEmail,
    setGoogleUserEmail,
    isSyncing,
    setIsSyncing,
    syncSettings,
    setSyncSettings,
    showAlert,
    showConfirm,
    handleTabChangeUI,
    handleOpenSettings,
    loadSidebarOrder,
    handleViewChange,
    refreshClock,
    refreshQuote,
  } = useUI();

  // â”€â”€â”€ Sync Hook â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const {
    handleManualSyncTasks,
    handleGoogleLogin,
    handleGoogleLogout,
    handleExportBackup,
    handleImportBackup,
    handleBackupToGoogleDrive,
    handleRestoreFromGoogleDrive,
    triggerCloudBackup,
  } = useSync({
    showAlert,
    errorLabel: "Sync error",
    detailLabel: "Detail",
  });

  // â”€â”€â”€ Todos Hook â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const {
    todos,
    handleAddTodo,
    handleToggleTodo,
    handleDeleteTodo,
    handleMoveTaskStatus,
    handleMoveTaskDirection,
    handleUpdateTodoUrgentImportant,
    initTodos,
  } = useTodos(
    todoRepository,
    syncPort,
    syncRepo,
    triggerCloudBackup,
    showAlert,
    getTranslation(lang as Language),
  );

  // â”€â”€â”€ App Init Hook â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  useAppInit(appInitDeps, {
    onSettingsLoaded: loadSettings,
    onTodosLoaded: initTodos,
    onSyncSettingsLoaded: (settings) => setSyncSettings(settings),
    onGoogleUserEmail: (email) => setGoogleUserEmail(email),
    onSidebarOrderLoaded: (order) => setSidebarOrder(order),
    onQuoteRefreshed: (l: Language) => refreshQuote(l),
    onClockStarted: () => refreshClock(lang as Language),
  });

  // Sync initTodos into the DI-backed useAppInit flow
  useEffect(() => {
    initTodos();
  }, []);

  // Re-render clock/quote on lang change
  useEffect(() => {
    refreshClock(lang as Language);
    refreshQuote(lang as Language);
  }, [lang]);

  // â”€â”€â”€ Todo Input Hook â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const {
    todoText,
    setTodoText,
    todoRepeat,
    todoDueDate,
    setTodoDueDate,
    handleAddTodoClick,
    handleKeyPress,
    handleRepeatChange,
    handleTabChange,
  } = useAppTodoInput({
    lang: lang as Language,
    onAddTodo: handleAddTodo,
    activeTab,
    setActiveTab,
    setActiveView,
    handleTabChangeUI,
  });

  // â”€â”€â”€ Confirm Actions Hook â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const { handleClearAllDataConfirm, handleResetKpssDataConfirm } =
    useAppConfirmActions({ showConfirm });

  // â”€â”€â”€ Continue to Chat callback â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const handleContinueToChat = useCallback(
    (symbol: string) => {
      // Stock bilgisini sessionStorage'a yaz ki AI Chat okusun
      sessionStorage.setItem("hermes_pending_stock", symbol);
      handleViewChange("ai-chat");
    },
    [handleViewChange],
  );

  // â”€â”€â”€ JSX Template â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const t = getTranslation(lang as Language);

  if (typeof window !== "undefined" && window.location.search.includes("view=kpss-notes")) {
    return <KpssNotesDashboard lang={lang as Language} t={t} />;
  }

  return (
    <>
      {/* Background visual overlay blur */}
      <div className="background-overlay"></div>

      {/* Sidebar Navigation */}
      <Sidebar
        lang={lang as Language}
        activeView={activeView}
        activeTab={activeTab}
        sidebarOpen={sidebarOpen}
        onViewChange={handleViewChange}
        onTabChange={handleTabChange}
        onSidebarToggle={handleSidebarToggle}
        onSettingsOpen={() => handleOpenSettings("general")}
        onOrderChange={(newOrder) => setSidebarOrder(newOrder)}
      />

      {/* Top Input Header */}
      {activeView === "list" && (
        <AppTopHeader
          t={t}
          lang={lang as Language}
          todoText={todoText}
          onTodoTextChange={setTodoText}
          onKeyPress={handleKeyPress}
          todoRepeat={todoRepeat}
          onRepeatChange={handleRepeatChange}
          todoDueDate={todoDueDate}
          onDueDateChange={setTodoDueDate}
          onAddTodoClick={handleAddTodoClick}
        />
      )}

      {/* Settings Drawer */}
      <SettingsDrawer
        isOpen={settingsOpen}
        onClose={() => setSettingsOpen(false)}
        initialTab={settingsInitialTab}
        lang={lang as Language}
        onToggleLang={handleToggleLang}
        freeGamesNotificationsEnabled={freeGamesNotificationsEnabled}
        onToggleFreeGamesNotifications={handleToggleFreeGamesNotifications}
        calendarNotificationsEnabled={calendarNotificationsEnabled}
        onToggleCalendarNotifications={handleToggleCalendarNotifications}
        pomoBlockEnabled={pomoBlockEnabled}
        onTogglePomoBlock={handleTogglePomoBlock}
        universalInfoBoxEnabled={universalInfoBoxEnabled}
        onToggleUniversalInfoBox={handleToggleUniversalInfoBox}
        universalInfoBoxHotkey={universalInfoBoxHotkey}
        onUniversalInfoBoxHotkeyChange={handleUniversalInfoBoxHotkeyChange}
        whatsappBridgeEnabled={whatsappBridgeEnabled}
        onToggleWhatsappBridge={handleToggleWhatsappBridge}
        telegramBridgeEnabled={telegramBridgeEnabled}
        onToggleTelegramBridge={handleToggleTelegramBridge}
        autoGroupTabsEnabled={autoGroupTabsEnabled}
        onToggleAutoGroupTabs={handleToggleAutoGroupTabs}
        onExportBackup={handleExportBackup}
        onImportBackup={handleImportBackup}
        onClearAllData={() => handleClearAllDataConfirm(handleClearAllData)}
        aiApiKey={aiApiKey}
        aiModel={aiModel}
        aiEndpoint={aiEndpoint}
        onUpdateAIConfig={handleUpdateAIConfig}
        aiShowThinking={aiShowThinking}
        onUpdateAIShowThinking={handleUpdateAIShowThinking}
        googleUserEmail={googleUserEmail}
        isSyncing={isSyncing}
        onGoogleLogin={handleGoogleLogin}
        onGoogleLogout={handleGoogleLogout}
        syncSettings={syncSettings}
        onBackupToGoogleDrive={handleBackupToGoogleDrive}
        onRestoreFromGoogleDrive={handleRestoreFromGoogleDrive}
        kpssGoalType={kpssGoalType}
        kpssTargetNet={kpssTargetNet}
        kpssTargetScore={kpssTargetScore}
        onKpssGoalTypeChange={handleKpssGoalTypeChange}
        onKpssTargetNetChange={handleKpssTargetNetChange}
        onKpssTargetScoreChange={handleKpssTargetScoreChange}
        onResetKpssData={() =>
          handleResetKpssDataConfirm(async () => {
            await kpssService.resetAllKpssData();
            showAlert(t.alert_kpss_reset_success);
          })
        }
        detoxLimits={detoxLimits}
        onDetoxLimitsChange={handleDetoxLimitsChange}
        onNotify={(message: string) => showAlert(message)}
      />

      {/* Main Viewport */}
      <main id="container" className="container">
        {sidebarOrder.length > 0 && activeView === sidebarOrder[0] && (
          <HeroHeader clockText={clockText} dateText={dateText} />
        )}
        <ViewRouter
          activeView={activeView}
          lang={lang as Language}
          todos={todos}
          activeTab={activeTab}
          syncSettings={syncSettings}
          isSyncing={isSyncing}
          aiProvider={aiProvider}
          aiApiKey={aiApiKey}
          aiModel={aiModel}
          aiEndpoint={aiEndpoint}
          aiShowThinking={aiShowThinking}
          kpssGoalType={kpssGoalType}
          kpssTargetNet={kpssTargetNet}
          kpssTargetScore={kpssTargetScore}
          onTabChange={handleTabChange}
          onToggleTodo={handleToggleTodo}
          onDeleteTodo={handleDeleteTodo}
          onMoveTaskStatus={handleMoveTaskStatus}
          onMoveTaskDirection={handleMoveTaskDirection}
          onUpdateTodoUrgentImportant={handleUpdateTodoUrgentImportant}
          onAddTodo={handleAddTodo}
          onManualSync={handleManualSyncTasks}
          onShowConfirm={showConfirm}
          onSettingsOpen={handleOpenSettings}
          onContinueToChat={handleContinueToChat}
        />
      </main>

      {/* Footer Quote â€” outside container, zero layout impact */}
      {quoteText && activeView !== "ai-chat" && (
        <FooterQuote quoteText={quoteText} />
      )}

      {/* Confirm Modal */}
      <ConfirmModal
        isOpen={confirmDialog.isOpen}
        message={confirmDialog.message}
        lang={lang as Language}
        onConfirm={confirmDialog.onConfirm}
        onCancel={() =>
          setConfirmDialog((prev) => ({ ...prev, isOpen: false }))
        }
      />

      {/* Alert Modal */}
      <ConfirmModal
        isOpen={alertDialog.isOpen}
        message={alertDialog.message}
        lang={lang as Language}
        onConfirm={() => {
          if (alertDialog.onConfirm) {
            alertDialog.onConfirm();
          }
          setAlertDialog({ isOpen: false, message: "" });
        }}
        isAlert={true}
      />
    </>
  );
}

/**
 * UpdateSettingsUseCase
 * Application use case for updating application settings.
 * Handles all setting changes (language, sidebar, notifications, AI, KPSS, detox, etc.).
 */

import type {
  ISettingsRepository,
  AppSettings,
} from "@/domain/repositories/ISettingsRepository.js";
import type { Language } from "@/domain/value-objects/Language.js";

export class UpdateSettingsUseCase {
  constructor(private settingsRepo: ISettingsRepository) {}

  async getSettings(): Promise<AppSettings> {
    return this.settingsRepo.getSettings();
  }

  async setLanguage(lang: Language): Promise<void> {
    await this.settingsRepo.setLang(lang);
  }

  async setSidebarOpen(isOpen: boolean): Promise<void> {
    await this.settingsRepo.setSidebarOpen(isOpen);
  }

  async toggleFreeGamesNotifications(): Promise<boolean> {
    const settings = await this.settingsRepo.getSettings();
    const nextVal = !settings.freeGamesNotificationsEnabled;
    await this.settingsRepo.setFreeGamesNotificationsEnabled(nextVal);
    return nextVal;
  }

  async toggleCalendarNotifications(): Promise<boolean> {
    const settings = await this.settingsRepo.getSettings();
    const nextVal = !settings.calendarNotificationsEnabled;
    await this.settingsRepo.setCalendarNotificationsEnabled(nextVal);
    return nextVal;
  }

  async togglePomoBlock(): Promise<boolean> {
    const settings = await this.settingsRepo.getSettings();
    const nextVal = !settings.pomoBlockEnabled;
    await this.settingsRepo.setPomoBlockEnabled(nextVal);
    return nextVal;
  }

  async setUniversalInfoBox(enabled: boolean, hotkey: string): Promise<void> {
    await this.settingsRepo.setUniversalInfoBox(enabled, hotkey);
  }

  async toggleWhatsappBridge(): Promise<boolean> {
    const settings = await this.settingsRepo.getSettings();
    const nextVal = !settings.whatsappBridgeEnabled;
    await this.settingsRepo.setWhatsappBridgeEnabled(nextVal);
    return nextVal;
  }

  async toggleTelegramBridge(): Promise<boolean> {
    const settings = await this.settingsRepo.getSettings();
    const nextVal = !settings.telegramBridgeEnabled;
    await this.settingsRepo.setTelegramBridgeEnabled(nextVal);
    return nextVal;
  }

  async clearAllData(lang: Language): Promise<void> {
    await this.settingsRepo.clearAll(lang);
  }
}

/**
 * BackupToDriveUseCase
 *
 * Application use case for backing up all application data to Google Drive.
 * Collects data from repositories and delegates upload to the drive port.
 */

import type { ISyncRepository } from "@/domain/repositories/ISyncRepository.js";
import type { IDriveBackupPort } from "@/application/ports/IDriveBackupPort.js";
import type { ITodoRepository } from "@/domain/repositories/ITodoRepository.js";

export class BackupToDriveUseCase {
  constructor(
    private syncRepo: ISyncRepository,
    private drivePort: IDriveBackupPort,
    private todoRepo: ITodoRepository,
  ) {}

  async execute(): Promise<void> {
    const syncSettings = await this.syncRepo.getSyncSettings();
    if (!syncSettings.enabled) {
      return;
    }

    // Get auth token from chrome.identity via chrome.storage cached token
    const token = await this.getAuthToken();

    // Gather all backup data from chrome.storage.sync directly
    const allData = await new Promise<Record<string, unknown>>((resolve) => {
      chrome.storage.sync.get(null, (result) => {
        resolve(result as Record<string, unknown>);
      });
    });

    await this.drivePort.backupToDrive(token, allData);
  }

  private async getAuthToken(): Promise<string> {
    return new Promise((resolve, reject) => {
      chrome.identity.getAuthToken({ interactive: false }, (token) => {
        if (chrome.runtime.lastError || !token) {
          reject(
            new Error(chrome.runtime.lastError?.message ?? "No auth token"),
          );
        } else {
          resolve(token as string);
        }
      });
    });
  }
}

/**
 * RestoreFromDriveUseCase
 * Application use case for restoring all data (including sidebarOrder) from Google Drive backup.
 */

import type { ISyncRepository } from "@/domain/repositories/ISyncRepository.js";
import type { IDriveBackupPort } from "@/application/ports/IDriveBackupPort.js";
import type { ITodoRepository } from "@/domain/repositories/ITodoRepository.js";
import type { INoteRepository } from "@/domain/repositories/INoteRepository.js";
import type { Todo } from "@/domain/entities/Todo.js";
import type { Note } from "@/types/types.js";
import { logger } from "@/utils/logger.js";

export interface RestoreResult {
  readonly restored: boolean;
  readonly data?: Record<string, unknown>;
}

export class RestoreFromDriveUseCase {
  constructor(
    private syncRepo: ISyncRepository,
    private drivePort: IDriveBackupPort,
    private todoRepo?: ITodoRepository,
    private noteRepo?: INoteRepository,
  ) {}

  async execute(): Promise<RestoreResult> {
    const syncSettings = await this.syncRepo.getSyncSettings();
    if (!syncSettings.enabled) {
      return { restored: false };
    }

    try {
      const token = await this.getAuthToken();
      const restored = await this.drivePort.restoreFromDrive(token);

      if (!restored) {
        return { restored: false };
      }

      // MERGE: combine Drive backup with current local data instead of
      // blindly overwriting. Newer local todos/notes (created after the
      // backup) must survive a restore. Arrays are merged by unique id,
      // scalars use the backup value only when the local key is absent.
      const [localTodos, localNotes] = await Promise.all([
        this.todoRepo ? this.todoRepo.getAll() : Promise.resolve([] as Todo[]),
        this.noteRepo ? this.noteRepo.getAll() : Promise.resolve([] as Note[]),
      ]);

      // Todos: merge by id — Drive wins on conflicts, local extras kept
      if (Array.isArray(restored.todos)) {
        const mergedTodos = new Map<string, Todo>();
        for (const t of restored.todos as Todo[]) {
          if (t && t.id) {
            mergedTodos.set(t.id, t);
          }
        }
        for (const t of localTodos) {
          if (t && t.id && !mergedTodos.has(t.id)) {
            mergedTodos.set(t.id, t); // local-only todo survives
          }
        }
        restored.todos = Array.from(mergedTodos.values());
      }

      // Notes: merge by id — same strategy
      if (Array.isArray(restored.notes)) {
        const mergedNotes = new Map<string, Note>();
        for (const n of restored.notes as Note[]) {
          if (n && n.id) {
            mergedNotes.set(n.id, n);
          }
        }
        for (const n of localNotes) {
          if (n && n.id && !mergedNotes.has(n.id)) {
            mergedNotes.set(n.id, n);
          }
        }
        restored.notes = Array.from(mergedNotes.values());
      }

      // Save all restored keys (including sidebarOrder) directly to chrome.storage.sync
      await new Promise<void>((resolve) => {
        chrome.storage.sync.set(restored, () => resolve());
      });

      // Restore data to repositories if available
      if (restored.todos && this.todoRepo) {
        await this.todoRepo.saveAll(restored.todos as Todo[]);
      }
      if (restored.notes && this.noteRepo) {
        await this.noteRepo.saveAll(restored.notes as Note[]);
      }

      return { restored: true, data: restored };
    } catch (e) {
      logger.error("Restore from Drive failed:", e);
      return { restored: false };
    }
  }

  private async getAuthToken(): Promise<string> {
    return new Promise((resolve, reject) => {
      chrome.identity.getAuthToken({ interactive: false }, (token) => {
        if (chrome.runtime.lastError || !token) {
          reject(
            new Error(chrome.runtime.lastError?.message ?? "No auth token"),
          );
        } else {
          resolve(token as string);
        }
      });
    });
  }
}

import { logger } from "@/utils/logger.js";

/**
 * alarmNotificationHandler.ts
 * Clean Architecture - Background Domain Handler for Alarms and Notifications (Free Games, Calendar Tasks, BIST Stock Alerts).
 */

import { getTranslation } from "@/utils/i18n.js";
import type { Language } from "@/types/types.js";

async function checkFreeGames(): Promise<void> {
  chrome.storage.sync.get(
    ["freeGamesNotificationsEnabled", "lang"],
    async (syncRes) => {
      const notificationsEnabled =
        (syncRes.freeGamesNotificationsEnabled as boolean) ?? true;
      if (!notificationsEnabled) {
        return;
      }

      const lang = (syncRes.lang as string) || "tr";
      const t = getTranslation(lang as Language);

      try {
        const response = await fetch(
          "https://www.gamerpower.com/api/giveaways",
        );
        if (!response.ok) {
          return;
        }
        const giveaways = await response.json();
        if (!Array.isArray(giveaways)) {
          return;
        }

        const targetPlatforms = ["steam", "epic games store", "gog"];
        const filtered = giveaways.filter((item) => {
          if (!item.platforms) {
            return false;
          }
          const platformsLower = item.platforms.toLowerCase();
          return targetPlatforms.some((plat) => platformsLower.includes(plat));
        });

        if (filtered.length === 0) {
          return;
        }

        chrome.storage.local.get(["notified_giveaway_ids"], (localRes) => {
          const notifiedIds =
            (localRes.notified_giveaway_ids as number[]) || [];
          const newGiveaways = filtered.filter(
            (item: { id: number }) => !notifiedIds.includes(item.id),
          );

          if (newGiveaways.length === 0) {
            return;
          }

          newGiveaways.forEach(
            (item: { id: number; title: string; worth: string }) => {
              const title = t.notif_free_game_title.replace(
                "{title}",
                item.title,
              );
              const message = t.notif_free_game_msg.replace(
                "{worth}",
                item.worth,
              );

              chrome.notifications.create(String(item.id), {
                type: "basic",
                iconUrl: "icons/icon-128.png",
                title: title,
                message: message,
                priority: 2,
              });
            },
          );

          const updatedIds = [
            ...notifiedIds,
            ...newGiveaways.map((item: { id: number }) => item.id),
          ];
          chrome.storage.local.set({ notified_giveaway_ids: updatedIds });
        });
      } catch (err) {
        logger.error("Failed to check free games:", err);
      }
    },
  );
}

async function checkCalendarTasks(): Promise<void> {
  chrome.storage.sync.get(
    ["calendarNotificationsEnabled", "lang", "todos"],
    (syncRes) => {
      const notificationsEnabled =
        (syncRes.calendarNotificationsEnabled as boolean) ?? true;
      if (!notificationsEnabled) {
        return;
      }

      const lang = (syncRes.lang as string) || "tr";
      const t = getTranslation(lang as Language);
      const todos =
        (syncRes.todos as Array<{ completed: boolean; dueDate?: string }>) ||
        [];

      const todayStr = new Date().toLocaleDateString("sv");
      const dueToday = todos.filter(
        (t) => !t.completed && t.dueDate === todayStr,
      );

      if (dueToday.length === 0) {
        return;
      }

      chrome.storage.local.get(
        ["last_calendar_notification_date"],
        (localRes) => {
          const lastDate = localRes.last_calendar_notification_date;
          if (lastDate === todayStr) {
            return;
          }

          const title = t.notif_calendar_title;
          const message = t.notif_calendar_msg.replace(
            "{count}",
            String(dueToday.length),
          );

          chrome.notifications.create("calendar_tasks_due_today", {
            type: "basic",
            iconUrl: "icons/icon-128.png",
            title: title,
            message: message,
            priority: 2,
          });

          chrome.storage.local.set({
            last_calendar_notification_date: todayStr,
          });
        },
      );
    },
  );
}

function isBistMarketOpen(): boolean {
  const date = new Date();
  const utcOffset = date.getTimezoneOffset() * 60000;
  const trtDate = new Date(date.getTime() + utcOffset + 3 * 3600000);
  const day = trtDate.getDay();
  if (day === 0 || day === 6) {
    return false;
  }
  const timeInMinutes = trtDate.getHours() * 60 + trtDate.getMinutes();
  return timeInMinutes >= 9 * 60 + 55 && timeInMinutes <= 18 * 60 + 15;
}

async function checkBistStockRules(): Promise<void> {
  if (!isBistMarketOpen()) {
    return;
  }

  chrome.storage.sync.get(["stockPortfolio", "stockRules"], async (res) => {
    const portfolio = (res.stockPortfolio as Array<{ symbol: string }>) || [];
    const rules =
      (res.stockRules as Array<{
        symbol: string;
        isActive: boolean;
        ruleType: string;
      }>) || [];
    if (portfolio.length === 0 || rules.length === 0) {
      return;
    }

    const symbols = Array.from(new Set(portfolio.map((p) => p.symbol)));
    for (const sym of symbols) {
      try {
        const fullSymbol = sym.toUpperCase().endsWith(".IS")
          ? sym.toUpperCase()
          : `${sym.toUpperCase()}.IS`;
        const url = `https://query2.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(fullSymbol)}?interval=1d&range=1d`;
        const resp = await fetch(url);
        if (!resp.ok) {
          continue;
        }
        const json = await resp.json();
        const meta = json?.chart?.result?.[0]?.meta;
        if (!meta) {
          continue;
        }

        const price = meta.regularMarketPrice ?? 0;
        const prev = meta.previousClose ?? price;
        const changePct = prev !== 0 ? ((price - prev) / prev) * 100 : 0;
        const normSym = fullSymbol.replace(/\.IS$/, "");

        const activeRules = rules.filter(
          (r) =>
            r.symbol.replace(/\.IS$/, "").toUpperCase() === normSym &&
            r.isActive,
        );
        for (const r of activeRules) {
          let triggered = false;
          let title = "BIST Alarm Uyarısı";
          let message = "";

          if (r.ruleType === "RED_CANDLE" && changePct <= -4.0) {
            triggered = true;
            title = `⚠️ KRİZ UYARISI: ${normSym} Sert Düşüşte!`;
            message = `${normSym} %${changePct.toFixed(2)} düşüş yaşadı. Anlık fiyat: ₺${price.toFixed(2)}`;
          } else if (r.ruleType === "TAVAN_BREAK" && changePct < 8.5) {
            triggered = true;
            title = `⚡ ${normSym} Tavan Bozdu!`;
            message = `${normSym} tavan serisini bozdu. Günlük değişim: %${changePct.toFixed(2)}`;
          }

          if (triggered) {
            chrome.notifications.create(`bist-${normSym}-${Date.now()}`, {
              type: "basic",
              iconUrl: "icons/icon128.png",
              title: title,
              message: message,
              priority: 2,
            });
          }
        }
      } catch {
        // ignore background fetch errors
      }
    }
  });
}

