/**
 * SchemaBuilder.tsx
 * KPSS Şema Oluşturucu — archives/kpss-sema-olusturucu-v2.html mantığı (birebir).
 * Tire-tabanlı outline → klasik hiyerarşik ağaç diyagramı:
 *  - kök üstte ortalanır, dallar aşağıya doğru yanlara yayılır (tree layout)
 *  - kutu genişliği canvas ile gerçek metin genişliğinden ölçülür → taşma olmaz
 *  - parent→child arası yumuşak (bezier) eğri çizgiler aynı koordinatlardan türer
 * Hem tarih haritası (Devlet Teşkilatı) hem not editöründe kullanılır.
 */
import type { JSX } from "preact";
import { useMemo, useState } from "preact/hooks";

/* ---------- Veri modeli ---------- */

interface OutlineNode {
  text: string;
  children: OutlineNode[];
  level: number;
  depth: number;
  w: number;
  x: number;
  y: number;
}

const BOX_MIN_W = 120;
const BOX_MAX_W = 210;
const BOX_H = 48;
const ROW_GAP = 110; // satırlar arası dikey mesafe
const SIB_GAP = 34; // kardeş kutular arası yatay boşluk
const LINE_COLOR = "#a5905f";
const BOX_BORDER = "#7a2323";

/* ---------- Outline ayrıştırma (archives ile birebir) ---------- */

function parseOutline(text: string): OutlineNode[] {
  const lines = text.split("\n").filter((l) => l.trim().length > 0);
  const root: OutlineNode = {
    text: "ROOT",
    children: [],
    level: -1,
    depth: 0,
    w: 0,
    x: 0,
    y: 0,
  };
  const stack = [root];
  lines.forEach((raw) => {
    // seviye: satır başındaki "-" (tire) sayısı. Tab/boşluk da yedek olarak desteklenir.
    const dashMatch = raw.match(/^-*/)?.[0] || "";
    let level: number;
    let content: string;
    if (dashMatch.length > 0) {
      level = dashMatch.length;
      content = raw.slice(dashMatch.length).trim();
    } else {
      const indentMatch = raw.match(/^(\t| )*/)?.[0] || "";
      const tabs = (indentMatch.match(/\t/g) || []).length;
      const spaces = (indentMatch.match(/ /g) || []).length;
      level = tabs + Math.floor(spaces / 2);
      content = raw.trim();
    }
    if (!content) {
      return;
    }
    const node: OutlineNode = {
      text: content,
      children: [],
      level,
      depth: 0,
      w: 0,
      x: 0,
      y: 0,
    };
    while (stack.length > 1 && stack[stack.length - 1].level >= level) {
      stack.pop();
    }
    stack[stack.length - 1].children.push(node);
    stack.push(node);
  });
  return root.children;
}

/* ---------- Genişlik ölçümü (canvas — taşmayı önler) ---------- */

let measureCtx: CanvasRenderingContext2D | null = null;

function measureWidth(text: string): number {
  if (!measureCtx && typeof document !== "undefined") {
    const canvas = document.createElement("canvas");
    measureCtx = canvas.getContext("2d");
  }
  if (measureCtx) {
    measureCtx.font = "700 13px 'Segoe UI', Arial, sans-serif";
    const w = measureCtx.measureText(text).width;
    return Math.min(BOX_MAX_W, Math.max(BOX_MIN_W, w + 40));
  }
  // canvas yoksa tahmini genişlik (fallback)
  const w = text.length * 8.1;
  return Math.min(BOX_MAX_W, Math.max(BOX_MIN_W, w + 40));
}

/* ---------- Yerleşim (archives ile birebir) ---------- */

function prepare(nodes: OutlineNode[], depth: number): void {
  nodes.forEach((n) => {
    n.w = measureWidth(n.text);
    n.depth = depth;
    if (n.children.length) {
      prepare(n.children, depth + 1);
    }
  });
}

function assignX(nodes: OutlineNode[], cursor: { val: number }): { val: number } {
  nodes.forEach((n) => {
    if (n.children.length) {
      cursor = assignX(n.children, cursor);
      const first = n.children[0];
      const last = n.children[n.children.length - 1];
      n.x = (first.x + last.x) / 2;
    } else {
      n.x = cursor.val + n.w / 2;
      cursor.val += n.w + SIB_GAP;
    }
  });
  return cursor;
}

function collect(nodes: OutlineNode[], out: OutlineNode[]): OutlineNode[] {
  nodes.forEach((n) => {
    out.push(n);
    if (n.children.length) {
      collect(n.children, out);
    }
  });
  return out;
}

function computeLayout(
  text: string,
): { all: OutlineNode[]; totalWidth: number; totalHeight: number } {
  const forest = parseOutline(text);
  if (forest.length === 0) {
    return { all: [], totalWidth: 0, totalHeight: 0 };
  }
  prepare(forest, 0);
  const cursor = { val: 0 };
  assignX(forest, cursor);
  const totalWidth = cursor.val - SIB_GAP;

  let maxDepth = 0;
  const all = collect(forest, []);
  all.forEach((n) => {
    n.y = n.depth * ROW_GAP;
    if (n.depth > maxDepth) {
      maxDepth = n.depth;
    }
  });
  const totalHeight = maxDepth * ROW_GAP + BOX_H + 20;
  return { all, totalWidth, totalHeight };
}

/* ---------- Bileşen ---------- */

const DEFAULT_OUTLINE = `SULTAN
-MELİK
--IKTA SİSTEMİ
-ATABEY
-DİVAN-I SALTANAT
--TUĞRACI
--PERVANE
---EMİR-İ DAD
--MÜSTEVFİ`;

const BOX_STYLE: JSX.CSSProperties = {
  position: "absolute",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  textAlign: "center",
  padding: "10px 14px",
  borderRadius: 10,
  fontSize: 13,
  fontWeight: 700,
  color: "#2b2320",
  background: "linear-gradient(180deg,#fbf4e4,#f4e8d0)",
  border: `2px solid ${BOX_BORDER}`,
  boxShadow: "0 3px 5px rgba(0,0,0,.12), inset 0 1px 0 rgba(255,255,255,.6)",
  lineHeight: 1.3,
  boxSizing: "border-box",
  zIndex: 1,
  wordBreak: "break-word",
  whiteSpace: "normal",
};

const SCHEMA_ANIM_CSS = `
@keyframes schemaBoxIn {
  from { opacity: 0; transform: scale(0.55); }
  to   { opacity: 1; transform: scale(1); }
}
@keyframes schemaLinkIn {
  from { opacity: 0; stroke-dashoffset: 120; }
  to   { opacity: 1; stroke-dashoffset: 0; }
}
`;

interface SchemaBuilderProps {
  /** Tire-tabanlı hiyerarşik metin (isteğe bağlı; varsayılan örnek) */
  outline?: string;
  /** Şema başlığı */
  title?: string;
  /** Editör modunda: kullanıcı metni düzenleyebilsin mi? */
  editable?: boolean;
  onChange?: (text: string) => void;
  /** Kutu sayısıyla sınırlı animasyonlu belirme (opsiyonel) */
  revealedCount?: number;
}

export function SchemaBuilder({
  outline,
  title = "ŞEMA",
  editable = false,
  onChange,
  revealedCount,
}: SchemaBuilderProps) {
  const [internalText, setInternalText] = useState<string>(outline ?? DEFAULT_OUTLINE);
  const text = outline ?? internalText;

  const { all, totalWidth, totalHeight } = useMemo(() => computeLayout(text), [text]);

  const handleEditorChange = (value: string) => {
    setInternalText(value);
    onChange?.(value);
  };

  // Animasyon: yalnızca ilk N kutu + iki ucu da görünen çizgiler
  const visibleSet =
    revealedCount !== undefined ? new Set(all.slice(0, revealedCount)) : null;
  // "Pat diye" değil, yumuşakça belirmesi için son eklenen öğeyi işaretle
  const lastIndex = revealedCount !== undefined ? revealedCount - 1 : -1;

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: 12,
        flex: 1,
        minWidth: 0,
        maxWidth: "100%",
        width: "100%",
        height: "100%",
        boxSizing: "border-box",
      }}
    >
      <style>{SCHEMA_ANIM_CSS}</style>

      {editable && (
        <textarea
          value={text}
          onInput={(e) => handleEditorChange((e.target as HTMLTextAreaElement).value)}
          placeholder={'Her satır bir kutu. Alt dal için satır başına "-" koy (ne kadar çok tire, o kadar derin).'}
          style={{
            width: "100%",
            maxWidth: "100%",
            minHeight: 140,
            fontFamily: "'Consolas','Courier New',monospace",
            fontSize: 13,
            padding: 10,
            border: "1px solid rgba(255,255,255,0.12)",
            borderRadius: 8,
            background: "rgba(0,0,0,0.4)",
            color: "#e2e8f0",
            resize: "vertical",
            whiteSpace: "pre",
            lineHeight: 1.5,
            boxSizing: "border-box",
          }}
        />
      )}

      {/* Şema tuvali — genişliği her zaman tam; içerik taşarsa scroll */}
      <div
        style={{
          position: "relative",
          flex: 1,
          minHeight: 320,
          minWidth: 0,
          width: "100%",
          maxWidth: "100%",
          overflow: "auto",
          background: "#f2e6cc",
          borderRadius: 12,
          padding: "30px 20px 50px 20px",
          boxSizing: "border-box",
        }}
      >
        {/* Başlık — boşsa gizli */}
        {title.trim() ? (
          <div
            style={{
              background: "#7a1414",
              color: "#fff",
              textAlign: "center",
              fontWeight: "bold",
              fontSize: 15,
              padding: "10px 24px",
              borderRadius: 5,
              margin: "0 auto 35px auto",
              width: "fit-content",
              minWidth: 280,
              letterSpacing: 0.5,
              boxShadow: "0 2px 4px rgba(0,0,0,.2)",
            }}
          >
            {title}
          </div>
        ) : null}

        {/* Şema alanı — genişliği her zaman tam; şema darsa ortalanır, genişse scroll */}
        <div
          style={{
            position: "relative",
            margin: "0 auto",
            width: "100%",
            height: all.length === 0 ? 200 : Math.max(totalHeight, 1),
          }}
        >
          {/* Boş şema durumu */}
          {all.length === 0 && (
            <div
              style={{
                position: "absolute",
                top: 40,
                left: 0,
                width: "100%",
                textAlign: "center",
                color: "#6b6252",
                fontSize: 13,
                fontStyle: "italic",
              }}
            >
              Şema oluşturmak için yukarıya hiyerarşik metin yazın
              <br />
              (satır başına "-" koyarak alt dal ekleyin)
            </div>
          )}

          {/* Merkez konteyner — şemanın gerçek genişliği; tuvalde ortalanır */}
          <div
            style={{
              position: "relative",
              margin: "0 auto",
              width: Math.max(totalWidth, 1),
              height: Math.max(totalHeight, 1),
            }}
          >
          {/* Eğri bağlantı çizgileri */}
          <svg
            width={totalWidth}
            height={totalHeight}
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              overflow: "visible",
              pointerEvents: "none",
            }}
          >
            {all.map((n, idx) =>
              n.children.map((c) => {
                const show = !visibleSet || (visibleSet.has(n) && visibleSet.has(c));
                if (!show) {
                  return null;
                }
                const x1 = n.x;
                const y1 = n.y + BOX_H;
                const x2 = c.x;
                const y2 = c.y;
                const midY = (y1 + y2) / 2;
                // Child yeni eklenen öğeyse çizgi "çizilme" animasyonu alır
                const cIdx = all.indexOf(c);
                const isNew = cIdx === lastIndex;
                return (
                  <path
                    key={`link-${idx}-${c.text}`}
                    d={`M ${x1} ${y1} C ${x1} ${midY}, ${x2} ${midY}, ${x2} ${y2}`}
                    fill="none"
                    stroke={LINE_COLOR}
                    strokeWidth={2.2}
                    strokeDasharray={isNew ? 120 : undefined}
                    strokeDashoffset={isNew ? 120 : undefined}
                    style={
                      isNew
                        ? {
                            animation: "schemaLinkIn 0.5s ease-out forwards",
                            opacity: 0,
                          }
                        : undefined
                    }
                  />
                );
              }),
            )}
          </svg>

          {/* Kutular */}
          {all.map((n, nIdx) => {
            if (visibleSet && !visibleSet.has(n)) {
              return null;
            }
            const isNew = nIdx === lastIndex;
            return (
              <div
                key={n.text}
                style={{
                  ...BOX_STYLE,
                  left: n.x - n.w / 2,
                  top: n.y,
                  width: n.w,
                  height: BOX_H,
                  ...(isNew
                    ? {
                        transformOrigin: "center",
                        animation: "schemaBoxIn 0.45s ease-out forwards",
                        opacity: 0,
                      }
                    : {}),
                }}
              >
                {n.text}
              </div>
            );
          })}
          </div>
        </div>

        {/* Sayaç */}
        {revealedCount !== undefined && (
          <div
            style={{
              marginTop: 14,
              fontSize: 11.5,
              color: "#6b6252",
              fontVariantNumeric: "tabular-nums",
            }}
          >
            {Math.min(revealedCount, all.length)} / {all.length}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * StateStructureOutline.ts
 * Devlet Teşkilatı şema verisi — SchemaBuilder tarafından tüketilen saf metin outline.
 * Tarih haritası şeması için ayrı veri dosyası (HistoryMapView içine gömülü değil).
 * Tire sayısı = hiyerarşi derinliği. Toplam 9 düğüm.
 * Kaynak: archives/kpss-sema-olusturucu-v2.html örnek formatı.
 */
export const TESKILAT_OUTLINE = `Sultan
-Melik
--Ikta Sistemi
-Atabey
-Divan-ı Saltanat
--Tuğracı
--Pervane
---Emir-i Dad
--Müstevfi`;

/** Şema başlığı (SchemaBuilder title prop'u) */
export const TESKILAT_TITLE = "SELÇUKLU DEVLET TEŞKİLATI ŞEMASI";

/** Outline düğüm sayısı (satır sayısı) — SchemaBuilder kutu sayısıyla senkron */
export function countOutlineLines(outline: string): number {
  return outline.split("\n").filter((l) => l.trim().length > 0).length;
}

/**
 * TurkeyMapView.tsx
 * Türkiye Fiziki Haritası — konu seçici (volkanik dağlar, ovalar, göller, akarsular, platolar).
 * Video oynatıcı mantığı: ileri/geri sarma, fullscreen, başlangıçta tüm pinler görünür.
 * Veri: src/domain/constants/TurkeyGeographyData.ts + TurkeyProvincePaths.ts
 * Parçalar: MapControls, MapTopicSidebar, MapCanvas, useMapPlayback (ortak mantık).
 */
import { useEffect, useMemo, useState } from "preact/hooks";
import {
  MAP_TOPICS,
  TOPIC_PINS,
  VOLCANIC_MOUNTAINS,
  TurkeyMapTopic,
} from "@/domain/constants/TurkeyGeographyData.js";
import { MapControls } from "./MapControls.js";
import { MapTopicSidebar } from "./MapTopicSidebar.js";
import { MapCanvas } from "./MapCanvas.js";
import { useMapPlayback } from "./useMapPlayback.js";

interface TurkeyMapViewProps {
  t: Record<string, string>;
}

const STEP_MS = 1500;

const TOPIC_TITLE_KEYS: Record<TurkeyMapTopic, string> = {
  volcanic: "kpss_map_title_volcanic",
  plains: "kpss_map_title_plains",
  lakes: "kpss_map_title_lakes",
  rivers: "kpss_map_title_rivers",
  plateaus: "kpss_map_title_plateaus",
};

export function TurkeyMapView({ t }: TurkeyMapViewProps) {
  const [selectedTopic, setSelectedTopic] =
    useState<TurkeyMapTopic>("volcanic");
  // Başlangıçta tüm pinler görünür (göz aşinalığı) — play basınca 0'dan başlar
  const playback = useMapPlayback({
    initialCount: VOLCANIC_MOUNTAINS.length,
    stepMs: STEP_MS,
  });
  const {
    revealedCount,
    currentIndex,
    playing,
    isFullscreen,
    view,
    containerRef,
    svgWrapRef,
    total,
    setTotal,
    handleUnitChange,
    handlePlay,
    handleStep,
    handleReset,
    toggleFullscreen,
    onPointerDown,
    onPointerMove,
    onPointerUp,
    onWheel,
  } = playback;

  const pins = TOPIC_PINS[selectedTopic];
  const topicMeta = MAP_TOPICS.find((m) => m.id === selectedTopic) || MAP_TOPICS[0];
  const topicColor = topicMeta.color;

  // Seçili konu değişince toplam pin sayısını senkronla
  const nextTotal = pins.length;
  useEffect(() => {
    if (total !== nextTotal) {
      setTotal(nextTotal);
    }
  }, [total, nextTotal, setTotal]);

  const handleTopicChange = (topic: TurkeyMapTopic) => {
    if (topic === selectedTopic) {
      return;
    }
    setSelectedTopic(topic);
    // Yeni konu da son haliyle (tüm pinler) açılır
    handleUnitChange(TOPIC_PINS[topic].length);
  };

  const title = useMemo(
    () =>
      t[TOPIC_TITLE_KEYS[selectedTopic]] ||
      t.kpss_map_title ||
      "Türkiye Fiziki Haritası",
    [t, selectedTopic],
  );

  return (
    <div
      ref={containerRef}
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "12px",
        width: "100%",
        ...(isFullscreen
          ? {
              height: "100vh",
              boxSizing: "border-box",
              padding: "24px",
              background: "linear-gradient(160deg, #0f172a 0%, #1e293b 100%)",
              overflow: "auto",
            }
          : {}),
      }}
    >
      {/* Harita Başlığı + Kontroller */}
      <MapControls
        t={t}
        title={title}
        total={total}
        revealedCount={revealedCount}
        playing={playing}
        isFullscreen={isFullscreen}
        onStep={handleStep}
        onReset={() => handleReset(total)}
        onPlayToggle={handlePlay}
        onToggleFullscreen={toggleFullscreen}
      />

      {/* Konu Seçici + Harita */}
      <div
        style={{
          display: "flex",
          gap: "12px",
          alignItems: "stretch",
          flex: isFullscreen ? 1 : undefined,
        }}
      >
        {/* Sol Sidebar: Konu Listesi */}
        <MapTopicSidebar
          t={t}
          selectedTopic={selectedTopic}
          onSelect={handleTopicChange}
        />

        {/* Harita Gövdesi */}
        <MapCanvas
          t={t}
          topicColor={topicColor}
          legendKey={topicMeta.legendKey}
          pins={pins}
          revealedCount={revealedCount}
          currentIndex={currentIndex}
          isFullscreen={isFullscreen}
          svgWrapRef={svgWrapRef}
          view={view}
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={onPointerUp}
          onWheel={onWheel}
        />
      </div>

      {/* @keyframes tanımı (global CSS'e eklenir) */}
      <style>{`
        @keyframes mapPulse {
          0% { opacity: 0.55; transform: scale(0.6); }
          100% { opacity: 0; transform: scale(2.4); }
        }
      `}</style>
    </div>
  );
}

/**
 * KpssExternalResultModal.tsx
 * Harici AI sınavı tamamlandıktan sonra kullanıcının kaç doğru yaptığını
 * gireceği premium sonuç giriş ekranı.
 */

import { useState } from "preact/hooks";

interface KpssExternalResultModalProps {
  t: Record<string, string>;
  totalCount: number;
  onSave: (correct: number, total: number) => void;
  onBack: () => void;
}

export function KpssExternalResultModal({
  t,
  totalCount,
  onSave,
  onBack,
}: KpssExternalResultModalProps) {
  const [total, setTotal] = useState(totalCount);
  const [correct, setCorrect] = useState(0);

  const wrong = Math.max(0, total - correct);
  const scorePercent = total > 0 ? Math.round((correct / total) * 100) : 0;

  const scoreColor =
    scorePercent >= 80
      ? "#10b981"
      : scorePercent >= 40
        ? "#f59e0b"
        : scorePercent > 0
          ? "#ef4444"
          : "var(--text-secondary)";

  const scoreLabel =
    scorePercent >= 80
      ? "Mükemmel"
      : scorePercent >= 60
        ? "İyi"
        : scorePercent >= 40
          ? "Geliştirilmeli"
          : scorePercent > 0
            ? "Tekrar Et"
            : "—";

  const handleSave = () => {
    if (total > 0) {
      onSave(correct, total);
    }
  };

  const clampCorrect = (val: number) => Math.max(0, Math.min(val, total));

  // Skor çarkı için stroke-dasharray hesabı
  const radius = 44;
  const circumference = 2 * Math.PI * radius;
  const dashOffset = circumference - (scorePercent / 100) * circumference;

  return (
    <div class="kpss-ext-result">
      {/* Başlık */}
      <div class="kpss-ext-result__header">
        <h4 class="kpss-ext-result__title">
          {t.kpss_external_quiz_enter_result}
        </h4>
        <p class="kpss-ext-result__desc">{t.kpss_external_quiz_result_desc}</p>
      </div>

      {/* Skor çemberi + Input alanları yan yana */}
      <div class="kpss-ext-result__main">
        {/* SVG Skor Çemberi */}
        <div class="kpss-ext-result__ring-wrap">
          <svg class="kpss-ext-result__ring" viewBox="0 0 100 100">
            {/* Arka iz */}
            <circle
              cx="50"
              cy="50"
              r={radius}
              fill="none"
              stroke="rgba(255,255,255,0.06)"
              stroke-width="8"
            />
            {/* Aktif yay */}
            <circle
              cx="50"
              cy="50"
              r={radius}
              fill="none"
              stroke={scorePercent > 0 ? scoreColor : "rgba(255,255,255,0.06)"}
              stroke-width="8"
              stroke-linecap="round"
              stroke-dasharray={circumference}
              stroke-dashoffset={dashOffset}
              style={{
                transform: "rotate(-90deg)",
                transformOrigin: "50% 50%",
                transition:
                  "stroke-dashoffset 0.5s cubic-bezier(0.4,0,0.2,1), stroke 0.3s ease",
              }}
            />
            {/* Merkez metin */}
            <text
              x="50"
              y="44"
              text-anchor="middle"
              font-size="18"
              font-weight="800"
              fill={scorePercent > 0 ? scoreColor : "rgba(255,255,255,0.3)"}
              font-family="inherit"
            >
              {scorePercent > 0 ? `%${scorePercent}` : "—"}
            </text>
            <text
              x="50"
              y="60"
              text-anchor="middle"
              font-size="7.5"
              font-weight="600"
              fill="rgba(255,255,255,0.45)"
              font-family="inherit"
            >
              {scoreLabel}
            </text>
          </svg>
        </div>

        {/* Input alanları */}
        <div class="kpss-ext-result__fields">
          {/* Toplam Soru */}
          <div class="kpss-ext-result__field">
            <label class="kpss-ext-result__label">
              {t.kpss_external_quiz_total}
            </label>
            <div class="kpss-ext-result__input-wrap">
              <input
                type="number"
                class="kpss-ext-result__input"
                value={total}
                min={1}
                max={100}
                onInput={(e) => {
                  const v =
                    parseInt((e.target as HTMLInputElement).value, 10) || 1;
                  setTotal(v);
                  setCorrect((prev) => Math.min(prev, v));
                }}
              />
              <span class="kpss-ext-result__input-unit">
                {t.kpss_quiz_questions}
              </span>
            </div>
          </div>

          {/* Doğru Sayısı */}
          <div class="kpss-ext-result__field">
            <label class="kpss-ext-result__label" style={{ color: "#10b981" }}>
              {t.kpss_external_quiz_correct}
            </label>
            <div class="kpss-ext-result__input-wrap">
              <input
                type="number"
                class="kpss-ext-result__input kpss-ext-result__input--correct"
                value={correct}
                min={0}
                max={total}
                onInput={(e) => {
                  const v =
                    parseInt((e.target as HTMLInputElement).value, 10) || 0;
                  setCorrect(clampCorrect(v));
                }}
              />
              <span
                class="kpss-ext-result__input-unit"
                style={{ color: "#10b981" }}
              >
                ✓
              </span>
            </div>
          </div>

          {/* Yanlış — readonly gösterim */}
          <div class="kpss-ext-result__field">
            <label class="kpss-ext-result__label" style={{ color: "#ef4444" }}>
              {t.kpss_external_quiz_wrong}
            </label>
            <div class="kpss-ext-result__input-wrap">
              <div class="kpss-ext-result__input kpss-ext-result__input--wrong kpss-ext-result__readonly">
                {wrong}
              </div>
              <span
                class="kpss-ext-result__input-unit"
                style={{ color: "#ef4444" }}
              >
                ✗
              </span>
            </div>
          </div>
        </div>
      </div>

      {/* Detay bar */}
      <div class="kpss-ext-result__bar-wrap">
        <div
          class="kpss-ext-result__bar-fill"
          style={{
            width: `${scorePercent}%`,
            background: `linear-gradient(90deg, ${scoreColor}bb, ${scoreColor})`,
          }}
        />
        <div
          class="kpss-ext-result__bar-fill kpss-ext-result__bar-fill--wrong"
          style={{
            width: `${total > 0 ? (wrong / total) * 100 : 0}%`,
            marginLeft: `${scorePercent}%`,
          }}
        />
      </div>

      {/* Aksiyon butonları */}
      <div style={{ display: "flex", gap: "10px" }}>
        <button class="kpss-qcount-btn" style={{ flex: 1 }} onClick={onBack}>
          {t.kpss_external_quiz_back}
        </button>
        <button
          class="settings-add-btn"
          style={{ flex: 2, padding: "0 16px" }}
          disabled={total === 0 || correct === 0}
          onClick={handleSave}
        >
          {t.kpss_external_quiz_save}
        </button>
      </div>
    </div>
  );
}

import { CSSProperties } from "preact";

/**
 * KpssQuizQuestionsStep.tsx
 * KPSS Sınavı sorularının gösterim ekranı (İlerleme çubuğu, Canvas, Harita, Şıklar, Çözüm kutusu ve Navigasyon).
 */

import { useEffect, useState } from "preact/hooks";
import { KpssQuestionCanvas } from "@/components/kpss/topics/KpssQuestionCanvas.js";
import { KpssQuestionMap } from "@/components/kpss/exams/KpssQuestionMap.js";
import { MathRenderer } from "@/components/kpss/quiz/MathRenderer.js";

export interface QuizQuestion {
  question: string;
  options: string[];
  correctAnswer: number;
  solution: string;
  chart?: {
    type: "bar" | "line" | "geometry";
    title?: string;
    labels?: string[];
    values?: (number | string)[];
    shape?: "triangle" | "circle" | "parallel_lines";
    angles?: Record<string, string>;
    sides?: Record<string, string>;
  };
  map?: {
    highlightRegions?: string[];
    markers?: Array<{ x: number; y: number; label: string }>;
  };
}

interface KpssQuizQuestionsStepProps {
  t: Record<string, string>;
  quizLoading: boolean;
  quizError: string | null;
  quizQuestions: QuizQuestion[];
  currentQuestionIndex: number;
  selectedAnswers: number[];
  totalQuizLength: number;
  onStartQuiz: () => void;
  onSelectAnswer: (oIdx: number) => void;
  onPreviousQuestion: () => void;
  onNextQuestion: () => void;
  onFinishQuiz: () => void;
}

export function KpssQuizQuestionsStep({
  t,
  quizLoading,
  quizError,
  quizQuestions,
  currentQuestionIndex,
  selectedAnswers,
  totalQuizLength,
  onStartQuiz,
  onSelectAnswer,
  onPreviousQuestion,
  onNextQuestion,
  onFinishQuiz,
}: KpssQuizQuestionsStepProps) {
  // Zamanlayıcı: her soru için 1 dk (5 soru=5dk, 10=10dk...). Süre bitince otomatik sonuç.
  const [remainingSec, setRemainingSec] = useState(totalQuizLength * 60);

  useEffect(() => {
    setRemainingSec(totalQuizLength * 60);
  }, [totalQuizLength]);

  useEffect(() => {
    if (quizLoading || quizError || quizQuestions.length === 0) {
      return;
    }
    if (remainingSec <= 0) {
      onFinishQuiz();
      return;
    }
    const timer = window.setInterval(() => {
      setRemainingSec((s) => Math.max(0, s - 1));
    }, 1000);
    return () => window.clearInterval(timer);
  }, [remainingSec, quizLoading, quizError, quizQuestions.length]);

  const fmt = (sec: number) => {
    const m = Math.floor(sec / 60);
    const s = sec % 60;
    return `${m}:${s.toString().padStart(2, "0")}`;
  };

  if (quizLoading) {
    return (
      <div className="ha-loading" style={{ minHeight: "200px" }}>
        <div className="ha-spinner" />
        <span style={{ fontSize: "0.95rem" }}>{t.kpss_quiz_generating}</span>
      </div>
    );
  }

  if (quizError) {
    return (
      <div className="ha-error" style={{ minHeight: "200px" }}>
        <span>{quizError}</span>
        <button className="ha-retry-btn" onClick={onStartQuiz}>
          {t.kpss_quiz_retry}
        </button>
      </div>
    );
  }

  if (quizQuestions.length === 0) {
    return null;
  }

  const currentQ = quizQuestions[currentQuestionIndex];
  const isAnswered = selectedAnswers[currentQuestionIndex] !== -1;

  return (
    <div>
      <div className="kpss-quiz-progress-bar-container">
        <div
          className="kpss-quiz-progress-fill"
          style={{
            width: `${((currentQuestionIndex + 1) / totalQuizLength) * 100}%`,
          }}
        />
      </div>

      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          fontSize: "0.85rem",
          opacity: 0.6,
          marginBottom: "8px",
        }}
      >
        <span>
          {`${t.kpss_quiz_questions} ${currentQuestionIndex + 1} / ${totalQuizLength}`}
        </span>
        {/* Zamanlayıcı — süre bitince otomatik sonuç */}
        <span
          style={{
            fontWeight: 700,
            fontVariantNumeric: "tabular-nums",
            color: remainingSec <= 60 ? "#f87171" : "inherit",
          }}
        >
          ⏱ {fmt(remainingSec)}
        </span>
      </div>

      {currentQ.chart && <KpssQuestionCanvas chart={currentQ.chart} />}
      {currentQ.map && <KpssQuestionMap map={currentQ.map} />}

      <div className="kpss-quiz-question-container">
        <div className="kpss-quiz-question-text">
          <MathRenderer text={currentQ.question} />
        </div>
      </div>

      <div className="kpss-quiz-options-grid">
        {currentQ.options.map((opt, oIdx) => {
          const letter = ["A", "B", "C", "D", "E"][oIdx];
          const isSelected = selectedAnswers[currentQuestionIndex] === oIdx;
          const isCorrect = oIdx === currentQ.correctAnswer;

          let cardStyle: Record<string, string | number> = {
            transition: "all 0.2s ease",
          };

          if (isAnswered) {
            if (isCorrect) {
              cardStyle = {
                ...cardStyle,
                border: "1px solid rgba(16, 185, 129, 0.4)",
                background: "rgba(16, 185, 129, 0.08)",
                color: "#34d399",
                cursor: "default",
              };
            } else if (isSelected) {
              cardStyle = {
                ...cardStyle,
                border: "1px solid rgba(239, 68, 68, 0.4)",
                background: "rgba(239, 68, 68, 0.08)",
                color: "#f87171",
                cursor: "default",
              };
            } else {
              cardStyle = {
                ...cardStyle,
                opacity: 0.4,
                cursor: "default",
              };
            }
          }

          return (
            <div
              key={oIdx}
              className={`kpss-quiz-option-card ${isSelected && !isAnswered ? "selected" : ""}`}
              style={cardStyle}
              onClick={() => onSelectAnswer(oIdx)}
            >
              <div
                className="kpss-quiz-option-letter"
                style={
                  isAnswered && isCorrect
                    ? { background: "#10b981", color: "white" }
                    : isAnswered && isSelected
                      ? { background: "#ef4444", color: "white" }
                      : {}
                }
              >
                {letter}
              </div>
              <span>
                <MathRenderer text={opt} />
              </span>
            </div>
          );
        })}
      </div>

      {/* Solution display box */}
      {isAnswered && (
        <div
          style={{
            marginTop: "16px",
            padding: "12px 16px",
            background: "rgba(255, 255, 255, 0.03)",
            borderLeft: "4px solid var(--accent-color)",
            borderRadius: "8px",
            fontSize: "0.82rem",
            lineHeight: 1.5,
            color: "rgba(255, 255, 255, 0.7)",
            textAlign: "left",
          }}
        >
          <div
            style={{
              fontWeight: "700",
              color: "var(--accent-color)",
              marginBottom: "4px",
            }}
          >
            {t.kpss_quiz_solution}
          </div>
          <MathRenderer text={currentQ.solution || t.kpss_quiz_no_solution} />
        </div>
      )}

      <div style={{ display: "flex", gap: "12px", marginTop: "24px" }}>
        <button
          className="kpss-qcount-btn"
          style={{ flex: 1 }}
          disabled={currentQuestionIndex === 0}
          onClick={onPreviousQuestion}
        >
          {t.kpss_quiz_previous}
        </button>
        {currentQuestionIndex < totalQuizLength - 1 ? (
          <button
            className={`settings-add-btn ${currentQuestionIndex >= quizQuestions.length - 1 ? "loading" : ""}`}
            style={{ flex: 1, padding: 0 }}
            disabled={
              selectedAnswers[currentQuestionIndex] === -1 ||
              currentQuestionIndex >= quizQuestions.length - 1
            }
            onClick={onNextQuestion}
          >
            {currentQuestionIndex >= quizQuestions.length - 1 ? (
              <span
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: "6px",
                }}
              >
                <span className="kpss-btn-loader" />
                {t.kpss_quiz_next_loading}
              </span>
            ) : (
              t.kpss_quiz_next
            )}
          </button>
        ) : (
          <button
            className="settings-add-btn"
            style={{ flex: 1, padding: 0 }}
            disabled={selectedAnswers[currentQuestionIndex] === -1}
            onClick={onFinishQuiz}
          >
            {t.kpss_quiz_finish}
          </button>
        )}
      </div>
    </div>
  );
}

/**
 * KpssQuizResultStep.tsx
 * KPSS Sınavı tamamlanma ekranı (Skor yüzdesi, pop-up soru inceleme butonu, aksiyonlar).
 */
import { useState } from "preact/hooks";
import type { QuizQuestion } from "@/components/kpss/quiz/KpssQuizQuestionsStep.js";
import { QuizResultHero } from "./QuizResultHero.js";
import { QuizResultActions } from "./QuizResultActions.js";
import { KpssQuizReviewModal } from "./KpssQuizReviewModal.js";

import { KpssPastQuizSession } from "@/services/kpss/kpssQuizService.js";

interface KpssQuizResultStepProps {
  lang: string;
  t: Record<string, string>;
  currentSubject: string;
  activeQuizTopic: string | null;
  quizResultScore: number;
  cumulative: { totalQuestions: number; totalCorrect: number };
  quizQuestions: QuizQuestion[];
  selectedAnswers: number[];
  historySessions?: KpssPastQuizSession[];
  subjectNames: Record<string, string>;
  onRetakeQuiz: () => void;
  onClose: () => void;
}

export function KpssQuizResultStep({
  lang,
  t,
  currentSubject,
  activeQuizTopic,
  quizResultScore,
  cumulative,
  quizQuestions,
  selectedAnswers,
  historySessions,
  subjectNames,
  onRetakeQuiz,
  onClose,
}: KpssQuizResultStepProps) {
  const [showReviewModal, setShowReviewModal] = useState(false);

  const handleExportTxt = () => {
    let text = `Sınav Raporu\n`;
    text += `Ders: ${subjectNames[currentSubject] || currentSubject}\n`;
    text += `Konu: ${activeQuizTopic}\n`;
    text += `Skor: %${quizResultScore}\n`;
    text += `Tarih: ${new Date().toLocaleDateString(lang === "tr" ? "tr-TR" : "en-US")}\n`;
    text += `=========================================\n\n`;

    quizQuestions.forEach((q, idx) => {
      const userAnsIdx = selectedAnswers[idx];
      const correctAnsIdx = q.correctAnswer;
      const letters = ["A", "B", "C", "D", "E"];

      text += `Soru ${idx + 1}: ${q.question}\n`;
      q.options.forEach((opt, oIdx) => {
        text += `${letters[oIdx]}) ${opt}\n`;
      });
      text += `-----------------------------------------\n`;
      text += `Sizin Cevabınız: ${userAnsIdx !== -1 ? letters[userAnsIdx] : "Boş"}\n`;
      text += `Doğru Cevap: ${letters[correctAnsIdx]}\n`;
      text += `Çözüm: ${q.solution || "Açıklama bulunmuyor."}\n`;
      text += `=========================================\n\n`;
    });

    const blob = new Blob([text], {
      type: "text/plain;charset=utf-8",
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `Sinav_${currentSubject}_${activeQuizTopic?.replace(/\s+/g, "_")}.txt`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const correctCount = selectedAnswers.filter(
    (ans, idx) => ans === quizQuestions[idx]?.correctAnswer,
  ).length;
  const totalQuestions = quizQuestions.length;

  // Birikimli başarı: konu tamamlanması için min 100 soru + %80 şartı
  const cumTotal = cumulative?.totalQuestions ?? 0;
  const cumCorrect = cumulative?.totalCorrect ?? 0;
  const cumPercent =
    cumTotal >= 100
      ? Math.round((cumCorrect / cumTotal) * 100)
      : cumTotal > 0
        ? Math.round((cumCorrect / cumTotal) * 100)
        : 0;
  const cumPassed = cumTotal >= 100 && cumPercent >= 80;
  const barPct = Math.min(100, Math.round((cumTotal / 100) * 100));

  return (
    <div style={{ padding: "4px" }}>
      {/* ─── Unified Score & Dual Progress Hero ─── */}
      <QuizResultHero
        t={t}
        score={quizResultScore}
        correctCount={correctCount}
        totalQuestions={totalQuestions}
        cumulative={cumulative}
      />

      {/* ─── Actions ─── */}
      <QuizResultActions
        t={t}
        hasPastQuestions={
          quizQuestions.length > 0 || (historySessions && historySessions.length > 0)
        }
        onReviewQuestions={() => setShowReviewModal(true)}
        onRetakeQuiz={onRetakeQuiz}
      />

      {/* ─── Soruları İncele Pop-up Modali ─── */}
      {showReviewModal && (
        <KpssQuizReviewModal
          lang={lang}
          t={t}
          subjectTitle={subjectNames[currentSubject] || currentSubject}
          topicTitle={activeQuizTopic || ""}
          score={quizResultScore}
          quizQuestions={quizQuestions}
          selectedAnswers={selectedAnswers}
          historySessions={historySessions}
          onClose={() => setShowReviewModal(false)}
          onRetake={onRetakeQuiz}
          onExport={handleExportTxt}
        />
      )}
    </div>
  );
}

