      text += `Sizin Cevabınız: ${userAnsIdx !== -1 && userAnsIdx !== undefined ? letters[userAnsIdx] : "Boş"}\n`;
      text += `Doğru Cevap: ${letters[correctAnsIdx]}\n`;
      text += `Çözüm: ${q.solution || "Açıklama bulunmuyor."}\n`;
