/**
 * AddStockModal.tsx
 * Takip edilen veya satın alınan BIST hissesi ekleme modali.
 */

import { useState, useEffect } from "preact/hooks";
import { fetchDynamicBistTickers } from "@/services/bistService.js";
import type { StockPortfolioItem } from "@/types/stock.js";

interface AddStockModalProps {
  initialSymbol?: string;
  onSave: (item: Omit<StockPortfolioItem, "id">) => void;
  onClose: () => void;
}

function IconX() {
  return (
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <line x1="18" y1="6" x2="6" y2="18" />
      <line x1="6" y1="6" x2="18" y2="18" />
    </svg>
  );
}

export function AddStockModal({
  initialSymbol,
  onSave,
  onClose,
}: AddStockModalProps) {
  const [selectedStock, setSelectedStock] = useState<string>("THYAO.IS");
  const [customSymbol, setCustomSymbol] = useState<string>(initialSymbol || "");
  const [useCustom, setUseCustom] = useState<boolean>(Boolean(initialSymbol));
  const [displayName, setDisplayName] = useState<string>(initialSymbol || "");
  const [buyPrice, setBuyPrice] = useState<number>(0);
  const [lotCount, setLotCount] = useState<number>(0);
  const [note, setNote] = useState<string>("");
  const [tickers, setTickers] = useState<string[]>([
    "THYAO.IS",
    "GARAN.IS",
    "AKBNK.IS",
    "EREGL.IS",
    "ASELS.IS",
  ]);

  useEffect(() => {
    fetchDynamicBistTickers().then((list) => {
      if (list && list.length > 0) {
        setTickers(list);
      }
    });
  }, []);

  const handleSubmit = (e: Event) => {
    e.preventDefault();

    const rawSym = useCustom ? customSymbol.trim() : selectedStock;
    if (!rawSym) {
      return;
    }

    let fullSym = rawSym.toUpperCase();
    if (!fullSym.endsWith(".IS")) {
      fullSym += ".IS";
    }

    const finalName = displayName.trim() || fullSym.replace(".IS", "");

    onSave({
      symbol: fullSym,
      displayName: finalName,
      buyPrice: Math.max(0, buyPrice),
      lotCount: Math.max(0, lotCount),
      buyDate: new Date().toISOString().split("T")[0],
      note: note.trim() || undefined,
    });

    onClose();
  };

  return (
    <div className="stock-modal-overlay" onClick={onClose}>
      <div className="stock-modal-content" onClick={(e) => e.stopPropagation()}>
        <div className="stock-modal-header">
          <div className="stock-modal-title">Portföye Hisse Ekle</div>
          <button
            style={{
              background: "none",
              border: "none",
              color: "#94a3b8",
              cursor: "pointer",
            }}
            onClick={onClose}
          >
            <IconX />
          </button>
        </div>

        <form
          onSubmit={handleSubmit}
          style={{ display: "flex", flexDirection: "column", gap: "14px" }}
        >
          <div className="stock-form-group">
            <label className="stock-form-label">Hisse Seçimi</label>
            {!useCustom ? (
              <select
                className="stock-select"
                value={selectedStock}
                onChange={(e) =>
                  setSelectedStock((e.target as HTMLSelectElement).value)
                }
              >
                {tickers.map((sym) => (
                  <option key={sym} value={sym}>
                    {sym.replace(".IS", "")}
                  </option>
                ))}
              </select>
            ) : (
              <input
                type="text"
                className="stock-input"
                placeholder="Hisse Kodu (Örn: KRDMD, SASA, EREGL)"
                value={customSymbol}
                onInput={(e) =>
                  setCustomSymbol((e.target as HTMLInputElement).value)
                }
                required
              />
            )}
            <button
              type="button"
              style={{
                background: "none",
                border: "none",
                color: "#818cf8",
                fontSize: "0.78rem",
                textAlign: "left",
                cursor: "pointer",
                padding: "2px 0",
              }}
              onClick={() => setUseCustom(!useCustom)}
            >
              {useCustom
                ? "← Popüler hisselerden seç"
                : "+ Farklı BIST hisse koda sahip ol (Özel kod gir)"}
            </button>
          </div>

          <div className="stock-form-group">
            <label className="stock-form-label">
              Şirket Adı (İsteğe Bağlı)
            </label>
            <input
              type="text"
              className="stock-input"
              placeholder="Örn: Kardemir D"
              value={displayName}
              onInput={(e) =>
                setDisplayName((e.target as HTMLInputElement).value)
              }
            />
          </div>

          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr",
              gap: "12px",
            }}
          >
            <div className="stock-form-group">
              <label className="stock-form-label">Alış Fiyatı (TL)</label>
              <input
                type="number"
                step="0.01"
                min="0"
                className="stock-input"
                placeholder="0.00"
                value={buyPrice || ""}
                onInput={(e) =>
                  setBuyPrice(
                    parseFloat((e.target as HTMLInputElement).value) || 0,
                  )
                }
              />
            </div>

            <div className="stock-form-group">
              <label className="stock-form-label">Adet / Lot</label>
              <input
                type="number"
                min="0"
                className="stock-input"
                placeholder="0"
                value={lotCount || ""}
                onInput={(e) =>
                  setLotCount(
                    parseInt((e.target as HTMLInputElement).value, 10) || 0,
                  )
                }
              />
            </div>
          </div>

          <div className="stock-form-group">
            <label className="stock-form-label">Not (İsteğe Bağlı)</label>
            <input
              type="text"
              className="stock-input"
              placeholder="Örn: Halka arz katılımı / 1. kademe alım"
              value={note}
              onInput={(e) => setNote((e.target as HTMLInputElement).value)}
            />
          </div>

          <div
            style={{
              display: "flex",
              justifyContent: "flex-end",
              gap: "10px",
              marginTop: "10px",
            }}
          >
            <button
              type="button"
              className="stock-btn stock-btn-secondary"
              onClick={onClose}
            >
              İptal
            </button>
            <button type="submit" className="stock-btn stock-btn-primary">
              Portföye Ekle
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

import type { StockQuote } from "@/types/bist.js";
import { formatPrice } from "@/services/bistService.js";
import type { StockPortfolioItem, StockRule } from "@/types/stock.js";
import { IconChart, IconPlus, IconSparkles, IconSell } from "./portfolioIcons.js";

interface PortfolioRowProps {
  item: StockPortfolioItem;
  quoteMap: Map<string, StockQuote>;
  rules: StockRule[];
  onAddRuleClick: (symbol: string) => void;
  onDeleteRule?: (ruleId: string) => void;
  onDeleteItem: (id: string) => void;
  onSellItem: (
    id: string,
    symbol: string,
    currentLot: number,
    currentPrice: number,
  ) => void;
  onAiAnalyzeClick: (symbol: string) => void;
  onOpenChart: (symbol: string) => void;
}

export function PortfolioRow({
  item,
  quoteMap,
  rules,
  onAddRuleClick,
  onDeleteRule,
  onDeleteItem,
  onSellItem,
  onAiAnalyzeClick,
  onOpenChart,
}: PortfolioRowProps) {
  const sym = item.symbol.replace(/\.IS$/, "").toUpperCase();
  const quote = quoteMap.get(sym);
  const hasLivePrice = Boolean(quote && quote.price > 0);
  const currentPrice = hasLivePrice ? quote!.price : item.buyPrice;
  const changePct = hasLivePrice ? quote!.changePercent : 0;
  const isTavan = changePct >= 9.5;
  const isPositive = changePct >= 0;
  const totalVal = currentPrice * item.lotCount;
  const costVal = item.buyPrice * item.lotCount;
  const profit = hasLivePrice ? totalVal - costVal : 0;
  const profitPct = hasLivePrice && costVal > 0 ? (profit / costVal) * 100 : 0;
  const symbolRules = rules.filter(
    (r) =>
      r.symbol.replace(/\.IS$/, "").toUpperCase() === sym && r.isActive,
  );

  return (
    <tr key={item.id}>
      <td
        style={{ textAlign: "left", cursor: "pointer" }}
        onClick={() => onOpenChart(sym)}
        title="Grafik Görüntüle"
      >
        <div style={{ fontWeight: 700, color: "#f8fafc" }}>{sym}</div>
        <div style={{ fontSize: "0.75rem", color: "#94a3b8" }}>
          {item.displayName}
        </div>
      </td>
      <td style={{ textAlign: "right", fontWeight: 600 }}>
        {hasLivePrice ? formatPrice(currentPrice) : "—"}
      </td>
      <td style={{ textAlign: "center" }}>
        <span
          className={`stock-card-badge ${
            !hasLivePrice
              ? "stock-badge-neutral"
              : isTavan
                ? "stock-badge-tavan"
                : isPositive
                  ? "stock-badge-positive"
                  : "stock-badge-negative"
          }`}
        >
          {!hasLivePrice
            ? "0.00% (Açılış Bekleniyor)"
            : `${isTavan ? "Tavan " : ""}${isPositive ? "+" : ""}${changePct.toFixed(2)}%`}
        </span>
      </td>
      <td style={{ textAlign: "right" }}>
        {item.buyPrice > 0 ? formatPrice(item.buyPrice) : "—"}
      </td>
      <td style={{ textAlign: "center", whiteSpace: "nowrap" }}>
        <span
          style={{
            fontWeight: 700,
            padding: "3px 8px",
            borderRadius: "6px",
            background: "rgba(255, 255, 255, 0.06)",
            color: "#e2e8f0",
            fontSize: "0.85rem",
          }}
        >
          {item.lotCount.toLocaleString("tr-TR")} Lot
        </span>
      </td>
      <td style={{ textAlign: "right", fontWeight: 600 }}>
        {formatPrice(totalVal)}
      </td>
      <td style={{ textAlign: "right", whiteSpace: "nowrap" }}>
        <span
          className={
            !hasLivePrice
              ? "stock-badge-neutral"
              : profit >= 0
                ? "stock-badge-positive"
                : "stock-badge-negative"
          }
        >
          {!hasLivePrice
            ? "0,00 ₺ (0.00%)"
            : `${profit >= 0 ? "+" : ""}${formatPrice(profit)} (${profitPct.toFixed(1)}%)`}
        </span>
      </td>
      <td>
        <div style={{ display: "flex", gap: "4px", flexWrap: "wrap" }}>
          {symbolRules.length > 0 ? (
            symbolRules.map((r) => (
              <span
                key={r.id}
                style={{
                  fontSize: "0.7rem",
                  padding: "2px 6px",
                  borderRadius: "6px",
                  background: "rgba(99, 102, 241, 0.2)",
                  color: "#818cf8",
                  border: "1px solid rgba(99, 102, 241, 0.4)",
                  display: "inline-flex",
                  alignItems: "center",
                  gap: "4px",
                }}
              >
                <span>
                  {r.ruleType === "PRICE_ABOVE"
                    ? `Fiyat > ₺${r.targetValue}`
                    : r.ruleType === "PRICE_BELOW"
                      ? `Fiyat < ₺${r.targetValue}`
                      : r.ruleType === "RED_CANDLE"
                        ? "Kırmızı Mum"
                        : r.ruleType === "TAVAN_BREAK"
                          ? "Tavan Bozdu"
                          : r.ruleType === "STOP_LOSS"
                            ? `Stop %${r.targetValue}`
                            : r.ruleType === "TAKE_PROFIT"
                              ? `KarAl %${r.targetValue}`
                              : `İzleyenStop %${r.targetValue}`}
                </span>
                {onDeleteRule && (
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      onDeleteRule(r.id);
                    }}
                    title="Alarmı / Kuralı Kaldır"
                    style={{
                      background: "transparent",
                      border: "none",
                      color: "#f87171",
                      cursor: "pointer",
                      fontWeight: 700,
                      fontSize: "0.85rem",
                      padding: "0 2px",
                      lineHeight: 1,
                    }}
                  >
                    &times;
                  </button>
                )}
              </span>
            ))
          ) : (
            <span style={{ fontSize: "0.75rem", color: "#64748b" }}>
              Alarm Yok
            </span>
          )}
        </div>
      </td>
      <td style={{ textAlign: "right" }}>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "flex-end",
            gap: "6px",
          }}
        >
          <button
            className="stock-btn stock-btn-secondary"
            onClick={() => onOpenChart(sym)}
            title="Canlı Grafik Görüntüle"
            style={{ padding: "6px 10px" }}
          >
            <IconChart />
            <span style={{ fontSize: "0.75rem" }}>Grafik</span>
          </button>
          <button
            className="stock-btn stock-btn-secondary"
            onClick={() => onAddRuleClick(sym)}
            title="Fiyat Alarmı Ekle"
            style={{ padding: "6px 10px" }}
          >
            <IconPlus />
            <span style={{ fontSize: "0.75rem" }}>Alarm</span>
          </button>
          <button
            className="stock-btn stock-btn-ai"
            onClick={() => onAiAnalyzeClick(sym)}
            title="AI Analiz & Danışman"
            style={{ padding: "6px 10px" }}
          >
            <IconSparkles />
            <span style={{ fontSize: "0.75rem" }}>AI</span>
          </button>
          <button
            className="stock-btn stock-btn-danger"
            onClick={() => onSellItem(item.id, sym, item.lotCount, currentPrice)}
            title="Satış Yap"
            style={{ padding: "6px 10px" }}
          >
            <IconSell />
            <span style={{ fontSize: "0.75rem" }}>Sat</span>
          </button>
        </div>
      </td>
    </tr>
  );
}

