      <td style={{ textAlign: "right", color: "#cbd5e1" }}>
        {quote?.dayLow && quote.dayLow > 0 ? formatPrice(quote.dayLow) : "—"}
      </td>
      <td
        style={{
          textAlign: "right",
          color: "#94a3b8",
          fontSize: "0.85rem",
