/**
 * Finds element by selector, aria-label, or matching text content.
 */
function findTargetElement(
  selector?: string,
  targetText?: string,
): HTMLElement | null {
  if (selector) {
    try {
      const el = document.querySelector(selector) as HTMLElement;
      if (el) {
        return el;
      }
    } catch {
      // Ignore invalid CSS selector syntax
    }
  }

  if (targetText) {
    const textLower = targetText.toLowerCase().trim();
    const all = Array.from(
      document.querySelectorAll(
        "input, textarea, select, button, a, [role='button'], [role='textbox'], label",
      ),
    );

    for (const el of all) {
      const htmlEl = el as HTMLElement;
      const aria = (htmlEl.getAttribute("aria-label") || "")
        .toLowerCase()
        .trim();
      const placeholder = (htmlEl.getAttribute("placeholder") || "")
        .toLowerCase()
        .trim();
      const nameAttr = (htmlEl.getAttribute("name") || "").toLowerCase().trim();
      const idAttr = (htmlEl.id || "").toLowerCase().trim();
      const val = (htmlEl.innerText || (htmlEl as HTMLInputElement).value || "")
        .toLowerCase()
        .trim();
      const parentText =
        (
          (htmlEl.parentElement ||
            htmlEl.closest("label, div, p")) as HTMLElement
        )?.innerText
          ?.toLowerCase()
          .trim() || "";

      if (
        aria.includes(textLower) ||
        placeholder.includes(textLower) ||
        nameAttr.includes(textLower) ||
        idAttr.includes(textLower) ||
        val.includes(textLower) ||
        parentText.includes(textLower)
      ) {
        return htmlEl;
      }
    }
  }

  return null;
}

export interface ExtractedPageData {
  title: string;
  url: string;
  summaryText: string;
}

/**
 * Executes requested browser action or form autofill on active DOM with Claude / Browser-Use overlays.
 */
export function executeAgentAction(payload: AgentActionPayload): {
  success: boolean;
  message: string;
  extractedData?: ExtractedPageData;
} {
  const { actionType, selector, targetText, textValue, direction } = payload;

  if (actionType === "scroll") {
    showScanningSweep();
    const scrollAmount = direction === "up" ? -400 : 400;
    window.scrollBy({ top: scrollAmount, behavior: "smooth" });
    return { success: true, message: `Scrolled ${direction || "down"}` };
  }

  if (actionType === "extract") {
    showScanningSweep();
    const context = getPageContext();
    return {
      success: true,
      message: "Page data extracted successfully",
      extractedData: {
        title: context.title,
        url: context.url,
        summaryText: context.pageText.slice(0, 1000),
      },
    };
  }

  const targetEl = findTargetElement(selector, targetText);

  if (!targetEl) {
    return {
      success: false,
      message: `Target element not found: ${selector || targetText}`,
    };
  }

  const labelText =
    targetText ||
    (targetEl as HTMLInputElement).placeholder ||
    targetEl.innerText ||
    "Öğe";
  highlightElement(
    targetEl,
    `${actionType.toUpperCase()}: ${labelText.slice(0, 25)}`,
  );

  if (actionType === "click" || actionType === "highlight") {
    if (actionType === "click") {
      targetEl.click();
      return {
        success: true,
        message: `Clicked element: ${selector || targetText}`,
      };
    }
    return {
      success: true,
      message: `Highlighted element: ${selector || targetText}`,
    };
  }

  if (actionType === "type") {
    const inputEl = targetEl as HTMLInputElement | HTMLTextAreaElement;

    // Focus & Fill input with event dispatches for dynamic forms (Google Forms, React, Vue)
    inputEl.focus();
    inputEl.value = textValue || "";

    // Dispatch synthetic events so form state updates immediately
    inputEl.dispatchEvent(new Event("focus", { bubbles: true }));
    inputEl.dispatchEvent(new Event("input", { bubbles: true }));
    inputEl.dispatchEvent(new Event("change", { bubbles: true }));
    inputEl.dispatchEvent(new Event("blur", { bubbles: true }));

    return {
      success: true,
      message: `Typed text into element: ${selector || targetText}`,
    };
  }

  return {
    success: false,
    message: `Action type '${actionType}' could not be completed.`,
  };
}

/**
 * Initializes DOM Agent listener for incoming messages from extension background/sidepanel.
 */
export function initDomAgentEngine(): void {
  chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
    if (message.type === "agent_get_context") {
      const context = getPageContext();
      sendResponse({ success: true, context });
      return true;
    }

    if (message.type === "agent_execute_action") {
      if (Array.isArray(message.payload)) {
        const results = (message.payload as AgentActionPayload[]).map(
          (action) => executeAgentAction(action),
        );
        sendResponse({
          success: true,
          message: `Executed ${results.length} form actions`,
          results,
        });
      } else {
        const result = executeAgentAction(
          message.payload as AgentActionPayload,
        );
        sendResponse(result);
      }
      return true;
    }
  });
}

/**
 * detoxBlocker.ts
 * Screen time detox & Pomodoro focus session website blocker.
 * Clean Architecture - Content Script Domain Module.
 */

import { getTranslation } from "@/utils/i18n.js";
import type { Language } from "@/types/types.js";

export function initDetoxBlocker(): void {
  const currentHost = window.location.hostname;

  // Hiding helper (immediately inject to prevent layout flash)
  const styleEl = document.createElement("style");
  styleEl.innerHTML = "html, body { display: none !important; }";
  if (document.documentElement) {
    document.documentElement.appendChild(styleEl);
  }

  function checkScreenTimeLimits(): void {
    try {
      if (!chrome.runtime?.id) {
        return;
      }

      chrome.storage.sync.get(
        [
          "detox_enabled",
          "detox_blocked_sites",
          "detox_end_time",
          "custom_quotes",
          "lang",
          "pomoBlockEnabled",
          "detox_limits",
          "detoxLimits",
        ],
        (settings) => {
          if (chrome.runtime.lastError || !chrome.runtime?.id) {
            return;
          }

          chrome.storage.local.get(
            ["pomodoro_timer_state", "screen_time_stats"],
            (localRes) => {
              if (chrome.runtime.lastError || !chrome.runtime?.id) {
                return;
              }

              const enabled = (settings.detox_enabled as boolean) || false;
              const blockedSites =
                (settings.detox_blocked_sites as string[]) || [];
              const endTime = (settings.detox_end_time as number) || 0;
              const lang = (settings.lang as string) || "tr";
              const pomoBlockEnabled = settings.pomoBlockEnabled ?? true;
              const pomoState =
                (localRes.pomodoro_timer_state as {
                  running?: boolean;
                  mode?: string;
                  endTime?: number;
                }) || {};

              const isBlockedHost = blockedSites.some((site) =>
                currentHost.includes(site),
              );

              const defaultSites = [
                "instagram.com",
                "facebook.com",
                "youtube.com",
                "tiktok.com",
                "x.com",
                "twitter.com",
              ];
              const isPomoBlockedHost =
                blockedSites.some((site) => currentHost.includes(site)) ||
                defaultSites.some((site) => currentHost.includes(site));

              const isTimeActive = endTime === -1 || endTime > Date.now();

              const isDetoxActive = enabled && isBlockedHost && isTimeActive;
              const isPomoActive =
                pomoBlockEnabled &&
                isPomoBlockedHost &&
                pomoState.running &&
                pomoState.mode === "focus";

              const detoxLimits =
                (settings.detoxLimits as Record<string, number>) ||
                (settings.detox_limits as Record<string, number>) ||
                {};
              const cleanHost = currentHost.replace("www.", "");
              const limitDomain = Object.keys(detoxLimits).find((domain) => {
                const cleanDomain = domain.replace("www.", "");
                return (
                  cleanHost.includes(cleanDomain) ||
                  cleanDomain.includes(cleanHost)
                );
              });
              const activeLimitMinutes = limitDomain
                ? detoxLimits[limitDomain]
                : 0;

              let isLimitExceeded = false;
              let remainingSeconds = 999999;
              if (activeLimitMinutes > 0 && limitDomain) {
                const todayStr = new Date().toLocaleDateString("sv");
                const dailyStats = localRes.screen_time_stats?.[todayStr] || {};
                const cleanLimitDomain = limitDomain.replace("www.", "");

                let spentSeconds = 0;
                for (const statDomain in dailyStats) {
                  const cleanStatDomain = statDomain.replace("www.", "");
                  if (
                    cleanStatDomain.includes(cleanLimitDomain) ||
                    cleanLimitDomain.includes(cleanStatDomain)
                  ) {
                    spentSeconds += dailyStats[statDomain];
                  }
                }

                const limitSeconds = activeLimitMinutes * 60;
                isLimitExceeded = spentSeconds >= limitSeconds;
                remainingSeconds = limitSeconds - spentSeconds;
              }

              if (isDetoxActive || isPomoActive || isLimitExceeded) {
                const targetEndTime = isPomoActive
                  ? pomoState.endTime
                  : isLimitExceeded
                    ? -1
                    : endTime;
                const isLimitBlock =
                  isLimitExceeded && !isDetoxActive && !isPomoActive;

                setupBlockPage(
                  targetEndTime || -1,
                  (settings.custom_quotes as Array<{ text: string }>) || [],
                  lang,
                  Boolean(isPomoActive),
                  isLimitBlock,
                  activeLimitMinutes,
                  styleEl,
                );
              } else {
                if (styleEl.parentNode) {
                  styleEl.parentNode.removeChild(styleEl);
                }

                if (
                  activeLimitMinutes > 0 &&
                  remainingSeconds > 0 &&
                  remainingSeconds <= 300
                ) {
                  showTopWarningBanner(
                    Math.ceil(remainingSeconds / 60),
                    lang,
                    limitDomain || "",
                  );
                } else {
                  removeWarningBanner();
                }
              }
            },
          );
        },
      );
    } catch {
      // Ignore extension context invalidation on extension reload
    }
  }

  // Real-time listener for Pomodoro timer start/stop, screen time, or settings changes
  chrome.storage.onChanged.addListener((changes, areaName) => {
    if (
      areaName === "local" &&
      (changes["pomodoro_timer_state"] || changes["screen_time_stats"])
    ) {
      checkScreenTimeLimits();
    }
    if (
      areaName === "sync" &&
      (changes["detox_enabled"] ||
        changes["detox_blocked_sites"] ||
        changes["detox_end_time"] ||
        changes["pomoBlockEnabled"] ||
        changes["detox_limits"])
    ) {
      checkScreenTimeLimits();
    }
  });

  checkScreenTimeLimits();

  let lastUrl = location.href;
  setInterval(() => {
    if (location.href !== lastUrl) {
      lastUrl = location.href;
      checkScreenTimeLimits();
    }
  }, 2000);
}

function showTopWarningBanner(
  minutesLeft: number,
  lang: string,
  domain: string,
): void {
  if (sessionStorage.getItem("detox_warning_dismissed") === "true") {
    return;
  }

  if (!document.body) {
    return;
  }

  let banner: HTMLElement | null = null;
  let host = document.getElementById("detox-warning-banner-host");
  if (!host) {
    host = document.createElement("div");
    host.id = "detox-warning-banner-host";
    host.style.position = "fixed";
    host.style.top = "16px";
    host.style.left = "50%";
    host.style.transform = "translateX(-50%)";
    host.style.zIndex = "2147483647";
    host.style.pointerEvents = "auto";
    document.body.appendChild(host);

    const shadow = host.attachShadow({ mode: "open" });

    const wrapper = document.createElement("div");
    wrapper.id = "detox-warning-banner";
    wrapper.style.display = "flex";
    wrapper.style.alignItems = "center";
    wrapper.style.gap = "12px";
    wrapper.style.background = "rgba(15, 15, 20, 0.85)";
    wrapper.style.backdropFilter = "blur(12px)";
    (wrapper.style as unknown as Record<string, string>)[
      "webkitBackdropFilter"
    ] = "blur(12px)";
    wrapper.style.border = "1px solid rgba(239, 68, 68, 0.4)";
    wrapper.style.boxShadow = "0 10px 30px rgba(0, 0, 0, 0.5)";
    wrapper.style.borderRadius = "12px";
    wrapper.style.padding = "10px 18px";
    wrapper.style.color = "#fff";
    wrapper.style.fontFamily =
      "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
    wrapper.style.fontSize = "13px";
    wrapper.style.fontWeight = "600";

    const textSpan = document.createElement("span");
    textSpan.id = "detox-warning-text";

    const closeBtn = document.createElement("button");
    closeBtn.textContent = "✕";
    closeBtn.style.background = "transparent";
    closeBtn.style.border = "none";
    closeBtn.style.color = "rgba(255, 255, 255, 0.6)";
    closeBtn.style.cursor = "pointer";
    closeBtn.style.fontSize = "12px";
    closeBtn.style.padding = "2px 6px";
    closeBtn.addEventListener("click", () => {
      sessionStorage.setItem("detox_warning_dismissed", "true");
      if (host) {
        host.remove();
      }
    });

    wrapper.appendChild(textSpan);
    wrapper.appendChild(closeBtn);
    shadow.appendChild(wrapper);

    banner = textSpan;
  } else if (host.shadowRoot) {
    banner = host.shadowRoot.getElementById("detox-warning-text");
  }

  if (banner) {
    const siteLabel = domain.replace(".com", "").toUpperCase();
    const t = getTranslation(lang as Language);
    banner.textContent = t.social_media_limit_warning
      .replace("{site}", siteLabel)
      .replace("{minutes}", String(minutesLeft));
  }
}

function removeWarningBanner(): void {
  const host = document.getElementById("detox-warning-banner-host");
  if (host) {
    host.remove();
  }
}

