      clearInterval(timerInterval);
    }

    if (endTime === -1) {
      if (timerText) {
        timerText.textContent = permanentLabel;
      }
    } else {
      const updateTimer = () => {
        const remaining = endTime - Date.now();
        if (remaining <= 0) {
          window.location.reload();
          return;
        }

        const hrs = Math.floor(remaining / 3600000);
        const mins = Math.floor((remaining % 3600000) / 60000);
        const secs = Math.floor((remaining % 60000) / 1000);

        let timeString = "";
        if (hrs > 0) {
          timeString += `${hrs.toString().padStart(2, "0")}:`;
        }
        timeString += `${mins.toString().padStart(2, "0")}:${secs.toString().padStart(2, "0")}`;

        const currentTimerText = document.getElementById("detox-timer-text");
        if (currentTimerText) {
          currentTimerText.textContent = `${timeRemainingLabel}: ${timeString}`;
        }
      };

      updateTimer();
      timerInterval = setInterval(updateTimer, 1000);
    }
  };

  setupDOMAndTimer();

  if (document.body) {
    const observer = new MutationObserver(() => {
      if (!document.getElementById("detox-block-overlay")) {
        observer.disconnect();
        setupDOMAndTimer();
        if (document.body) {
          observer.observe(document.body, { childList: true, subtree: true });
        }
      }
    });
    observer.observe(document.body, { childList: true, subtree: true });
  }
}

/**
 * universalInfoBox.ts
 * Universal AI translation & inline web info box bubble.
 * Clean Architecture - Content Script Domain Module.
 */

/**
 * Content script NOTE: Uses contentLogger (console + storage ring buffer)
 * instead of the centralized logger — bundling that caused esbuild name
 * collisions that crashed the content IIFE.
 */
import { contentWarn, contentError } from "@/content/contentLogger.js";

let bubbleHost: HTMLDivElement | null = null;

export function initUniversalInfoBox(): void {
  chrome.storage.sync.get(
    ["universalInfoBoxEnabled", "universalInfoBoxHotkey"],
    (settings) => {
      const enabled = (settings.universalInfoBoxEnabled as boolean) ?? true;
      const hotkey = (settings.universalInfoBoxHotkey as string) || "none";

      if (!enabled) {
        return;
      }

      document.addEventListener("mouseup", (e) => {
        handleTextSelection(e, hotkey);
      });
      document.addEventListener("mousedown", (e) => {
        handleOutsideClick(e);
      });
    },
  );
}

function handleTextSelection(e: MouseEvent, hotkey: string): void {
  if (hotkey === "alt" && !e.altKey) {
    return;
  }
  if (hotkey === "ctrl" && !e.ctrlKey) {
    return;
  }
  if (hotkey === "shift" && !e.shiftKey) {
    return;
  }

  setTimeout(() => {
    const selection = window.getSelection();
    if (!selection || selection.isCollapsed) {
      removeBubble();
      return;
    }

    const text = selection.toString().trim();

    if (!text || text.length <= 1 || text.length > 5000) {
      return;
    }

    if (bubbleHost && e.target && bubbleHost.contains(e.target as Node)) {
      return;
    }

    try {
      if (!chrome.runtime?.id) {
        return;
      }
      chrome.runtime.sendMessage(
        { type: "translate_text", text: text },
        (response: { translation?: string }) => {
          if (chrome.runtime.lastError) {
            contentWarn(
              "[InfoBox] translate_text lastError:",
              chrome.runtime.lastError,
            );
            return;
          }
          if (response && response.translation) {
            showTranslationBubble(response.translation, selection);
          } else {
            contentWarn("[InfoBox] translate_text yanıtsız:", response);
          }
        },
      );
    } catch (err) {
      contentError("[InfoBox] sendMessage hatası:", err);
    }
  }, 10);
}

function handleOutsideClick(e: MouseEvent): void {
  if (bubbleHost) {
    const path = e.composedPath ? e.composedPath() : [];
    if (!path.includes(bubbleHost)) {
      removeBubble();
    }
  }
}

function removeBubble(): void {
  if (bubbleHost) {
    if (bubbleHost.parentNode) {
      bubbleHost.parentNode.removeChild(bubbleHost);
    }
    bubbleHost = null;
  }
}

function showTranslationBubble(
  translationText: string,
  selection: Selection,
): void {
  removeBubble();

  if (!document.body) {
    return;
  }

  bubbleHost = document.createElement("div");
  bubbleHost.style.position = "absolute";
  bubbleHost.style.zIndex = "2147483647";
  bubbleHost.style.pointerEvents = "auto";

  const range = selection.getRangeAt(0);
  const rect = range.getBoundingClientRect();
  const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
  const scrollLeft = window.pageXOffset || document.documentElement.scrollLeft;

  const bubbleX = rect.left + rect.width / 2 + scrollLeft;

  const shadow = bubbleHost.attachShadow({ mode: "open" });

  const style = document.createElement("style");
  style.textContent = `
    .bubble-wrapper {
      position: relative;
      transform: translate(-50%, -100%);
      background: rgba(18, 18, 24, 0.85);
      backdrop-filter: blur(14px);
      -webkit-backdrop-filter: blur(14px);
      border: 1px solid rgba(139, 92, 246, 0.4);
      box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
      border-radius: 10px;
      padding: 10px 14px;
      width: max-content;
      max-width: 280px;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
      color: #f1f5f9;
      font-size: 13px;
      line-height: 1.5;
      animation: bubbleFadeIn 0.2s cubic-bezier(0.16, 1, 0.3, 1) forwards;
    }
    .bubble-wrapper.below {
      transform: translate(-50%, 0);
      animation: bubbleFadeInBelow 0.2s cubic-bezier(0.16, 1, 0.3, 1) forwards;
    }
    .bubble-header {
      display: flex;
      align-items: center;
      margin-bottom: 6px;
      border-bottom: 1px solid rgba(255, 255, 255, 0.08);
      padding-bottom: 4px;
      gap: 15px;
    }
    .bubble-title {
      color: #a78bfa;
      font-size: 9px;
      font-weight: 800;
      letter-spacing: 1.2px;
      text-transform: uppercase;
      margin: 0;
    }
    .bubble-close {
      background: transparent;
      border: none;
      color: #64748b;
      font-size: 10px;
      cursor: pointer;
      padding: 2px;
      margin-left: auto;
      line-height: 1;
      transition: color 0.15s ease;
    }
    .bubble-close:hover {
      color: #ef4444;
    }
    .bubble-content {
      word-break: break-word;
      font-weight: 500;
    }
    @keyframes bubbleFadeIn {
      from {
        opacity: 0;
        transform: translate(-50%, -95%) scale(0.95);
      }
      to {
        opacity: 1;
        transform: translate(-50%, -100%) scale(1);
      }
    }
    @keyframes bubbleFadeInBelow {
      from {
        opacity: 0;
        transform: translate(-50%, 5%) scale(0.95);
      }
      to {
        opacity: 1;
        transform: translate(-50%, 0) scale(1);
      }
    }
  `;

  const wrapper = document.createElement("div");
  wrapper.className = "bubble-wrapper";

  const header = document.createElement("div");
  header.className = "bubble-header";

  const title = document.createElement("h4");
  title.className = "bubble-title";
  title.textContent = "AI TRANSLATE";

  const closeBtn = document.createElement("button");
  closeBtn.className = "bubble-close";
  closeBtn.textContent = "✕";
  closeBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    removeBubble();
  });

  header.appendChild(title);
  header.appendChild(closeBtn);

  const content = document.createElement("div");
  content.className = "bubble-content";
  content.textContent = translationText;

  wrapper.appendChild(header);
  wrapper.appendChild(content);

  shadow.appendChild(style);
  shadow.appendChild(wrapper);

  bubbleHost.style.left = "-9999px";
  bubbleHost.style.top = "-9999px";
  document.body.appendChild(bubbleHost);

  const wrapperEl = shadow.querySelector(".bubble-wrapper");
  const wrapperHeight = wrapperEl
    ? wrapperEl.getBoundingClientRect().height
    : 60;

  const needsToRenderBelow = rect.top < wrapperHeight + 20;

  let bubbleY: number;
  if (needsToRenderBelow) {
    bubbleY = rect.bottom + 12 + scrollTop;
    if (wrapperEl) {
      wrapperEl.classList.add("below");
    }
  } else {
    bubbleY = rect.top - 12 + scrollTop;
  }

  bubbleHost.style.left = `${bubbleX}px`;
  bubbleHost.style.top = `${bubbleY}px`;
}

/**
 * quizPanel.ts
 * Content Script Domain Module — External AI sites quiz overlay panel.
 * Detects AI quiz responses in Gemini/ChatGPT/Claude/Copilot, shows a small
 * "Quiz Mode" trigger button, and opens an isolated Shadow DOM overlay with
 * clickable option cards, navigation, and a score summary.
 *
 * Clean Architecture - Content Script Module.
 * Security: createElement + textContent only — NO innerHTML (AGENTS.md 4.4).
 */
import { contentLog, contentError } from "@/content/contentLogger.js";

const AI_SITES: Array<{ host: string; name: string }> = [
  { host: "gemini.google.com", name: "Gemini" },
  { host: "chatgpt.com", name: "ChatGPT" },
  { host: "claude.ai", name: "Claude" },
  { host: "copilot.microsoft.com", name: "Copilot" },
];

/** Flexible option marker: "A." "A)" "* A)" "**A)**" etc. */
const OPTION_RE = /^\s*[*_]*([A-E])[.)]\s*(.*)$/i;

/** Question start marker: "Soru 1:", "**1. Soru:**", "1.", "1)", "1-)" etc. */
const QUESTION_RE =
  /^\s*[*_#]*\s*(?:Soru\s*)?(\d{1,2})\s*[.):\-–]?\s*(?:Soru\s*)?[:*_#]*\s*(.*)$/i;

/** Correct answer marker: "Doğru Cevap: X", "✓ X", "Cevap: X". */
const ANSWER_RE = /(?:doğru\s*cevap|✓|cevap)\s*[:*\-–]?\s*([A-E])/i;

const STORAGE_KEY = "lifos_quiz_stats";

interface QuizQuestion {
  num: number;
  question: string;
  options: Array<{ letter: string; text: string }>;
  correctAnswer: string | null;
  explanation?: string;
}

interface QuizStats {
  completedTests: number;
  totalQuestions: number;
  correctAnswers: number;
  lastDate: string;
}

let panelHost: HTMLElement | null = null;
let triggerButton: HTMLElement | null = null;
let collectedText = "";
let debounceTimer: ReturnType<typeof setTimeout> | null = null;
let parsedQuestions: QuizQuestion[] = [];
let currentIndex = 0;
let selectedAnswers: Record<number, string> = {};

export function initQuizPanel(): void {
  const host = window.location.hostname;
  const matchedSite = AI_SITES.find(
    (entry) => host === entry.host || host.endsWith("." + entry.host),
  );

  if (!matchedSite) {
    return;
  }

  contentLog(`[QuizPanel] Active on ${matchedSite.name} (${host})`);

  const start = () => {
    const observer = new MutationObserver(() => {
      scheduleParse();
    });

    observer.observe(document.documentElement, {
      childList: true,
      subtree: true,
      characterData: true,
    });
  };

  if (document.body) {
    start();
  } else {
    document.addEventListener("DOMContentLoaded", start, { once: true });
  }

  // Initial scan — a past chat may already be in the DOM.
  // MutationObserver only fires on CHANGES, so scan once on load.
  setTimeout(() => {
    tryParse();
  }, 1200);
}

/** Debounced parse — runs 1.8s after the last DOM change (AI finished typing). */
function scheduleParse(): void {
  if (debounceTimer) {
    clearTimeout(debounceTimer);
  }
  debounceTimer = setTimeout(() => {
    tryParse();
  }, 1800);
}

/**
 * Collects visible text from the AI response area.
 * Uses innerText (not TreeWalker) — innerText preserves inline text
 * ("<strong>Soru 1:</strong> metin" stays on ONE line), while TreeWalker
 * splits text nodes at element boundaries and breaks question parsing.
 * Open shadow roots are walked too (ChatGPT/Claude/Copilot render inside them).
 */
function collectPageText(): string {
  const parts: string[] = [];
  const seen = new Set<Node>();

  const walk = (root: ParentNode) => {
    const text = (root as HTMLElement).innerText ?? root.textContent ?? "";
    if (text.trim()) {
      parts.push(text.trim());
    }
    root.querySelectorAll("*").forEach((el) => {
      const shadow = (el as HTMLElement).shadowRoot as ShadowRoot | null;
      if (shadow && shadow.mode === "open" && !seen.has(shadow)) {
        seen.add(shadow);
        walk(shadow);
      }
    });
  };

  walk(document.body);
  return parts.join("\n");
}

/** Parses collected text into structured questions. */
function parseQuestions(rawText: string): QuizQuestion[] {
  const lines = rawText
    .split("\n")
    .map((l) => l.trim())
    .filter(Boolean);

  // User prompt templates like "Soru 1: [soru metni]" / "A) [şıkkı]"
  // are collected too (the user's own message is in the DOM). Drop them.
  const PLACEHOLDER_RE =
    /\[(?:soru\s*metni|şıkkı|şıklar|açıklaması|cevabı|question\s*text|option|answer)\]/i;

  const questions: QuizQuestion[] = [];
  const seenNumbers = new Set<number>();
  let current: QuizQuestion | null = null;

  const flush = () => {
    if (current && current.options.length >= 2) {
      // Drop user-template questions (placeholder text).
      const hasPlaceholder =
        PLACEHOLDER_RE.test(current.question) ||
        current.options.some((o) => PLACEHOLDER_RE.test(o.text));
      if (!hasPlaceholder) {
        questions.push(current);
      }
    }
    current = null;
  };

  for (const line of lines) {
    const qMatch = QUESTION_RE.exec(line);
    if (qMatch && qMatch[1]) {
      const num = parseInt(qMatch[1], 10);
      // "Soru 1" appearing again = a NEW test started in the same chat.
      // The user's template questions (with [soru metni] placeholders) are
      // never pushed, so a real "Soru 1" only comes from an AI answer.
      if (num === 1 && questions.length > 0) {
        questions.length = 0;
        seenNumbers.clear();
        contentLog("[QuizPanel] yeni test algılandı — önceki sorular temizlendi");
      }
      flush();
      seenNumbers.add(num);
      current = {
        num,
        question: qMatch[2] || line,
        options: [],
        correctAnswer: null,
      };
      continue;
    }

    const optMatch = OPTION_RE.exec(line);
    if (optMatch && current) {
      current.options.push({
        letter: optMatch[1].toUpperCase(),
        text: optMatch[2],
      });
      continue;
    }

    const ansMatch = ANSWER_RE.exec(line);
    if (ansMatch && current) {
      current.correctAnswer = ansMatch[1].toUpperCase();
      // Capture the explanation after "— Açıklama: ..." if present.
      const expl = line.split(/—|–|-/)[1]?.trim();
      if (expl && expl.length > 0) {
        current.explanation = expl.replace(/^açıklama\s*:?\s*/i, "");
      }
      continue;
    }

    // Fallback: a paragraph line that matches nothing (multi-line question
    // stems, ÖSYM-style long questions) gets appended to the current
    // question text instead of being dropped.
    if (current) {
      current.question =
        current.question.length > 0
          ? `${current.question}\n${line}`
          : line;
    }
  }

  flush();
  return questions;
}

function tryParse(): void {
  const raw = collectPageText();
  if (!raw || raw === collectedText) {
    return;
  }
  collectedText = raw;

  // Freeze parsing while the overlay panel is open — the user is mid-quiz.
  if (document.getElementById("lifos-quiz-panel-host")) {
    return;
  }

  const questions = parseQuestions(raw);
  contentLog(
    `[QuizPanel] parse: ${questions.length} soru bulundu (raw ${raw.length} karakter)`,
  );
  if (questions.length < 2) {
    // No usable quiz detected — hide trigger if shown.
    hideTrigger();
    return;
  }

  // Replace the parsed set on every valid parse. A second test in the
  // same chat has the SAME question numbers (1-5), so a "grew" check
  // (questions.length > previous) would compare 5 > 5 = false and keep
  // the OLD test. Duplicate-number filtering in parseQuestions already
  // drops the first test's questions in favor of the newer ones.
  parsedQuestions = questions;
  currentIndex = 0;
  selectedAnswers = {};
  showTrigger();
}

/** Shows the small floating trigger button (bottom-right). */
function showTrigger(): void {
  if (triggerButton && triggerButton.isConnected) {
    return;
  }

  const host = document.createElement("div");
  host.id = "lifos-quiz-trigger-host";
  host.style.cssText = `
    position: fixed;
    bottom: 24px;
    right: 24px;
    z-index: 2147483646;
  `;

  const shadow = host.attachShadow({ mode: "open" });

  const btn = document.createElement("button");
  btn.textContent = "Quiz Moduna Geç";
  btn.style.cssText = `
    background: linear-gradient(135deg, #8b5cf6, #6366f1);
    color: #fff;
    border: none;
    border-radius: 999px;
    padding: 12px 20px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    font-family: system-ui, sans-serif;
    box-shadow: 0 8px 24px rgba(139, 92, 246, 0.4);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
  `;
  btn.addEventListener("mouseenter", () => {
    btn.style.transform = "scale(1.05)";
    btn.style.boxShadow = "0 12px 32px rgba(139, 92, 246, 0.55)";
  });
  btn.addEventListener("mouseleave", () => {
    btn.style.transform = "scale(1)";
    btn.style.boxShadow = "0 8px 24px rgba(139, 92, 246, 0.4)";
  });
  btn.addEventListener("click", () => {
    openPanel();
  });

  shadow.appendChild(btn);
  document.body.appendChild(host);
  triggerButton = btn;
  panelHost = host;
}

function hideTrigger(): void {
  if (panelHost && panelHost.isConnected) {
    panelHost.remove();
  }
  panelHost = null;
  triggerButton = null;
}

/** Opens the full overlay quiz panel in its own Shadow DOM. */
function openPanel(): void {
  if (!panelHost) {
    return;
  }

  const overlayHost = document.createElement("div");
  overlayHost.id = "lifos-quiz-panel-host";
  overlayHost.style.cssText = `
    position: fixed;
    inset: 0;
    z-index: 2147483647;
  `;

  const shadow = overlayHost.attachShadow({ mode: "open" });
  renderPanel(shadow);

  document.body.appendChild(overlayHost);

  // ESC to close.
  const escHandler = (e: KeyboardEvent) => {
    if (e.key === "Escape") {
      overlayHost.remove();
      document.removeEventListener("keydown", escHandler);
    }
  };
  document.addEventListener("keydown", escHandler);
}

/** Closes the overlay panel. Works from inside shadow DOM —
 *  closest() cannot cross the shadow boundary, so we remove
 *  the host element directly. */
function closePanel(): void {
  document.getElementById("lifos-quiz-panel-host")?.remove();
}

/** Renders the quiz panel content into the shadow root. */
function renderPanel(shadow: ShadowRoot): void {
  shadow.innerHTML = ""; // Clear (we control this root — safe).

  const style = document.createElement("style");
  style.textContent = `
    :host { all: initial; }
    * { box-sizing: border-box; }
    .overlay {
      position: fixed;
      inset: 0;
      background: rgba(15, 23, 42, 0.92);
      backdrop-filter: blur(14px);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 40px;
      font-family: system-ui, -apple-system, sans-serif;
      color: #f8fafc;
    }
    .panel {
      background: linear-gradient(160deg, rgba(30, 41, 59, 0.95), rgba(15, 23, 42, 0.98));
      border: 1px solid rgba(139, 92, 246, 0.3);
      border-radius: 20px;
      width: min(720px, 100%);
      max-height: 90vh;
      overflow-y: auto;
      padding: 32px;
      box-shadow: 0 24px 64px rgba(0, 0, 0, 0.6);
    }
    .header {
      display: flex;
