/**
 * GoogleAuthApi
 * Infrastructure implementation of Google OAuth authentication.
 * Directly uses Chrome Identity API and Google OAuth2 endpoints.
 */

export interface GoogleUserInfo {
  email: string;
}

export class GoogleAuthApi {
  async getAuthToken(interactive: boolean = false): Promise<string> {
    return new Promise((resolve, reject) => {
      if (typeof chrome === "undefined" || !chrome.identity) {
        return reject(new Error("Chrome Identity API is not available."));
      }
      chrome.identity.getAuthToken({ interactive }, (result) => {
        if (chrome.runtime.lastError) {
          return reject(new Error(chrome.runtime.lastError.message));
        }
        if (!result) {
          return reject(new Error("Failed to retrieve token."));
        }
        const token =
          typeof result === "string"
            ? result
            : (result as { token: string }).token;
        if (!token) {
          return reject(new Error("No token returned in auth result."));
        }
        resolve(token);
      });
    });
  }

  async removeCachedAuthToken(token: string): Promise<void> {
    return new Promise((resolve) => {
      if (typeof chrome !== "undefined" && chrome.identity) {
        chrome.identity.removeCachedAuthToken({ token }, () => {
          resolve();
        });
      } else {
        resolve();
      }
    });
  }

  async getUserEmail(token: string): Promise<string> {
    const response = await fetch(
      "https://www.googleapis.com/oauth2/v2/userinfo",
      {
        headers: { Authorization: `Bearer ${token}` },
      },
    );
    if (!response.ok) {
      throw new Error("Failed to fetch Google user info.");
    }
    const info: GoogleUserInfo = await response.json();
    return info.email;
  }
}

/**
 * GoogleCalendarApi
 * Infrastructure adapter for Google Calendar REST API.
 */

export interface GoogleCalendarEvent {
  id?: string;
  summary?: string;
  description?: string;
  start?: { dateTime?: string; date?: string };
  end?: { dateTime?: string; date?: string };
  [key: string]: unknown;
}

export class GoogleCalendarApi {
  async getCalendarEvents(
    token: string,
    startStr: string,
    endStr: string,
  ): Promise<GoogleCalendarEvent[]> {
    const url = `https://www.googleapis.com/calendar/v3/calendars/primary/events?timeMin=${encodeURIComponent(startStr)}&timeMax=${encodeURIComponent(endStr)}&singleEvents=true&orderBy=startTime`;
    const res = await fetch(url, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!res.ok) {
      throw new Error(`Calendar fetch failed: ${res.statusText}`);
    }
    const data = await res.json();
    return data.items || [];
  }

  async createCalendarEvent(
    token: string,
    event: GoogleCalendarEvent,
  ): Promise<GoogleCalendarEvent> {
    const url =
      "https://www.googleapis.com/calendar/v3/calendars/primary/events";
    const res = await fetch(url, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(event),
    });
    if (!res.ok) {
      throw new Error(`Calendar event creation failed: ${res.statusText}`);
    }
    return await res.json();
  }
}

/**
 * LocalToSyncMigration
 * Infrastructure implementation for migrating data from chrome.storage.local to chrome.storage.sync.
 * Standalone implementation without legacy core/storage dependency.
 */

import { SYNC_ALL_KEYS } from "@/infrastructure/storage/keys.js";
import { logger } from "@/utils/logger.js";

const SYNC_KEYS = SYNC_ALL_KEYS;

export class LocalToSyncMigration {
  /**
   * Migrates data from local storage to sync storage.
   * Reads all keys from chrome.storage.local and writes relevant keys
   * to chrome.storage.sync if sync storage is empty.
   */
  async migrate(): Promise<void> {
    return new Promise((resolve) => {
      chrome.storage.local.get(null, async (localData) => {
        if (localData && Object.keys(localData).length > 0) {
          chrome.storage.sync.get(null, async (syncData) => {
            if (!syncData || Object.keys(syncData).length <= 1) {
              const filteredData: Record<string, any> = {};
              for (const key of SYNC_KEYS) {
                if (localData[key] !== undefined) {
                  filteredData[key] = localData[key];
                }
              }
              if (Object.keys(filteredData).length > 0) {
                try {
                  await chrome.storage.sync.set(filteredData);
                  logger.log("Data migrated to sync storage.");
                } catch (error) {
                  logger.error("Migration to sync storage failed:", error);
                }
              }
            }
            resolve();
          });
        } else {
          resolve();
        }
      });
    });
  }
}

/**
 * ChromeStorageArcadeRepository
 * Infrastructure implementation of IArcadeRepository.
 *
 * Uses chrome.storage.local for game metadata, IndexedDB for
 * FileSystemDirectoryHandle objects, and chrome.storage.sync for
 * legacy migration.
 */

import type { IArcadeRepository } from "@/domain/repositories/IArcadeRepository.js";
import type { GameEntry } from "@/types/game.js";
import { LOCAL_ARCADE_GAMES } from "@/infrastructure/storage/keys.js";

const STORAGE_KEY_GAMES = LOCAL_ARCADE_GAMES;
const LEGACY_SYNC_KEY_GAMES = STORAGE_KEY_GAMES;

/* ------------------------------------------------------------------ */
/* IndexedDB helpers (directory handle persistence)                    */
/* ------------------------------------------------------------------ */

const IDB_NAME = "lifeos_arcade_handles";
const IDB_STORE = "directory_handles";
const IDB_KEY = (id: string) => `handle_${id}`;

const openHandlesDB = (): Promise<IDBDatabase> =>
  new Promise((resolve, reject) => {
    const req = indexedDB.open(IDB_NAME, 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(IDB_STORE)) {
        db.createObjectStore(IDB_STORE);
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });

const isValidDirHandle = (h: unknown): boolean =>
  h !== null &&
  h !== undefined &&
  typeof h === "object" &&
  typeof (h as Record<string, unknown>).name === "string" &&
  typeof (h as Record<string, unknown>).values === "function" &&
  typeof (h as Record<string, unknown>).getDirectoryHandle === "function" &&
  typeof (h as Record<string, unknown>).getFileHandle === "function";

const getHandleInner = async (id: string): Promise<unknown | null> => {
  const db = await openHandlesDB();
  return new Promise<unknown | null>((resolve, reject) => {
    const tx = db.transaction(IDB_STORE, "readonly");
    const req = tx.objectStore(IDB_STORE).get(IDB_KEY(id));
    req.onsuccess = () => {
      db.close();
      const raw = req.result ?? null;
      resolve(isValidDirHandle(raw) ? raw : null);
    };
    req.onerror = () => {
      db.close();
      reject(req.error);
    };
  });
};

const putHandleInner = async (id: string, handle: unknown): Promise<void> => {
  const db = await openHandlesDB();
  await new Promise<void>((resolve, reject) => {
    const tx = db.transaction(IDB_STORE, "readwrite");
    tx.objectStore(IDB_STORE).put(handle, IDB_KEY(id));
    tx.oncomplete = () => {
      db.close();
      resolve();
    };
    tx.onerror = () => {
      db.close();
      reject(tx.error);
    };
  });
};

const deleteHandleInner = async (id: string): Promise<void> => {
  const db = await openHandlesDB();
  await new Promise<void>((resolve, reject) => {
    const tx = db.transaction(IDB_STORE, "readwrite");
    tx.objectStore(IDB_STORE).delete(IDB_KEY(id));
    tx.oncomplete = () => {
      db.close();
      resolve();
    };
    tx.onerror = () => {
      db.close();
      reject(tx.error);
    };
  });
};

/* ------------------------------------------------------------------ */
/* chrome.storage helpers                                              */
/* ------------------------------------------------------------------ */

const readJSON = async <T>(key: string, fallback: T): Promise<T> => {
  try {
    if (typeof chrome !== "undefined" && chrome.storage?.local) {
      return new Promise<T>((resolve) => {
        chrome.storage.local.get([key], (res) => {
          const v = res?.[key];
          if (v !== undefined && v !== null) {
            resolve(v as T);
          } else {
            resolve(fallback);
          }
        });
      });
    }
    const raw = localStorage.getItem(key);
    return raw ? (JSON.parse(raw) as T) : fallback;
  } catch {
    return fallback;
  }
};

const writeJSON = async (key: string, value: unknown): Promise<void> => {
  try {
    if (typeof chrome !== "undefined" && chrome.storage?.local) {
      chrome.storage.local.set({ [key]: value });
    } else {
      localStorage.setItem(key, JSON.stringify(value));
    }
  } catch {
    // swallow write errors
  }
};

/* ------------------------------------------------------------------ */
/* Repository implementation                                           */
/* ------------------------------------------------------------------ */

export class ChromeStorageArcadeRepository implements IArcadeRepository {
  async getAllGames(): Promise<GameEntry[]> {
    const games = await readJSON<GameEntry[]>(STORAGE_KEY_GAMES, []);
    if (games.length > 0) {
      return games;
    }

    // Fallback: legacy sync migration
    const legacy = await this.loadLegacySyncGames();
    if (legacy && legacy.length > 0) {
      const migrated = legacy.map((g) => ({
        ...g,
        folderPath: g.folderPath ?? "",
        handleId: g.handleId ?? "",
        mode: "dist" as const,
      }));
      await writeJSON(STORAGE_KEY_GAMES, migrated);
      return migrated;
    }

    return [];
  }

  async saveAllGames(games: GameEntry[]): Promise<void> {
    await writeJSON(STORAGE_KEY_GAMES, games);
  }

  async loadLegacySyncGames(): Promise<GameEntry[] | null> {
    if (typeof chrome === "undefined" || !chrome.storage?.sync) {
      return null;
    }
    return new Promise<GameEntry[] | null>((resolve) => {
      chrome.storage.sync.get([LEGACY_SYNC_KEY_GAMES], (res) => {
        const data = res?.[LEGACY_SYNC_KEY_GAMES];
        resolve(Array.isArray(data) ? (data as GameEntry[]) : null);
      });
    });
  }

  async getDirectoryHandle(handleId: string): Promise<unknown | null> {
    return getHandleInner(handleId);
  }

  async saveDirectoryHandle(handleId: string, handle: unknown): Promise<void> {
    await putHandleInner(handleId, handle);
  }

  async deleteDirectoryHandle(handleId: string): Promise<void> {
    await deleteHandleInner(handleId);
  }
}

