/**
 * useAppTodoInput Hook
 * Manages todo input state (text, repeat, dueDate) and related handlers.
 * Extracted from App.tsx to reduce monolith size.
 */

import { useState, useCallback } from "preact/hooks";
import type { Todo } from "@/domain/entities/Todo.js";
import type { Language } from "@/domain/value-objects/Language.js";
import type { JSX } from "preact";

interface UseAppTodoInputProps {
  lang: Language;
  onAddTodo: (text: string, repeat: Todo["repeat"], dueDate: string) => void;
  activeTab: "focus" | "routines";
  setActiveTab: (tab: "focus" | "routines") => void;
  setActiveView: (view: string) => void;
  handleTabChangeUI: (tab: "focus" | "routines") => void;
}

export function useAppTodoInput({
  lang,
  onAddTodo,
  activeTab,
  setActiveTab,
  setActiveView,
  handleTabChangeUI,
}: UseAppTodoInputProps) {
  const [todoText, setTodoText] = useState("");
  const [todoRepeat, setTodoRepeat] = useState<Todo["repeat"]>("none");
  const [todoDueDate, setTodoDueDate] = useState("");

  const handleAddTodoClick = useCallback(() => {
    if (todoText.trim()) {
      onAddTodo(todoText.trim(), todoRepeat, todoDueDate);
      setTodoText("");
      setTodoDueDate("");
    }
  }, [todoText, todoRepeat, todoDueDate, onAddTodo]);

  const handleKeyPress = useCallback(
    (e: JSX.TargetedKeyboardEvent<HTMLInputElement>) => {
      if (e.key === "Enter" && todoText.trim()) {
        onAddTodo(todoText.trim(), todoRepeat, todoDueDate);
        setTodoText("");
        setTodoDueDate("");
      }
    },
    [todoText, todoRepeat, todoDueDate, onAddTodo],
  );

  const handleRepeatChange = useCallback(
    (e: JSX.TargetedEvent<HTMLSelectElement, Event>) => {
      const val = (e.target as HTMLSelectElement).value as Todo["repeat"];
      setTodoRepeat(val);
      setActiveTab(val === "none" ? "focus" : "routines");
    },
    [setActiveTab],
  );

  const handleTabChange = useCallback(
    (tabVal: "focus" | "routines") => {
      setActiveView("list");
      setActiveTab(tabVal);
      setTodoRepeat(tabVal === "focus" ? "none" : "daily");
      handleTabChangeUI(tabVal);
    },
    [setActiveView, setActiveTab, handleTabChangeUI],
  );

  return {
    todoText,
    setTodoText,
    todoRepeat,
    todoDueDate,
    setTodoDueDate,
    handleAddTodoClick,
    handleKeyPress,
    handleRepeatChange,
    handleTabChange,
  };
}

import { useState, useEffect } from "preact/hooks";
import { Todo } from "@/types/types.js";
import { GoogleAuthApi } from "@/infrastructure/api/GoogleAuthApi.js";
import { GoogleCalendarApi } from "@/infrastructure/api/GoogleCalendarApi.js";
import { logger } from "@/utils/logger.js";

const _authApi = new GoogleAuthApi();
const _calendarApi = new GoogleCalendarApi();

interface CalendarModalData {
  title: string;
  items: {
    type: "task" | "event";
    text: string;
    completed?: boolean;
    time?: string;
  }[];
}

interface UseCalendarOptions {
  todos: Todo[];
}

/**
 * Takvim state + Google Calendar sync (AGENTS.md 6.3: presentation/hooks/).
 * View sadece JSX render eder; takvim fetch + modal state burada yaşar.
 */
export function useCalendar({ todos }: UseCalendarOptions) {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [activeModalData, setActiveModalData] =
    useState<CalendarModalData | null>(null);
  const [calendarEvents, setCalendarEvents] = useState<any[]>([]);

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  const handlePrevMonth = () => {
    setCurrentDate(new Date(year, month - 1, 1));
  };

  const handleNextMonth = () => {
    setCurrentDate(new Date(year, month + 1, 1));
  };

  useEffect(() => {
    let isMounted = true;
    const fetchCalendar = async () => {
      const syncData = await new Promise<any>((resolve) =>
        chrome.storage.sync.get(["syncEnabled", "syncCalendarEnabled"], (res) =>
          resolve(res),
        ),
      );
      const syncEnabled = syncData.syncEnabled === true;
      const calendarEnabled = syncData.syncCalendarEnabled === true;
      if (syncEnabled && calendarEnabled) {
        try {
          const token = await _authApi.getAuthToken(false);
          const startStr = new Date(year, month, 1, 0, 0, 0).toISOString();
          const endStr = new Date(year, month + 1, 0, 23, 59, 59).toISOString();
          const items = await _calendarApi.getCalendarEvents(
            token,
            startStr,
            endStr,
          );
          if (isMounted) {
            setCalendarEvents(items);
          }
        } catch (e) {
          logger.error("[CalendarView] Google Calendar fetching error:", e);
        } finally {
          // calendar sync finished
        }
      } else {
        setCalendarEvents([]);
      }
    };
    fetchCalendar();
    return () => {
      isMounted = false;
    };
  }, [currentDate]);

  // Group tasks by date key: YYYY-MM-DD
  const tasksByDate: Record<string, { text: string; completed: boolean }[]> =
    {};
  todos.forEach((todo) => {
    // 1. Completed dates
    const dates =
      todo.completedDates ||
      (todo.lastCompletedDate ? [todo.lastCompletedDate] : []);
    dates.forEach((dateStr) => {
      const date = new Date(dateStr);
      const dateKey = `${date.getFullYear()}-${date.getMonth()}-${date.getDate()}`;
      if (!tasksByDate[dateKey]) {
        tasksByDate[dateKey] = [];
      }
      if (
        !tasksByDate[dateKey].some((t) => t.text === todo.text && t.completed)
      ) {
        tasksByDate[dateKey].push({ text: todo.text, completed: true });
      }
    });

    // 2. Due dates
    if (todo.dueDate) {
      const parts = todo.dueDate.split("-");
      if (parts.length === 3) {
        const y = parseInt(parts[0], 10);
        const m = parseInt(parts[1], 10) - 1;
        const d = parseInt(parts[2], 10);
        const dateKey = `${y}-${m}-${d}`;
        if (!tasksByDate[dateKey]) {
          tasksByDate[dateKey] = [];
        }
        if (!tasksByDate[dateKey].some((t) => t.text === todo.text)) {
          tasksByDate[dateKey].push({
            text: todo.text,
            completed: todo.completed,
          });
        }
      }
    }
  });

  // Group events by date key: YYYY-MM-DD
  const eventsByDate: Record<string, any[]> = {};
  calendarEvents.forEach((event) => {
    if (!event.start) {
      return;
    }
    const dateStr = event.start.dateTime || event.start.date;
    if (!dateStr) {
      return;
    }
    let dateKey = "";
    if (event.start.date) {
      const parts = event.start.date.split("-");
      if (parts.length === 3) {
        const y = parseInt(parts[0], 10);
        const m = parseInt(parts[1], 10) - 1;
        const d = parseInt(parts[2], 10);
        dateKey = `${y}-${m}-${d}`;
      }
    } else {
      const date = new Date(dateStr);
      dateKey = `${date.getFullYear()}-${date.getMonth()}-${date.getDate()}`;
    }
    if (dateKey) {
      if (!eventsByDate[dateKey]) {
        eventsByDate[dateKey] = [];
      }
      eventsByDate[dateKey].push(event);
    }
  });

  return {
    currentDate,
    year,
    month,
    activeModalData,
    setActiveModalData,
    calendarEvents,
    tasksByDate,
    eventsByDate,
    handlePrevMonth,
    handleNextMonth,
  };
}

import { useState, useEffect } from "preact/hooks";
import {
  kpssQuizFlowService,
  AIConfig,
} from "@/services/kpss/kpssQuizFlowService.js";
import {
  getPastExamQuestions,
  KpssPastQuiz,
} from "@/services/kpss/kpssQuizService.js";
import { QuizQuestion } from "@/services/kpss/kpssAiService.js";
import { logger } from "@/utils/logger.js";

interface UseKpssQuizOptions {
  currentSubject: () => string;
  t: Record<string, string>;
  aiConfig: AIConfig;
  onQuizCompleted: () => Promise<void> | void;
  onLoadPastQuizzes: () => Promise<Record<string, KpssPastQuiz>>;
  onSubjectChange?: (subject: string) => void;
  onCloseDetail?: () => void;
}

export function useKpssQuiz({
  currentSubject,
  t,
  aiConfig,
  onQuizCompleted,
  onLoadPastQuizzes,
  onSubjectChange,
  onCloseDetail,
}: UseKpssQuizOptions) {
  const [activeQuizTopic, setActiveQuizTopic] = useState<string | null>(null);
  const [quizStep, setQuizStep] = useState<"intro" | "questions" | "result">(
    "intro",
  );
  const [selectedQuizCount, setSelectedQuizCount] = useState(5);
  const [quizLoading, setQuizLoading] = useState(false);
  const [isBackgroundLoading, setIsBackgroundLoading] = useState(false);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<number[]>([]);
  const [quizResultScore, setQuizResultScore] = useState(0);
  const [quizError, setQuizError] = useState<string | null>(null);
  const [pastQuizzes, setPastQuizzes] = useState<Record<string, KpssPastQuiz>>(
    {},
  );
  // Birikimli başarı: konuda çözülen toplam soru / doğru (min 100 soru + %80 şartı)
  const [cumulative, setCumulative] = useState<{
    totalQuestions: number;
    totalCorrect: number;
  }>({ totalQuestions: 0, totalCorrect: 0 });

  const fetchQuizFromAI = async (
    subjectKey: string,
    topicName: string,
    count: number,
  ) => {
    setQuizLoading(true);
    setIsBackgroundLoading(false);
    setQuizError(null);
    setQuizStep("questions");
    setQuizQuestions([]);

    try {
      // GeÃ§miÅŸte Ã§Ã¶zÃ¼len AI sorularÄ± (pastQuizzes) â€” tekrar sorulmamasÄ± iÃ§in exclude
      const quizKey = `${subjectKey}_${topicName}`;
      const pastQuiz = pastQuizzes[quizKey];
      const pastQuestions: QuizQuestion[] = pastQuiz?.questions ?? [];

      // Ä°lk soru AI'dan beklenir (boÅŸ ekran gÃ¶rÃ¼nmez), kalanlar arka planda Ã¼retilir
      const firstList = await kpssQuizFlowService.fetchQuestionsSubsetFromAI(
        subjectKey,
        topicName,
        1,
        aiConfig,
        pastQuestions,
        pastQuestions.length > 0 ? pastQuestions : [],
      );
      if (firstList.length === 0) {
        throw new Error("Soru Ã¼retilemedi.");
      }

      const firstQuestion = firstList[0];
      setQuizQuestions([firstQuestion]);
      setCurrentQuestionIndex(0);
      setSelectedAnswers(new Array(count).fill(-1));
      setQuizLoading(false);

      if (count > 1) {
        setIsBackgroundLoading(true);
        kpssQuizFlowService
          .fetchQuestionsSubsetFromAI(
            subjectKey,
            topicName,
            count - 1,
            aiConfig,
            [...pastQuestions, firstQuestion],
            pastQuestions.length > 0 ? pastQuestions : [firstQuestion],
          )
          .then((remainingQuestions) => {
            if (remainingQuestions.length > 0) {
              setQuizQuestions((prev) => {
                const updated = [...prev, ...remainingQuestions];
                return updated.slice(0, count);
              });
            }
          })
          .catch((err) => {
            logger.error("Background questions pre-fetch failed:", err);
          })
          .finally(() => {
            setIsBackgroundLoading(false);
          });
      }
    } catch (err: unknown) {
      logger.error("AI quiz generation error:", err);
      setQuizError(t.kpss_quiz_error);
      setQuizLoading(false);
      setIsBackgroundLoading(false);
    }
  };

  const handleFinishQuiz = async () => {
    try {
      const { scorePercentage, updatedPastQuizzes, cumulative: cum } =
        await kpssQuizFlowService.evaluateAndSaveQuizResult({
          currentSubject: currentSubject(),
          activeQuizTopic: activeQuizTopic!,
          quizQuestions,
          selectedAnswers,
          pastQuizzes,
        });

      setQuizResultScore(scorePercentage);
      setCumulative(cum);
      setQuizStep("result");
      setPastQuizzes(updatedPastQuizzes);
      await onQuizCompleted();
    } catch (err) {
      logger.error(
        "Failed to update status and save stats on quiz completion:",
        err,
      );
    }
  };

  const handleSaveExternalResult = async (correct: number, total: number) => {
    try {
      const { scorePercentage, updatedPastQuizzes, cumulative: cum } =
        await kpssQuizFlowService.saveExternalQuizResult({
          currentSubject: currentSubject(),
          activeQuizTopic: activeQuizTopic!,
          correctCount: correct,
          totalCount: total,
          pastQuizzes,
        });

      setQuizResultScore(scorePercentage);
      setCumulative(cum);
      setQuizQuestions([]);
      setSelectedAnswers([]);
      setQuizStep("result");
      setPastQuizzes(updatedPastQuizzes);
      await onQuizCompleted();
    } catch (err) {
      logger.error("Failed to save external quiz result:", err);
    }
  };

  const handleStartQuiz = (topic: string, subject?: string) => {
    const targetSubject = subject || currentSubject();
    if (subject && subject !== currentSubject()) {
      onSubjectChange?.(subject);
    }
    setActiveQuizTopic(topic);
    // Detail modal'ını kapat
    onCloseDetail?.();
    setQuizStep("intro");
    setSelectedQuizCount(5);
    setQuizQuestions([]);
    setSelectedAnswers([]);
    setQuizError(null);
    setCumulative({ totalQuestions: 0, totalCorrect: 0 });
  };

  const handleStartPastExam = (
    year: string,
    subject: string,
    countLimit?: number,
    selectedChapter?: string,
  ) => {
    const questions = getPastExamQuestions(
      year,
      subject,
      countLimit,
      selectedChapter,
    );

    if (questions.length === 0) {
      setQuizError(t.kpss_quiz_no_past);
      setQuizStep("questions");
      setActiveQuizTopic(t.kpss_quiz_error_title);
      return;
    }

    setQuizQuestions(questions);
    setCurrentQuestionIndex(0);
    setSelectedAnswers(new Array(questions.length).fill(-1));
    setSelectedQuizCount(questions.length);
    setQuizStep("questions");

    const subjectName =
      subject === "all"
        ? t.kpss_subject_mixed
        : subject === "cografya"
          ? t.kpss_subject_geography
          : subject === "tarih"
            ? t.kpss_subject_history
            : "Matematik";

    const yearName =
      year === "karma"
        ? t.kpss_exam_mixed_years || "Karma Deneme"
        : year === "tarih_arsivi"
          ? `Tarih Soru Arşivi (${selectedChapter && selectedChapter !== "all" ? selectedChapter : "Tüm Üniteler"})`
          : year;

    setActiveQuizTopic(`${yearName} (${questions.length} Soru)`);
    setQuizLoading(false);
    setIsBackgroundLoading(false);
  };

  const handleReviewPastQuiz = async (topic: string, subject?: string) => {
    const targetSubject = subject || currentSubject();
    if (subject && subject !== currentSubject()) {
      onSubjectChange?.(subject);
    }
    setActiveQuizTopic(topic);
    onCloseDetail?.();
    const quizKey = `${targetSubject}_${topic}`;
    // Esnek quizKey araması (Tam eşleşme veya normalize eşleşme)
    let pastQuiz = pastQuizzes[quizKey];
    if (!pastQuiz) {
      const normTopic = topic.toLowerCase().trim();
      const matchedKey = Object.keys(pastQuizzes).find((k) => {
        const [s, t] = k.split("_");
        return s === targetSubject && t && t.toLowerCase().trim() === normTopic;
      });
      if (matchedKey) {
        pastQuiz = pastQuizzes[matchedKey];
      }
    }

    // Cumulative verisini veritabanından çek
    let rec: { totalQuestions?: number; totalCorrect?: number; score?: number } | undefined;
    try {
      const progressList = await kpssQuizFlowService.getKpssProgress();
      rec = progressList.find(
        (p) => p.subject === targetSubject && p.topic === topic,
      );
      setCumulative({
        totalQuestions: rec?.totalQuestions ?? 0,
        totalCorrect: rec?.totalCorrect ?? 0,
      });
    } catch {
      // fallback
    }

    if (pastQuiz) {
      setQuizQuestions(pastQuiz.questions || []);
      setSelectedAnswers(pastQuiz.selectedAnswers || []);
      setQuizResultScore(pastQuiz.score);
      setQuizStep("result");
    } else if (rec && ((rec.totalQuestions ?? 0) > 0 || (rec.score !== undefined && rec.score > 0))) {
      // Eğer geçmiş sınav kaydı detay soru içermiyorsa ama konu çözülmüşse yine de Sonuç/İnceleme ekranını aç
      setQuizQuestions([]);
      setSelectedAnswers([]);
      setQuizResultScore(rec.score ?? 0);
      setQuizStep("result");
    } else {
      setQuizStep("intro");
      setSelectedQuizCount(5);
      setQuizQuestions([]);
      setSelectedAnswers([]);
    }
  };

  const loadPastQuizzes = async () => {
    const loaded = await onLoadPastQuizzes();
    setPastQuizzes(loaded);
  };

  // Başlangıçta geçmiş testleri yükle — aynı konuya tekrar girilince sonuç/sorular görünsün
  useEffect(() => {
    void loadPastQuizzes();
  }, []);

  return {
    activeQuizTopic,
    setActiveQuizTopic,
    quizStep,
    setQuizStep,
    selectedQuizCount,
    setSelectedQuizCount,
    quizLoading,
    setQuizLoading,
    isBackgroundLoading,
    quizQuestions,
    setQuizQuestions,
    currentQuestionIndex,
    setCurrentQuestionIndex,
    selectedAnswers,
    setSelectedAnswers,
    quizResultScore,
    quizError,
    setQuizError,
    pastQuizzes,
    cumulative,
    fetchQuizFromAI,
    handleFinishQuiz,
    handleSaveExternalResult,
    handleStartQuiz,
    handleReviewPastQuiz,
    handleStartPastExam,
    loadPastQuizzes,
  };
}

import { useState, useEffect, useRef, useCallback } from "preact/hooks";
import { Language, PomodoroLog } from "@/types/types.js";
import {
  pomodoroManager,
  AlarmItem,
} from "@/infrastructure/services/PomodoroManagerService.js";
import { logger } from "@/utils/logger.js";

interface UsePomodoroOptions {
  lang: Language;
  t: Record<string, string>;
}

/**
 * Pomodoro timer + stopwatch + alarms + zen garden state & handlers.
 * (AGENTS.md 6.3: presentation/hooks/) — View sadece JSX render eder.
 */
export function usePomodoro({ lang, t }: UsePomodoroOptions) {
  // Tab navigation
  const [activeTab, setActiveTab] = useState<"timer" | "zen">("timer");

  // Zen Garden & History states
  const [pomodoroHistory, setPomodoroHistory] = useState<PomodoroLog[]>([]);
  const [showPlantModal, setShowPlantModal] = useState(false);
  const [focusNote, setFocusNote] = useState("");
  const [selectedElement, setSelectedElement] =
    useState<PomodoroLog["element"]>("bonsai");
  const [lastCompletedDuration, setLastCompletedDuration] = useState(25 * 60);
  const [lastCompletedStartTime, setLastCompletedStartTime] = useState("");
  const [lastCompletedEndTime, setLastCompletedEndTime] = useState("");
  const [searchQuery, setSearchQuery] = useState("");

  // Pomodoro State
  const [customTimes, setCustomTimes] = useState<{
    focus: number;
    short: number;
    long: number;
  }>({
    focus: 25 * 60,
    short: 5 * 60,
    long: 15 * 60,
  });
  const [pomoMode, setPomoMode] = useState<"focus" | "short" | "long">("focus");
  const [pomoTimeLeft, setPomoTimeLeft] = useState(25 * 60);
  const [pomoTotalTime, setPomoTotalTime] = useState(25 * 60);
  const [pomoRunning, setPomoRunning] = useState(false);
  const [pomoEndTime, setPomoEndTime] = useState(0);
  const pomoTimerRef = useRef<number | null>(null);

  // Synced Stopwatch State
  const [swTime, setSwTime] = useState(0);
  const [swRunning, setSwRunning] = useState(false);
  const [swStartTime, setSwStartTime] = useState(0);

  // Synced Alarms State
  const [alarms, setAlarms] = useState<AlarmItem[]>([]);
  const [alarmInput, setAlarmInput] = useState("");

  // Notification and Audio Alert Helper
  const notify = useCallback((msg: string) => {
    try {
      const audio = new Audio(
        "https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3",
      );
      audio.volume = 0.4;
      audio.play();
    } catch (e) {
      logger.error("[PomodoroView] notify audio failed:", e);
    }
    if (Notification.permission === "granted") {
      new Notification("Life OS", { body: msg });
    } else {
      Notification.requestPermission();
    }
  }, []);

  // Sync with storage on mount and subscribe to changes
  useEffect(() => {
    // 1. Pomodoro initial state
    pomodoroManager.getState().then((state) => {
      setPomoMode(state.mode);
      setPomoTimeLeft(state.timeLeft);
      setPomoTotalTime(state.totalTime);
      setPomoRunning(state.running);
      setPomoEndTime(state.endTime);
    });

    const unsubPomo = pomodoroManager.onStateChanged((state) => {
      setPomoMode(state.mode);
      setPomoTimeLeft(state.timeLeft);
      setPomoTotalTime(state.totalTime);
      setPomoRunning(state.running);
      setPomoEndTime(state.endTime);
    });

    // 2. Stopwatch initial state
    pomodoroManager.getStopwatch().then((s) => {
      setSwRunning(s.running);
      setSwTime(s.time);
      setSwStartTime(s.startTime);
    });

    const unsubSw = pomodoroManager.onStopwatchChanged((s) => {
      setSwRunning(s.running);
      setSwTime(s.time);
      setSwStartTime(s.startTime);
    });

    // 3. Alarms initial state
    pomodoroManager.getAlarms().then((list) => {
      setAlarms(list);
    });

    const unsubAlarms = pomodoroManager.onAlarmsChanged((list) => {
      setAlarms(list);
    });

    // 4. Pomodoro history initial state
    chrome.storage.sync.get(["pomodoroHistory"], (res) => {
      setPomodoroHistory((res.pomodoroHistory as PomodoroLog[]) || []);
    });

    // 5. Load custom times settings
    chrome.storage.sync.get(["pomoCustomTimes"], (res) => {
      const times = res.pomoCustomTimes as
        { focus: number; short: number; long: number } | undefined;
      if (times) {
        setCustomTimes(times);
      }
    });

    return () => {
      unsubPomo();
      unsubSw();
      unsubAlarms();
      if (pomoTimerRef.current) {
        clearInterval(pomoTimerRef.current);
      }
    };
  }, []);

  // Tick Pomodoro timer locally
  useEffect(() => {
    if (pomoTimerRef.current) {
      clearInterval(pomoTimerRef.current);
      pomoTimerRef.current = null;
    }

    if (pomoRunning) {
      pomoTimerRef.current = window.setInterval(() => {
        const now = Date.now();
        const remaining = Math.max(0, Math.round((pomoEndTime - now) / 1000));

        setPomoTimeLeft(remaining);
        if (remaining === 0) {
          if (pomoTimerRef.current) {
            clearInterval(pomoTimerRef.current);
          }
          setPomoRunning(false);
          notify(
            pomoMode === "focus"
              ? "Focus session completed! Plant your Zen Element."
              : "Break finished!",
          );
          if (pomoMode === "focus") {
            setLastCompletedDuration(pomoTotalTime);
            setLastCompletedStartTime(
              new Date(Date.now() - pomoTotalTime * 1000).toISOString(),
            );
            setLastCompletedEndTime(new Date().toISOString());
            setShowPlantModal(true);
          }
        }
      }, 1000);
    }

    return () => {
      if (pomoTimerRef.current) {
        clearInterval(pomoTimerRef.current);
      }
    };
  }, [pomoRunning, pomoEndTime, pomoMode, pomoTotalTime, notify]);

  // Tick Stopwatch locally
  useEffect(() => {
    let interval: number | null = null;
    if (swRunning) {
      interval = window.setInterval(() => {
        const elapsed = Math.max(
          0,
          Math.floor((Date.now() - swStartTime) / 1000),
        );
        chrome.storage.local.get(["stopwatch_state"], (resData) => {
          const res = resData as Record<string, any>;
          const offset = res["stopwatch_state"]?.time || 0;
          setSwTime(offset + elapsed);
        });
      }, 1000);
    }
    return () => {
      if (interval) {
        clearInterval(interval);
      }
    };
  }, [swRunning, swStartTime]);

  // Monitor active alarms list in real-time
  useEffect(() => {
    const checkAlarms = setInterval(() => {
      const now = new Date();
      const currentHHMM = now.toTimeString().slice(0, 5);

      alarms.forEach(async (alarm) => {
        if (alarm.enabled && alarm.time === currentHHMM) {
          await pomodoroManager.toggleAlarm(alarm.id, false);
          notify(`${t.alarm_time_label} ${alarm.time}`);
        }
      });
    }, 1000);

    return () => clearInterval(checkAlarms);
  }, [alarms, lang, t, notify]);

  // Main Pomodoro Handlers
  const handlePomoModeChange = async (mode: "focus" | "short" | "long") => {
    const totalTime = customTimes[mode];
    await pomodoroManager.resetTimer(mode, totalTime);
  };

  const handleCustomTimeChange = async (
    mode: "focus" | "short" | "long",
    mins: number,
  ) => {
    if (isNaN(mins) || mins <= 0) {
      return;
    }
    const seconds = mins * 60;
    const newTimes = { ...customTimes, [mode]: seconds };
    setCustomTimes(newTimes);
    chrome.storage.sync.set({ pomoCustomTimes: newTimes });

    if (!pomoRunning && pomoMode === mode) {
      await pomodoroManager.resetTimer(mode, seconds);
    }
  };

  const handlePomoStart = async () => {
    await pomodoroManager.startTimer(pomoTimeLeft, pomoMode, pomoTotalTime);
  };

  const handlePomoPause = async () => {
    await pomodoroManager.pauseTimer(pomoTimeLeft);
  };

  const handlePomoReset = async () => {
    await pomodoroManager.resetTimer(pomoMode, pomoTotalTime);
  };

  // Synced Stopwatch Handlers
  const handleSwStart = async () => {
    const state = await pomodoroManager.startStopwatch(swTime);
    setSwRunning(true);
    setSwStartTime(state.startTime);
  };

  const handleSwPause = async () => {
    await pomodoroManager.pauseStopwatch(swTime);
    setSwRunning(false);
  };

  const handleSwReset = async () => {
    await pomodoroManager.resetStopwatch();
    setSwTime(0);
    setSwRunning(false);
  };

  // Synced Alarms Handlers
  const handleAddAlarm = async () => {
    if (!alarmInput) {
      return;
    }
    const list = await pomodoroManager.addAlarm(alarmInput);
    setAlarms(list);
    setAlarmInput("");
  };

  const handleToggleAlarm = async (id: string, enabled: boolean) => {
    const list = await pomodoroManager.toggleAlarm(id, enabled);
    setAlarms(list);
  };

  const handleDeleteAlarm = async (id: string) => {
    const list = await pomodoroManager.deleteAlarm(id);
    setAlarms(list);
  };

  // Zen Garden Handlers
  const handlePlantElement = async () => {
    let position = -1;
    const occupied = new Set(pomodoroHistory.map((h) => h.position));
    for (let i = 0; i < 25; i++) {
      if (!occupied.has(i)) {
        position = i;
        break;
      }
    }
    if (position === -1) {
      position = pomodoroHistory.length % 25;
    }

    const newLog: PomodoroLog = {
      id: Math.random().toString(36).substring(2, 9),
      startTime: lastCompletedStartTime || new Date().toISOString(),
      endTime: lastCompletedEndTime || new Date().toISOString(),
      duration: lastCompletedDuration,
      mode: "focus",
      note: focusNote.trim() || t.pomodoro_session_title,
      element: selectedElement,
      position,
    };

    const nextHistory = [
      ...pomodoroHistory.filter((h) => h.position !== position),
      newLog,
    ];
    await new Promise<void>((r) =>
      chrome.storage.sync.set({ pomodoroHistory: nextHistory }, r),
    );
    setPomodoroHistory(nextHistory);
    setShowPlantModal(false);
    setFocusNote("");
  };

  return {
    activeTab,
    setActiveTab,
    pomodoroHistory,
    showPlantModal,
    setShowPlantModal,
    focusNote,
    setFocusNote,
    selectedElement,
    setSelectedElement,
    searchQuery,
    setSearchQuery,
    customTimes,
    pomoMode,
    pomoTimeLeft,
    pomoRunning,
    pomoTotalTime,
    swTime,
    swRunning,
    alarms,
    alarmInput,
    setAlarmInput,
    handlePomoModeChange,
    handleCustomTimeChange,
    handlePomoStart,
    handlePomoPause,
    handlePomoReset,
    handleSwStart,
    handleSwPause,
    handleSwReset,
    handleAddAlarm,
    handleToggleAlarm,
    handleDeleteAlarm,
    handlePlantElement,
  };
}

import { useState, useEffect, useRef, useCallback } from "preact/hooks";
import {
  pomodoroManager,
  PomoState,
  AlarmItem,
} from "@/infrastructure/services/PomodoroManagerService.js";
import type { Language } from "@/domain/value-objects/Language.js";

const POMO_MODE_TIMES = { focus: 25 * 60, short: 5 * 60, long: 15 * 60 };

export function usePopup() {
  const [popupTab, setPopupTab] = useState<"pomo" | "detox" | "volume">("pomo");
  const [lang, setLang] = useState<Language>("en");

  // --- Pomodoro Sync States ---
  const [pomoState, setPomoState] = useState<PomoState>({
    mode: "focus",
    running: false,
    timeLeft: POMO_MODE_TIMES.focus,
    totalTime: POMO_MODE_TIMES.focus,
    endTime: 0,
  });

  const pomoTimerRef = useRef<number | null>(null);

  // --- Stopwatch Sync States ---
  const [swRunning, setSwRunning] = useState(false);
  const [swTime, setSwTime] = useState(0);
  const [swStartTime, setSwStartTime] = useState(0);

  // --- Alarms Sync States ---
  const [alarms, setAlarms] = useState<AlarmItem[]>([]);
  const [alarmInput, setAlarmInput] = useState("");

  // --- Detox Sync States ---
  const [detoxEnabled, setDetoxEnabled] = useState(false);
  const [detoxBlockedSites, setDetoxBlockedSites] = useState<string[]>([]);
  const [detoxEndTime, setDetoxEndTime] = useState(0);
  const [detoxDuration, setDetoxDuration] = useState(30 * 60 * 1000); // 30m default
  const [detoxTimeLeft, setDetoxTimeLeft] = useState(0);

  const loadDetoxSettings = useCallback(() => {
    chrome.storage.sync.get(
      ["detox_enabled", "detox_blocked_sites", "detox_end_time"],
      (resData) => {
        const res = resData as Record<string, any>;
        const isEnabled = res.detox_enabled || false;
        const end = res.detox_end_time || 0;
        setDetoxEnabled(isEnabled);
        setDetoxBlockedSites(res.detox_blocked_sites || []);
        setDetoxEndTime(end);
      },
    );
  }, []);

  // 1. Initial State Retrieval & Synchronization Subscriptions
  useEffect(() => {
    // Load UI Language
    chrome.storage.sync.get(["lang"], (res) => {
      if (res.lang) {
        setLang(res.lang as Language);
      } else if (typeof chrome !== "undefined" && chrome.i18n) {
        const uiLang = chrome.i18n.getUILanguage();
        setLang(uiLang.startsWith("tr") ? "tr" : "en");
      }
    });

    // A. Pomodoro timers
    pomodoroManager.getState().then(setPomoState);
    const unsubPomo = pomodoroManager.onStateChanged(setPomoState);

    // B. Stopwatch
    pomodoroManager.getStopwatch().then((s) => {
      setSwRunning(s.running);
      setSwTime(s.time);
      setSwStartTime(s.startTime);
    });
    const unsubSw = pomodoroManager.onStopwatchChanged((s) => {
      setSwRunning(s.running);
      setSwTime(s.time);
      setSwStartTime(s.startTime);
    });

    // C. Alarms
    pomodoroManager.getAlarms().then(setAlarms);
    const unsubAlarms = pomodoroManager.onAlarmsChanged(setAlarms);

    // D. Detox Settings
    loadDetoxSettings();
    const unsubStorage = (
      changes: { [key: string]: chrome.storage.StorageChange },
      areaName: string,
    ) => {
      if (areaName === "sync") {
        if (changes["lang"]) {
          setLang(changes["lang"].newValue as Language);
        }
        if (
          changes["detox_enabled"] ||
          changes["detox_blocked_sites"] ||
          changes["detox_end_time"]
        ) {
          loadDetoxSettings();
        }
      }
    };
    chrome.storage.onChanged.addListener(unsubStorage);

    return () => {
      unsubPomo();
      unsubSw();
      unsubAlarms();
      chrome.storage.onChanged.removeListener(unsubStorage);
      if (pomoTimerRef.current) {
        clearInterval(pomoTimerRef.current);
      }
    };
  }, [loadDetoxSettings]);

  // 2. Tick Pomodoro Timer Locally
  useEffect(() => {
    if (pomoTimerRef.current) {
      clearInterval(pomoTimerRef.current);
      pomoTimerRef.current = null;
    }

    if (pomoState.running) {
      pomoTimerRef.current = window.setInterval(() => {
        const now = Date.now();
        const remaining = Math.max(
          0,
          Math.round((pomoState.endTime - now) / 1000),
        );

        setPomoState((prev) => {
          if (remaining === 0) {
            if (pomoTimerRef.current) {
              clearInterval(pomoTimerRef.current);
            }
            return { ...prev, running: false, timeLeft: 0 };
          }
          return { ...prev, timeLeft: remaining };
        });
      }, 1000);
    }

    return () => {
      if (pomoTimerRef.current) {
        clearInterval(pomoTimerRef.current);
      }
    };
  }, [pomoState.running, pomoState.endTime]);

  // 3. Tick Stopwatch Locally
  useEffect(() => {
    let swInterval: number | null = null;
    if (swRunning) {
      swInterval = window.setInterval(() => {
        const elapsed = Math.max(
          0,
          Math.floor((Date.now() - swStartTime) / 1000),
        );
        chrome.storage.local.get(["stopwatch_state"], (resData) => {
          const res = resData as Record<string, any>;
          const offset = res["stopwatch_state"]?.time || 0;
          setSwTime(offset + elapsed);
        });
      }, 1000);
    }
    return () => {
      if (swInterval) {
        clearInterval(swInterval);
      }
    };
  }, [swRunning, swStartTime]);

  // 4. Tick Detoks Blocker Timer Locally
  useEffect(() => {
    let detoxInterval: number | null = null;
    if (detoxEnabled && detoxEndTime !== -1) {
      const calcDetox = () => {
        const remaining = Math.max(
          0,
          Math.round((detoxEndTime - Date.now()) / 1000),
        );
        setDetoxTimeLeft(remaining);
        if (remaining === 0) {
          handleDisableDetox();
        }
      };
      calcDetox();
      detoxInterval = window.setInterval(calcDetox, 1000);
    } else {
      setDetoxTimeLeft(0);
    }
    return () => {
      if (detoxInterval) {
        clearInterval(detoxInterval);
      }
    };
  }, [detoxEnabled, detoxEndTime]);

  // --- Pomodoro Action Handles ---
  const handlePomoTabChange = useCallback(
    async (mode: "focus" | "short" | "long") => {
      const totalTime = POMO_MODE_TIMES[mode];
      const newState = await pomodoroManager.resetTimer(mode, totalTime);
      setPomoState(newState);
    },
    [],
  );

  const handlePomoPlayPause = useCallback(async () => {
    if (pomoState.running) {
      const newState = await pomodoroManager.pauseTimer(pomoState.timeLeft);
      setPomoState(newState);
    } else {
      const newState = await pomodoroManager.startTimer(
        pomoState.timeLeft,
        pomoState.mode,
        pomoState.totalTime,
      );
      setPomoState(newState);
    }
  }, [pomoState]);

  const handlePomoReset = useCallback(async () => {
    const newState = await pomodoroManager.resetTimer(
      pomoState.mode,
      pomoState.totalTime,
    );
    setPomoState(newState);
  }, [pomoState]);

  // --- Stopwatch Action Handles ---
  const handleSwPlayPause = useCallback(async () => {
    if (swRunning) {
      await pomodoroManager.pauseStopwatch(swTime);
      setSwRunning(false);
    } else {
      const state = await pomodoroManager.startStopwatch(swTime);
      setSwRunning(true);
      setSwStartTime(state.startTime);
    }
  }, [swRunning, swTime]);

  const handleSwReset = useCallback(async () => {
    await pomodoroManager.resetStopwatch();
    setSwTime(0);
    setSwRunning(false);
  }, []);

  // --- Alarms Action Handles ---
  const handleAddAlarm = useCallback(async () => {
    if (!alarmInput) {
      return;
    }
    const list = await pomodoroManager.addAlarm(alarmInput);
    setAlarms(list);
    setAlarmInput("");
  }, [alarmInput]);

  const handleToggleAlarm = useCallback(
    async (id: string, enabled: boolean) => {
      const list = await pomodoroManager.toggleAlarm(id, enabled);
      setAlarms(list);
    },
    [],
  );

  const handleDeleteAlarm = useCallback(async (id: string) => {
    const list = await pomodoroManager.deleteAlarm(id);
    setAlarms(list);
  }, []);

  // --- Detoks Action Handles ---
  const handleTogglePopupSite = useCallback(
    (siteDomains: string[]) => {
      const isSelected = detoxBlockedSites.includes(siteDomains[0]);
      let updated;
      if (isSelected) {
        updated = detoxBlockedSites.filter((d) => !siteDomains.includes(d));
      } else {
        updated = [...detoxBlockedSites, ...siteDomains];
      }
      setDetoxBlockedSites(updated);
      chrome.storage.sync.set({ detox_blocked_sites: updated });
    },
    [detoxBlockedSites],
  );

  const handleEnableDetox = useCallback(() => {
    if (detoxBlockedSites.length === 0) {
      return;
    }
    const end = detoxDuration === -1 ? -1 : Date.now() + detoxDuration;
    chrome.storage.sync.set(
      {
        detox_enabled: true,
        detox_blocked_sites: detoxBlockedSites,
        detox_end_time: end,
      },
      () => {
        setDetoxEnabled(true);
        setDetoxEndTime(end);
      },
    );
  }, [detoxBlockedSites, detoxDuration]);

  const handleDisableDetox = useCallback(() => {
    chrome.storage.sync.set(
      {
        detox_enabled: false,
        detox_end_time: 0,
      },
      () => {
        setDetoxEnabled(false);
        setDetoxEndTime(0);
        setDetoxTimeLeft(0);
      },
    );
  }, []);

  return {
    popupTab,
    setPopupTab,
    lang,
    pomoState,
    swRunning,
    swTime,
    alarms,
    alarmInput,
    setAlarmInput,
    detoxEnabled,
    detoxBlockedSites,
    detoxEndTime,
    detoxDuration,
    setDetoxDuration,
    detoxTimeLeft,
    handlePomoTabChange,
    handlePomoPlayPause,
    handlePomoReset,
    handleSwPlayPause,
    handleSwReset,
    handleAddAlarm,
    handleToggleAlarm,
    handleDeleteAlarm,
    handleTogglePopupSite,
    handleEnableDetox,
    handleDisableDetox,
  };
}

import { useState, useEffect, useCallback } from "preact/hooks";
import { prayerService } from "@/services/prayerService.js";
import type { PrayerTimes } from "@/types/prayer.js";
import { logger } from "@/utils/logger.js";

/**
 * Prayer times state + business logic (AGENTS.md 6.3: presentation/hooks/).
 * View sadece JSX render eder; storage + fetch + highlight hesabı burada yaşar.
 */
export function usePrayer() {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const [city, setCity] = useState("Istanbul");
  const [times, setTimes] = useState<PrayerTimes | null>(null);
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [currentPrayerIdx, setCurrentPrayerIdx] = useState(-1);

  const calculateHighlight = useCallback((prayerTimes: PrayerTimes) => {
    const now = new Date();
    const currentTime = now.getHours() * 60 + now.getMinutes();

    const timeToMinutes = (tStr: string) => {
      const [h, m] = tStr.split(":").map(Number);
      return h * 60 + m;
    };

    const schedule = [
      timeToMinutes(prayerTimes.Fajr),
      timeToMinutes(prayerTimes.Sunrise),
      timeToMinutes(prayerTimes.Dhuhr),
      timeToMinutes(prayerTimes.Asr),
      timeToMinutes(prayerTimes.Maghrib),
      timeToMinutes(prayerTimes.Isha),
    ];

    let idx = -1;
    for (let i = 0; i < schedule.length; i++) {
      if (currentTime >= schedule[i]) {
        idx = i;
      }
    }
    setCurrentPrayerIdx(idx);
  }, []);

  const loadPrayers = useCallback(
    async (targetCity?: string) => {
      setLoading(true);
      setError(false);
      try {
        const res = await new Promise<{ prayerCity?: string }>((resolve) =>
          chrome.storage.sync.get(["prayerCity"], (r) => resolve(r)),
        );
        const activeCity =
          targetCity || (res.prayerCity as string) || "Istanbul";
        setCity(activeCity);

        const prayerTimes = await prayerService.getPrayerTimes(
          activeCity,
          "Turkey",
        );
        setTimes(prayerTimes);
        calculateHighlight(prayerTimes);
        setLoading(false);
      } catch (e) {
        logger.error("[PrayerView] loadPrayers failed:", e);
        setError(true);
        setLoading(false);
      }
    },
    [calculateHighlight],
  );

  useEffect(() => {
    loadPrayers();
  }, [loadPrayers]);

  const handleSaveCity = useCallback(
    async (newCity: string) => {
      if (!newCity) {
        return;
      }
      chrome.storage.sync.set({ prayerCity: newCity, prayerCountry: "Turkey" });
      setIsFormOpen(false);
      loadPrayers(newCity);
    },
    [loadPrayers],
  );

  return {
    loading,
    error,
    city,
    setCity,
    times,
    isFormOpen,
    setIsFormOpen,
    currentPrayerIdx,
    handleSaveCity,
  };
}

import { useState, useEffect, useRef, useCallback } from "preact/hooks";
import { WillpowerStreak, Language } from "@/types/types.js";
import { getTranslation } from "@/utils/i18n.js";

interface UseWillpowerOptions {
  lang: Language;
  onShowConfirm: (message: string, onConfirm: () => void) => void;
}

/**
 * Willpower sayaç + timer + geçmiş state mantığı (AGENTS.md 6.3: presentation/hooks/).
 * View sadece JSX render eder.
 */
export function useWillpower({ lang, onShowConfirm }: UseWillpowerOptions) {
  const t = getTranslation(lang);

  const [data, setData] = useState<WillpowerStreak | null>(null);
  const [note, setNote] = useState("");

  // Elapsed countdown states
  const [days, setDays] = useState(0);
  const [hours, setHours] = useState(0);
  const [minutes, setMinutes] = useState(0);
  const [seconds, setSeconds] = useState(0);

  const timerRef = useRef<number | null>(null);

  const calculateTime = useCallback((startDateStr: string) => {
    const start = new Date(startDateStr).getTime();
    const now = new Date().getTime();
    const diffMs = Math.max(0, now - start);

    const diffSecs = Math.floor(diffMs / 1000);
    setDays(Math.floor(diffSecs / 86400));
    setHours(Math.floor((diffSecs % 86400) / 3600));
    setMinutes(Math.floor((diffSecs % 3600) / 60));
    setSeconds(diffSecs % 60);
  }, []);

  const loadData = useCallback(async () => {
    const result = await new Promise<any>((resolve) =>
      chrome.storage.sync.get(["willpowerStreak"], (res) =>
        resolve(res.willpowerStreak),
      ),
    );
    let streakData = result;
    if (!streakData) {
      streakData = {
        startDate: new Date().toISOString(),
        bestStreakDays: 0,
        history: [],
      };
      chrome.storage.sync.set({ willpowerStreak: streakData });
    }
    setData(streakData);
    calculateTime(streakData.startDate);

    // Setup active countdown timer
    if (timerRef.current) {
      clearInterval(timerRef.current);
    }
    timerRef.current = window.setInterval(() => {
      calculateTime(streakData!.startDate);
    }, 1000);
  }, [calculateTime]);

  useEffect(() => {
    loadData();
    return () => {
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
    };
  }, [loadData]);

  const handleReset = () => {
    if (!data) {
      return;
    }

    const confirmMsg = t.willpower_reset_confirm;
    onShowConfirm(confirmMsg, async () => {
      // Calculate elapsed days
      const start = new Date(data.startDate).getTime();
      const now = new Date().getTime();
      const diffMs = Math.max(0, now - start);
      const diffSecs = Math.floor(diffMs / 1000);
      const finalDays = Math.floor(diffSecs / 86400);

      const nowStr = new Date().toISOString();

      // Push new history item
      const historyItem = {
        startDate: data.startDate,
        endDate: nowStr,
        days: finalDays,
        note: note.trim() || undefined,
      };

      const updatedData: WillpowerStreak = {
        startDate: nowStr,
        bestStreakDays: Math.max(data.bestStreakDays, finalDays),
        history: [...data.history, historyItem],
      };

      await new Promise<void>((resolve) =>
        chrome.storage.sync.set({ willpowerStreak: updatedData }, resolve),
      );
      setNote("");
      setData(updatedData);
      calculateTime(nowStr);

      // Restart timer
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
      timerRef.current = window.setInterval(() => {
        calculateTime(nowStr);
      }, 1000);
    });
  };

  const handleClearHistory = () => {
    if (!data) {
      return;
    }
    const confirmMsg = t.willpower_clear_history_confirm;
    onShowConfirm(confirmMsg, async () => {
      const updatedData: WillpowerStreak = {
        ...data,
        history: [],
      };
      await new Promise<void>((resolve) =>
        chrome.storage.sync.set({ willpowerStreak: updatedData }, resolve),
      );
      setData(updatedData);
    });
  };

  // Determine Rank Metadata
  let rankKey: string;
  if (days < 3) {
    rankKey = "initiate";
  } else if (days < 7) {
    rankKey = "iron";
  } else if (days < 14) {
    rankKey = "control";
  } else if (days < 30) {
    rankKey = "warrior";
  } else if (days < 90) {
    rankKey = "knight";
  } else {
    rankKey = "master";
  }

  const currentBest = data ? Math.max(data.bestStreakDays, days) : days;
  const historyList = data ? data.history : [];

  return {
    data,
    note,
    setNote,
    days,
    hours,
    minutes,
    seconds,
    rankKey,
    currentBest,
    historyList,
    handleReset,
    handleClearHistory,
  };
}

import { getTranslation } from "@/utils/i18n.js";
import type { AIResponseData } from "./types.js";
import type { INoteRepository } from "@/domain/repositories/INoteRepository.js";
import type { ITodoRepository } from "@/domain/repositories/ITodoRepository.js";
import type { IMemoryRepository } from "@/domain/repositories/IMemoryRepository.js";
import type { Todo } from "@/domain/entities/Todo.js";
import type { Language } from "@/domain/value-objects/Language.js";

/**
 * Automatically execute structured AI actions (create tasks, add notes, update memory).
 */
export async function executeAIAction(
  aiResult: AIResponseData,
  lang: string = "tr",
  todoRepo: ITodoRepository,
  noteRepo: INoteRepository,
  memoryRepo: IMemoryRepository,
): Promise<void> {
  if (!aiResult.action || aiResult.action === "none") {
    return;
  }

  if (aiResult.action === "create_task" && aiResult.params?.text) {
    const todos = await todoRepo.getAll();
    const newTodo = {
      id: `task-${Date.now()}`,
      text: String(aiResult.params?.text ?? ""),
      completed: false,
      repeat: String(aiResult.params?.repeat ?? "none") as Todo["repeat"],
      dueDate: String(aiResult.params?.dueDate ?? ""),
      status: "todo",
      category: "general",
      createdAt: new Date().toISOString(),
    };
    todos.unshift({
      ...newTodo,
      status: "todo" as const,
      lastCompletedDate: null,
    });
    await todoRepo.saveAll(todos);
  } else if (
    aiResult.action === "add_note" &&
    aiResult.params?.note_content
  ) {
    await handleAddNoteFromAI(
      (String(aiResult.params.note_type) || "note") as
        | "note"
        | "diary"
        | "cornell",
      aiResult.params.note_content as string,
      lang,
      noteRepo,
      aiResult.params.note_title as string,
      aiResult.params.note_cues as string,
      aiResult.params.note_summary as string,
    );
  } else if (
    aiResult.action === "update_memory" &&
    aiResult.params?.memory_fact
  ) {
    await handleUpdateMemoryFromAI(
      String(aiResult.params.memory_fact),
      memoryRepo,
    );
  }
}

/** Append a note (diary, cornell, or plain note) to the notes list. */
export async function handleAddNoteFromAI(
  type: "note" | "diary" | "cornell",
  content: string,
  lang: string,
  noteRepo: INoteRepository,
  title?: string,
  cues?: string,
  summary?: string,
): Promise<void> {
  const currentNotes = await noteRepo.getAll();
  const t = getTranslation(lang as Language);
  const formattedDate = new Date().toLocaleDateString(
    lang === "tr" ? "tr-TR" : "en-US",
  );
  const defaultTitle =
    title ||
    (type === "diary"
      ? t.note_diary_title.replace("{date}", formattedDate)
      : type === "cornell"
        ? t.note_cornell_title.replace("{date}", formattedDate)
        : t.note_title.replace("{date}", formattedDate));

  currentNotes.push({
    id: crypto.randomUUID(),
    title: defaultTitle,
    content: content,
    type: type,
    cues: cues || "",
    summary: summary || "",
    createdAt: new Date().toISOString(),
  });
  await noteRepo.saveAll(currentNotes);
}

/** Append a new learned personal memory fact. */
export async function handleUpdateMemoryFromAI(
  newFact: string,
  memoryRepo: IMemoryRepository,
): Promise<void> {
  if (!newFact || !newFact.trim()) {
    return;
  }

  const currentMemory = await memoryRepo.getMemory();
  const dateStr = new Date().toLocaleDateString("tr-TR");
  const cleanFact = `- [${dateStr}] ${newFact.trim()}`;

  let updatedMemory = currentMemory;
  if (!updatedMemory || !updatedMemory.trim()) {
    updatedMemory = `# Kişisel Hafıza & Kullanıcı Bağlamı (memory.md)\n\n## 💡 AI Tarafından Öğrenilen Bilgiler\n${cleanFact}`;
  } else if (
    updatedMemory.includes("## 💡 AI Tarafından Öğrenilen Bilgiler")
  ) {
    updatedMemory = updatedMemory.replace(
      "## 💡 AI Tarafından Öğrenilen Bilgiler",
      `## 💡 AI Tarafından Öğrenilen Bilgiler\n${cleanFact}`,
    );
  } else {
    updatedMemory = `${updatedMemory.trim()}\n\n## 💡 AI Tarafından Öğrenilen Bilgiler\n${cleanFact}`;
  }

  await memoryRepo.setMemory(updatedMemory);
}

