// ── Format helpers (pure) ──────────────────────────────────────────

export function formatPrice(price: number, currency = "TRY"): string {
  if (price === 0) {
    return "—";
  }
  const symbol = currency === "TRY" ? "₺" : currency;
  return `${price.toLocaleString("tr-TR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ${symbol}`;
}

export function formatVolume(vol: number): string {
  if (vol === 0) {
    return "—";
  }
  if (vol >= 1_000_000_000) {
    return `${(vol / 1_000_000_000).toFixed(2)}B`;
  }
  if (vol >= 1_000_000) {
    return `${(vol / 1_000_000).toFixed(2)}M`;
  }
  if (vol >= 1_000) {
    return `${(vol / 1_000).toFixed(1)}K`;
  }
  return vol.toLocaleString("tr-TR");
}

export function formatMarketCap(mc?: number): string {
  if (!mc) {
    return "—";
  }
  if (mc >= 1_000_000_000) {
    return `${(mc / 1_000_000_000).toFixed(2)}B ₺`;
  }
  if (mc >= 1_000_000) {
    return `${(mc / 1_000_000).toFixed(2)}M ₺`;
  }
  return `${mc.toLocaleString("tr-TR")} ₺`;
}

export async function fetchStockHistory(
  symbol: string,
  range: string = "1mo",
  interval?: string,
): Promise<StockHistoryItem[]> {
  const fullSymbol = symbol.endsWith(".IS") ? symbol : `${symbol}.IS`;
  const effectiveInterval = interval || (range === "1d" ? "15m" : "1d");
  try {
    const url = `https://query2.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(fullSymbol)}?interval=${effectiveInterval}&range=${range}&includePrePost=false`;
    const res = await fetch(url, {
      headers: { "User-Agent": "Mozilla/5.0", Accept: "application/json" },
      signal: AbortSignal.timeout(10000),
    });

    if (!res.ok) {
      throw new Error(`HTTP ${res.status}`);
    }

    const json = await res.json();
    const result = json?.chart?.result?.[0];
    if (!result) {
      throw new Error("No chart result");
    }

    const timestamps: number[] = result.timestamp || [];
    const quotes = result.indicators?.quote?.[0] || {};
    const opens: number[] = quotes.open || [];
    const highs: number[] = quotes.high || [];
    const lows: number[] = quotes.low || [];
    const closes: number[] = quotes.close || [];
    const volumes: number[] = quotes.volume || [];

    const history: StockHistoryItem[] = [];
    for (let i = 0; i < timestamps.length; i++) {
      if (
        opens[i] !== undefined &&
        opens[i] !== null &&
        closes[i] !== undefined &&
        closes[i] !== null
      ) {
        history.push({
          timestamp: timestamps[i] * 1000,
          open: opens[i],
          high: highs[i] ?? opens[i],
          low: lows[i] ?? opens[i],
          close: closes[i],
          volume: volumes[i] ?? 0,
        });
      }
    }
    return history;
  } catch (e) {
    logger.error("fetchStockHistory error:", e);
    return [];
  }
}

/**
 * errorReportService.ts
 * Hata raporlama servisi: birikmiş logları okur, .md'ye çevirir,
 * chrome.downloads ile indirir, temizler.
 * Loglar yalnızca cihazda (chrome.storage.local) tutulur — dışarı gönderilmez.
 */
import type { LogEntry } from "@/utils/logger.js";

const STORAGE_KEY = "logger_entries";

/** Storage'daki tüm log kayıtlarını okur (en eskiden yeniye). */
export async function getLogEntries(): Promise<LogEntry[]> {
  try {
    const res = await chrome.storage.local.get([STORAGE_KEY]);
    const entries = res?.[STORAGE_KEY];
    return Array.isArray(entries) ? (entries as LogEntry[]) : [];
  } catch {
    return [];
  }
}

/** Tüm log kayıtlarını temizler. */
export async function clearLogs(): Promise<void> {
  try {
    await chrome.storage.local.remove([STORAGE_KEY]);
  } catch {
    // sessiz — temizlik başarısız olursa kullanıcıya alert gösterilir
  }
}

/** Log kayıtlarını .md formatına çevirir. */
export async function exportLogsAsMarkdown(): Promise<string> {
  const entries = await getLogEntries();
  const manifest = chrome.runtime.getManifest();
  const now = new Date();

  const lines: string[] = [];
  lines.push("# Life OS Hata Raporu");
  lines.push("");
  lines.push(`- **Üretim tarihi:** ${now.toISOString()}`);
  lines.push(`- **Extension:** ${manifest.name} v${manifest.version}`);
  lines.push(`- **Log kaydı sayısı:** ${entries.length}`);
  lines.push("");

  if (entries.length === 0) {
    lines.push(
      "> Log kaydı bulunamadı. Henüz hata oluşmamış veya loglar temizlenmiş.",
    );
    lines.push("");
    return lines.join("\n");
  }

  // Seviyeye göre özet
  const counts: Record<string, number> = {};
  for (const e of entries) {
    counts[e.level] = (counts[e.level] || 0) + 1;
  }
  lines.push("## Özet");
  lines.push("");
  for (const [level, count] of Object.entries(counts)) {
    lines.push(`- **${level}:** ${count}`);
  }
  lines.push("");

  lines.push(`## Loglar (${entries.length})`);
  lines.push("");

  for (let i = 0; i < entries.length; i++) {
    const e = entries[i];
    lines.push(`### ${i + 1}. ${e.ts} [${e.level}] ${e.source}`);
    lines.push("");
    lines.push("```");
    lines.push(e.message);
    lines.push("```");
    lines.push("");
  }

  return lines.join("\n");
}

/** Logları life-os-logs-YYYY-MM-DD.md olarak indirir. */
export async function downloadLogsMd(): Promise<void> {
  const md = await exportLogsAsMarkdown();
  const blob = new Blob([md], { type: "text/markdown;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const dateStr = new Date().toISOString().slice(0, 10);
  const filename = `life-os-logs-${dateStr}.md`;

  try {
    await chrome.downloads.download({
      url,
      filename,
      saveAs: true,
    });
  } finally {
    // Kısa gecikme: indirme başladıktan sonra URL'i temizle
    setTimeout(() => URL.revokeObjectURL(url), 60_000);
  }
}

