/**
 * Tüm halka arz verilerini çeker.
 * halkarz.com anasayfasından makaleleri ayrıştırır; başarısız olursa statik fallback döner.
 */
export async function fetchAllIPOs(): Promise<{
  data: IPOEntry[];
  isFallback: boolean;
}> {
  try {
    const res = await fetch("https://halkarz.com", {
      signal: AbortSignal.timeout(8000),
    });
    if (res.ok) {
      const html = await res.text();
      const articleRegex = /<article class="index-list">([\s\S]*?)<\/article>/g;
      let match;
      const parsed: IPOEntry[] = [];
      let index = 0;

      while ((match = articleRegex.exec(html)) !== null) {
        const content = match[1];

        // Extract Company Name
        const nameMatch = content.match(
          /<h3 class="il-halka-arz-sirket"><a href="[^"]*" title="([^"]*)">/i,
        );
        const name = nameMatch ? nameMatch[1] : "";
        if (!name) {
          continue;
        }

        // Extract Url
        const urlMatch = content.match(/href="([^"]*)"/i);
        const url = urlMatch ? urlMatch[1] : "https://halkarz.com";

        // Extract Ticker / Code
        const tickerMatch = content.match(
          /<span class="il-bist-kod">([\s\S]*?)<\/span>/i,
        );
        const ticker = tickerMatch
          ? tickerMatch[1].replace(/<[^>]*>/g, "").trim()
          : "";

        // Extract Dates
        const dateMatch =
          content.match(/<time datetime="[^"]*" title="([^"]*)"/i) ||
          content.match(/<time[^>]*>([\s\S]*?)<\/time>/i);
        const dateRaw = dateMatch
          ? dateMatch[1].replace(/<[^>]*>/g, "").trim()
          : "";

        const parsedDate = parseHalkarzDate(dateRaw);
        const formatDateStr = (d: Date | null) =>
          d ? d.toISOString().split("T")[0] : "";

        parsed.push({
          id: `ha-${ticker || index}`,
          name,
          ticker: ticker || "—",
          sector: "Halka Arz",
          startDate: formatDateStr(parsedDate.start) || dateRaw,
          endDate: formatDateStr(parsedDate.end) || dateRaw,
          priceRange: "Detaylar için siteyi ziyaret edin",
          lotSize: 1,
          status: parsedDate.status,
          kapUrl: url,
        });
        index++;
      }

      if (parsed.length > 0) {
        return { data: parsed, isFallback: false };
      }
    }
  } catch (e) {
    logger.error("Failed to fetch from halkarz.com:", e);
  }

  return { data: FALLBACK_IPOS, isFallback: true };
}

/**
 * Aktif ve yakın gelecekteki halka arzları döner.
 */
export async function fetchActiveIPOs(): Promise<{
  data: IPOEntry[];
  isFallback: boolean;
}> {
  const result = await fetchAllIPOs();
  return {
    data: result.data.filter(
      (ipo) => ipo.status === "active" || ipo.status === "upcoming",
    ),
    isFallback: result.isFallback,
  };
}

/**
 * Son `days` gün içinde tamamlanmış halka arzları döner.
 */
export async function fetchIPOHistory(days = 30): Promise<{
  data: IPOEntry[];
  isFallback: boolean;
}> {
  const result = await fetchAllIPOs();
  const history = result.data.filter(
    (ipo) => ipo.status === "completed" && isWithinLastDays(ipo.endDate, days),
  );
  return { data: history, isFallback: result.isFallback };
}

/**
 * kapNewsService.ts
 * Kamuyu Aydınlatma Platformu (KAP) ve BIST haberlerinin RSS üzerinden çekilmesi ve IKapNewsCacheRepository ile önbelleklenmesi.
 */

import type {
  IKapNewsCacheRepository,
  KapNewsCache,
} from "@/domain/repositories/IKapNewsCacheRepository.js";
import type { KapNewsItem } from "@/types/kap.js";

export type { KapNewsItem } from "@/types/kap.js";

const KAP_CACHE_TTL = 15 * 60 * 1000; // 15 dakika cache

export function createKapNewsService(cacheRepo: IKapNewsCacheRepository) {
  return {
    async fetchLatestKapNews(targetSymbols?: string[]): Promise<KapNewsItem[]> {
      // Önce yerel cache kontrol et
      try {
        const cached = await cacheRepo.getCached();
        if (
          cached &&
          cached.timestamp &&
          Date.now() - cached.timestamp < KAP_CACHE_TTL &&
          cached.data
        ) {
          const items: KapNewsItem[] = cached.data;
          if (targetSymbols && targetSymbols.length > 0) {
            const uppercaseSyms = targetSymbols.map((s) =>
              s.replace(/\.IS$/, "").toUpperCase(),
            );
            const filtered = items.filter(
              (item) =>
                item.symbol &&
                uppercaseSyms.includes(item.symbol.toUpperCase()),
            );
            if (filtered.length > 0) {
              return filtered;
            }
          }
          return items;
        }
      } catch {
        // Cache okuma hatasında devam et
      }

      // Canlı RSS akışını çek (Mynet BIST / KAP Haber akışı)
      try {
        const res = await fetch("https://finans.mynet.com/rss/borsa/", {
          signal: AbortSignal.timeout(8000),
        });

        if (res.ok) {
          const xmlText = await res.text();
          const items = parseKapRssXml(xmlText);

          if (items.length > 0) {
            const cachePayload: KapNewsCache = {
              timestamp: Date.now(),
              data: items,
            };
            await cacheRepo.setCached(cachePayload);

            if (targetSymbols && targetSymbols.length > 0) {
              const uppercaseSyms = targetSymbols.map((s) =>
                s.replace(/\.IS$/, "").toUpperCase(),
              );
              const filtered = items.filter(
                (item) =>
                  item.symbol &&
                  uppercaseSyms.includes(item.symbol.toUpperCase()),
              );
              if (filtered.length > 0) {
                return filtered;
              }
            }
            return items;
          }
        }
      } catch {
        // RSS isteğinde hata olursa sessizce fallback verisine geç
      }

      return getFallbackKapNews(targetSymbols);
    },
  };
}

