/**
 * kpssQuizService.ts
 * Service module for querying local KPSS past questions archives and handling exam subsets.
 * Clean Architecture - Service Layer.
 */

import { KPSS_YEARLY_DATA } from "@/data/kpss/kpssDataRegistry.js";
import osymData from "@/data/kpss/osymHistoryQuestions.json";
import { QuizQuestion } from "@/services/kpss/kpssAiService.js";

export interface KpssPastQuizSession {
  id: string;
  date: string;
  questionCount: number;
  score: number;
  questions: QuizQuestion[];
  selectedAnswers: number[];
  mode?: "local" | "external";
}

export interface KpssPastQuiz {
  subject: string;
  topic: string;
  score: number;
  questions: QuizQuestion[];
  selectedAnswers: number[];
  date: string;
  history?: KpssPastQuizSession[];
}

/**
 * Aggregates questions for a specific topic across yearly exam archives.
 */
export function getLocalQuestionsForTopic(
  subjectKey: string,
  topicName: string,
): QuizQuestion[] {
  const aggregated: QuizQuestion[] = [];
  Object.values(KPSS_YEARLY_DATA).forEach((yearData) => {
    const list = yearData[subjectKey];
    if (Array.isArray(list)) {
      list.forEach((q: unknown) => {
        const quizQ = q as KpssPastQuiz;
        if (quizQ.topic === topicName) {
          aggregated.push(quizQ as unknown as QuizQuestion);
        }
      });
    }
  });
  return aggregated;
}

/**
 * Generates questions list for specific exam year or mixed GY-GK past exams.
 * Supports countLimit and selectedChapter filtering for Tarih Soru Arşivi (915 Q) & Karma Sınav.
 * Uses KPSS Lisans exam distribution ratios (50% History, 35% Geography, 15% Math) when All subjects selected in Mixed mode.
 */
export function getPastExamQuestions(
  year: string,
  subject: string,
  countLimit?: number,
  selectedChapter?: string,
): QuizQuestion[] {
  let questions: QuizQuestion[] = [];

  if (year === "tarih_arsivi") {
    const list = (osymData as { history?: any[] }).history || [];
    list.forEach((q) => {
      let isMatch = false;
      if (!selectedChapter || selectedChapter === "all") {
        isMatch = true;
      } else if (q.chapter) {
        const normQ = q.chapter.toLowerCase().replace(/[^a-z0-9çğıöşü]/g, "");
        const normSel = selectedChapter.toLowerCase().replace(/[^a-z0-9çğıöşü]/g, "");
        isMatch =
          normQ === normSel ||
          normQ.includes(normSel) ||
          normSel.includes(normQ);
      }

      if (isMatch) {
        const rawAns = (q.answer || "").trim();
        const cleanAnsLetter = rawAns.charAt(0).toUpperCase();
        const letters = ["A", "B", "C", "D", "E"];
        const correctIdx = letters.indexOf(cleanAnsLetter);

        questions.push({
          question: q.question,
          options: letters.map((l) => `${l}) ${q.options?.[l] || ""}`),
          correctAnswer: correctIdx !== -1 ? correctIdx : 0,
          solution: q.explanation
            ? `${cleanAnsLetter}) ${q.options?.[cleanAnsLetter] || ""} — ${q.explanation}`
            : `${cleanAnsLetter}) ${q.options?.[cleanAnsLetter] || ""}`,
        });
      }
    });

    // Rastgele karıştır
    questions = [...questions].sort(() => Math.random() - 0.5);
  } else if (year === "karma") {
    if (subject === "all") {
      // 🎯 KPSS Lisans Gerçek Dağılım Oranı: %50 Tarih, %35 Coğrafya, %15 Matematik
      const historyPool: QuizQuestion[] = [];
      const geoPool: QuizQuestion[] = [];
      const mathPool: QuizQuestion[] = [];

      Object.keys(KPSS_YEARLY_DATA).forEach((y) => {
        const yearData = KPSS_YEARLY_DATA[y];
        if (yearData.tarih)
          historyPool.push(...(yearData.tarih as unknown as QuizQuestion[]));
        if (yearData.cografya)
          geoPool.push(...(yearData.cografya as unknown as QuizQuestion[]));
        if (yearData.matematik)
          mathPool.push(...(yearData.matematik as unknown as QuizQuestion[]));
      });

      const totalTarget = countLimit || 20;
      const historyCount = Math.round(totalTarget * 0.5);
      const geoCount = Math.round(totalTarget * 0.35);
      const mathCount = Math.max(1, totalTarget - historyCount - geoCount);

      const shuffle = (arr: QuizQuestion[]) =>
        [...arr].sort(() => Math.random() - 0.5);

      const pickedHistory = shuffle(historyPool).slice(0, historyCount);
      const pickedGeo = shuffle(geoPool).slice(0, geoCount);
      const pickedMath = shuffle(mathPool).slice(0, mathCount);

      return shuffle([...pickedHistory, ...pickedGeo, ...pickedMath]);
    } else {
      // Tekil bir ders seçildiyse o dersin tüm yıllardaki sorularını karıştır
      Object.keys(KPSS_YEARLY_DATA).forEach((y) => {
        const yearData = KPSS_YEARLY_DATA[y];
        const list = yearData[subject];
        if (Array.isArray(list)) {
          questions.push(...(list as unknown as QuizQuestion[]));
        }
      });
      questions = [...questions].sort(() => Math.random() - 0.5);
    }
  } else {
    const yearData = KPSS_YEARLY_DATA[year];
    if (yearData) {
      if (subject === "all") {
        Object.values(yearData).forEach((list: unknown) => {
          if (Array.isArray(list)) {
            questions.push(...(list as unknown as QuizQuestion[]));
          }
        });
      } else {
        questions = (yearData[subject] || []) as unknown as QuizQuestion[];
      }
    }
  }

  // Eğer countLimit verilmişse sınırı uygula
  if (countLimit && countLimit > 0 && questions.length > countLimit) {
    return questions.slice(0, countLimit);
  }

  return questions;
}

/**
 * kpssWikiService.ts
 * Service layer for KPSS Ders Notları (Wiki/Article Note System).
 * Manages storage persistence via IWikiNoteRepository, markdown rendering,
 * headings extraction, and Wikilinks.
 */

import { renderMarkdown } from "@/utils/markdownRenderer.js";
import katex from "katex";
import "katex/dist/katex.min.css";
import type { IWikiNoteRepository } from "@/domain/repositories/IWikiNoteRepository.js";
import type { KpssWikiNote, HeadingItem } from "@/types/kpss.js";

export type { KpssWikiNote, HeadingItem } from "@/types/kpss.js";

/**
 * Extract Title from content: extracts the first meaningful line as title (no limit).
 * e.g. "Maki ailesinin özellikleri..." -> "Maki ailesinin özellikleri..."
 */
export function extractTitleFromContent(content: string): string {
  if (!content) {
    return "";
  }
  const lines = content.split("\n");
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) {
      continue;
    }
    const clean = trimmed
      .replace(/^#+\s*/, "")
      .replace(/^[:\-*_`]+/, "")
      .trim();
    if (!clean) {
      continue;
    }
    // İlk anlamlı satırın tamamını başlık yap — karakter sınırı yok
    return clean;
  }
  return "";
}

/**
 * Extract H1, H2, H3 headings from markdown content
 * "```sema" / "```harita" bloklarının içindeki başlıklar hariç tutulur
 * (şema/harita başlığı İçindekiler'e karışmasın).
 */
export function extractHeadings(content: string): HeadingItem[] {
  if (!content) {
    return [];
  }
  const lines = content.split("\n");
  const headings: HeadingItem[] = [];
  let inBlock = false;
  lines.forEach((l) => {
    const trimmed = l.trim();
    if (/^```(sema|harita)\s*$/.test(trimmed)) {
      inBlock = true;
      return;
    }
    if (inBlock && /^```\s*$/.test(trimmed)) {
      inBlock = false;
      return;
    }
    if (inBlock) {
      return;
    }
    const m = l.match(/^(#{1,3})\s+(.+)$/);
    if (m) {
      headings.push({
        level: m[1].length,
        text: m[2].replace(/[*_[\]]/g, "").trim(),
      });
    }
  });
  return headings;
}

/**
 * Extract the first Image URL from markdown content for Infobox Featured Header
 */
export function extractFirstImageUrl(content: string): string | null {
  if (!content) {
    return null;
  }
  const mdImgMatch = content.match(/!\[.*?\]\((https?:\/\/[^\s)]+)\)/i);
  if (mdImgMatch && mdImgMatch[1]) {
    return mdImgMatch[1];
  }
  const plainUrlMatch = content.match(
    /(https?:\/\/[^\s<>"]+\.(?:jpg|jpeg|png|gif|webp|svg)|https?:\/\/[^\s<>"']+images\?[^\s<>"']+|https?:\/\/[^\s<>"']+encrypted-tbn[^\s<>"']+)/i,
  );
  if (plainUrlMatch && plainUrlMatch[0]) {
    return plainUrlMatch[0];
  }
  return null;
}

/**
 * Render Markdown with custom styled links highlighted in blue.
 */
export function renderCustomArticleMarkdown(
  content: string,
  allNotes: KpssWikiNote[],
): string {
  if (!content) {
    return "";
  }
  const firstImg = extractFirstImageUrl(content);
  let processedContent = content;
  if (firstImg) {
    const escapedUrl = firstImg.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const mdPattern = new RegExp(`!\\[.*?\\]\\(${escapedUrl}\\)`, "gi");
    const plainPattern = new RegExp(`^\\s*${escapedUrl}\\s*$`, "gim");
    processedContent = processedContent
      .replace(mdPattern, "")
      .replace(plainPattern, "");
  }
  processedContent = processedContent.replace(
    /^(https?:\/\/[^\s<>"]+\.(?:jpg|jpeg|png|gif|webp|svg)|https?:\/\/[^\s<>"']+images\?[^\s<>"']+|https?:\/\/[^\s<>"']+encrypted-tbn[^\s<>"']+)$/gim,
    (url) => `![Görsel](${url})`,
  );
  let html = renderMarkdown(processedContent);

  // LaTeX desteği: $$...$$ (blok) ve $...$ (satır içi) KaTeX ile render edilir.
  // ÖNCE yapılır ki wikilink dönüşümleri LaTeX içeriğine dokunmasın.
  html = html.replace(/(\$\$[\s\S]+?\$\$|\$[^$\n]+?\$)/g, (match) => {
    const isBlock = match.startsWith("$$") && match.endsWith("$$");
    const math = isBlock ? match.slice(2, -2) : match.slice(1, -1);
    try {
      const rendered = katex.renderToString(math, {
        displayMode: isBlock,
        throwOnError: false,
      });
      return isBlock
        ? `<div style="margin:10px 0;overflow-x:auto;">${rendered}</div>`
        : rendered;
    } catch {
      return match;
    }
  });

  html = html.replace(
    /\[\[([^\]|]+)(?:\|([^\]]+))?\]\]/g,
    (_, title, display) => {
      const text = display || title;
      return `<a data-wiki-link="${escapeHtmlAttr(title)}" class="article-link" style="color: #60a5fa; cursor: pointer; text-decoration: underline; font-weight: 600;">${text}</a>`;
    },
  );
  allNotes.forEach((n) => {
    if (!n.title || n.title.trim().length < 3) {
      return;
    }
    const cleanTitle = n.title.trim();
    const escaped = cleanTitle.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    try {
      const regex = new RegExp(
        `(?<![\\p{L}\\p{N}])(${escaped})(?![\\p{L}\\p{N}])`,
        "gui",
      );
      html = html.replace(regex, (match, _g, offset, str) => {
        // Zaten <a> veya KaTeX span içinde olan eşleşmeleri atla
        const before = str.slice(0, offset);
        const after = str.slice(offset + match.length);
        if (
          before.lastIndexOf("<a") > before.lastIndexOf("</a>") ||
          after.indexOf("</a>") < after.indexOf("<a") ||
          before.lastIndexOf("=") > before.lastIndexOf(">") ||
          before.lastIndexOf('<span class="katex"') >
            before.lastIndexOf("</span>")
        ) {
          return match;
        }
        return `<a data-wiki-link="${escapeHtmlAttr(cleanTitle)}" class="article-link" style="color: #60a5fa; cursor: pointer; text-decoration: underline; font-weight: 600;">${match}</a>`;
      });
    } catch {
      const regex = new RegExp(`\\b(${escaped})\\b`, "gi");
      html = html.replace(regex, (match, _g, offset, str) => {
        const before = str.slice(0, offset);
        const after = str.slice(offset + match.length);
        if (
          before.lastIndexOf("<a") > before.lastIndexOf("</a>") ||
          after.indexOf("</a>") < after.indexOf("<a") ||
          before.lastIndexOf('<span class="katex"') >
            before.lastIndexOf("</span>")
        ) {
          return match;
        }
        return `<a data-wiki-link="${escapeHtmlAttr(cleanTitle)}" class="article-link" style="color: #60a5fa; cursor: pointer; text-decoration: underline; font-weight: 600;">${match}</a>`;
      });
    }
  });

  return html;
}

/**
 * Get human readable Turkish label for KPSS subject keys
