  lazy = false,
): Promise<WordCategory[]> => {
  if (CACHED_FULL && !lazy) {
    return CACHED_FULL;
  }

  const data = [
    ...(await getCoreVocabulary(lazy)),
    ...(await getIdiomsVocabulary(lazy)),
    ...(await getPhrasalVocabulary(lazy)),
    ...(await getGreVocabulary(lazy)),
    ...(await getIrregularVocabulary(lazy)),
  ];

  if (!lazy) {
    CACHED_FULL = data;
  }
  return data;
};

