/**
 * Canlı internet aramasını gerçekleştirir ve en alakalı web kaynaklarını döndürür.
 */
export async function executeWebSearch(
  userQuery: string,
): Promise<WebSearchResult> {
  const cleanQuery = userQuery
    .replace(/[^\w\sğüşıöçĞÜŞİÖÇ]/gi, " ")
    .trim()
    .slice(0, 100);

  if (!cleanQuery) {
    return { query: userQuery, sources: [] };
  }

  try {
    // 1. Primary: DuckDuckGo HTML Live Web Search
    const searchUrl = `https://html.duckduckgo.com/html/?q=${encodeURIComponent(cleanQuery)}`;
    const res = await fetch(searchUrl, {
      headers: {
        "User-Agent":
          "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
        Accept: "text/html,application/xhtml+xml,application/xml",
      },
      signal: AbortSignal.timeout(6000),
    });

    if (res.ok) {
      const html = await res.text();
      const sources = parseDuckDuckGoHTML(html);
      if (sources.length > 0) {
        return { query: cleanQuery, sources };
      }
    }
  } catch (e) {
    logger.warn("Primary DuckDuckGo HTML search error:", e);
  }

  // 2. Fallback: DuckDuckGo Instant API
  try {
    const apiUrl = `https://api.duckduckgo.com/?q=${encodeURIComponent(cleanQuery)}&format=json&no_html=1&skip_disambig=1`;
    const res = await fetch(apiUrl, {
      signal: AbortSignal.timeout(5000),
    });
    if (res.ok) {
      const json = await res.json();
      const sources: WebSearchSource[] = [];

      if (json.AbstractText && json.AbstractURL) {
        sources.push({
          title: json.Heading || cleanQuery,
          url: json.AbstractURL,
          snippet: json.AbstractText,
        });
      }

      const related = json.RelatedTopics || [];
      for (const item of related) {
        if (item.Text && item.FirstURL && sources.length < 4) {
          sources.push({
            title: item.Text.slice(0, 60) + "...",
            url: item.FirstURL,
            snippet: item.Text,
          });
        }
      }

      if (sources.length > 0) {
        return { query: cleanQuery, sources };
      }
    }
  } catch (e) {
    logger.warn("Fallback DuckDuckGo API search error:", e);
  }

  return { query: cleanQuery, sources: [] };
}

/**
 * DuckDuckGo HTML çıktılarını ayrıştırarak temiz başlık, URL ve özet çıkarır.
 */
function parseDuckDuckGoHTML(html: string): WebSearchSource[] {
  const sources: WebSearchSource[] = [];
  try {
    if (typeof DOMParser === "undefined") {
      // Service Worker (Background) context: DOMParser does not exist, use regex parsing
      const resultBlocks = html
        .split(/<div[^>]*class="[^"]*result[^"]*"[^>]*>/gi)
        .slice(1);
      for (const block of resultBlocks) {
        if (sources.length >= 4) {
          break;
        }
        const hrefMatch = block.match(
          /href="([^"]*uddg=[^"]*)"|href="(https?:\/\/[^"]+)"/i,
        );
        const titleMatch =
          block.match(
            /<a[^>]*class="[^"]*result__url[^"]*"[^>]*>([\s\S]*?)<\/a>/i,
          ) || block.match(/<h2[^>]*>([\s\S]*?)<\/h2>/i);
        const snippetMatch = block.match(
          /class="[^"]*result__snippet[^"]*"[^>]*>([\s\S]*?)<\/(?:a|td|div)>/i,
        );

        if (hrefMatch) {
          let rawUrl = hrefMatch[1] || hrefMatch[2] || "";
          if (rawUrl.includes("uddg=")) {
            const m = rawUrl.match(/uddg=([^&]+)/);
            if (m && m[1]) {
              rawUrl = decodeURIComponent(m[1]);
            }
          }
          const cleanTitle = (titleMatch ? titleMatch[1] : "Arama Sonucu")
            .replace(/<[^>]+>/g, "")
            .trim();
          const cleanSnippet = (snippetMatch ? snippetMatch[1] : cleanTitle)
            .replace(/<[^>]+>/g, "")
            .trim();

          if (rawUrl.startsWith("http") && cleanTitle) {
            sources.push({
              title: cleanTitle,
              url: rawUrl,
              snippet: cleanSnippet,
            });
          }
        }
      }
      return sources;
    }

    const parser = new DOMParser();
    const doc = parser.parseFromString(html, "text/html");
    const results = doc.querySelectorAll(".result");

    results.forEach((el, index) => {
      if (index >= 4) {
        return;
      }
      const titleEl = el.querySelector(".result__title a");
      const snippetEl = el.querySelector(".result__snippet");

      if (titleEl) {
        const rawTitle = titleEl.textContent?.trim() || "";
        let rawUrl = titleEl.getAttribute("href") || "";

        // Unpack DuckDuckGo redirect url if present
        if (rawUrl.includes("uddg=")) {
          const match = rawUrl.match(/uddg=([^&]+)/);
          if (match && match[1]) {
            rawUrl = decodeURIComponent(match[1]);
          }
        }

        const snippet = snippetEl?.textContent?.trim() || "";

        if (rawTitle && rawUrl.startsWith("http")) {
          sources.push({
            title: rawTitle,
            url: rawUrl,
            snippet: snippet || rawTitle,
          });
        }
      }
    });
  } catch (e) {
    logger.error("parseDuckDuckGoHTML error:", e);
  }
  return sources;
}

/**
 * zettelkastenEngine.ts
 * Obsidian-style Zettelkasten Knowledge Graph Engine.
 * Extracts [[Internal Links]], #tags, backlinks, and computes 2D Graph View physics layout.
 */

import { Note } from "@/types/types.js";

export interface GraphNode {
  id: string;
  title: string;
  type: string; // note, cornell, diary
  tags: string[];
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  color: string;
  linksCount: number;
}

export interface GraphEdge {
  source: string; // node id
  target: string; // node id
  label?: string;
  type: "parent" | "wikilink";
}

export interface ZettelkastenGraph {
  nodes: GraphNode[];
  edges: GraphEdge[];
}

/**
 * Extract all [[Internal Links]] from markdown note content.
 * e.g. "Daha fazla bilgi için [[Tarih - Amasya Genelgesi]] sayfasına bakın."
 */
export function extractInternalLinks(content: string): string[] {
  if (!content) {
    return [];
  }
  const regex = /\[\[([^\]|]+)(?:\|[^\]]+)?\]\]/g;
  const links: string[] = [];
  let match;
  while ((match = regex.exec(content)) !== null) {
    if (match[1] && match[1].trim()) {
      links.push(match[1].trim());
    }
  }
  return Array.from(new Set(links));
}

/**
 * Extract all hashtags from note content or cues/summary.
 * e.g. "#kpss/tarih", "#kpss/cografya", "#genel"
 */
export function extractTags(content: string): string[] {
  if (!content) {
    return [];
  }
  const regex = /(?:^|\s)#([a-zA-Z0-9_/öçşğıüÖÇŞĞİÜ-]+)/g;
  const tags: string[] = [];
  let match;
  while ((match = regex.exec(content)) !== null) {
    if (match[1] && match[1].trim()) {
      tags.push(match[1].trim().toLowerCase());
    }
  }
  return Array.from(new Set(tags));
}

/**
 * Determine node color based on KPSS subject tags or category.
 */
export function getNodeColor(
  tags: string[] = [],
  subject?: string,
  title?: string,
): string {
  const tagStr = (
    tags.join(" ") +
    " " +
    (subject || "") +
    " " +
    (title || "")
  ).toLowerCase();
  if (tagStr.includes("tarih")) {
    return "#a855f7";
  } // Purple
  if (tagStr.includes("cografya") || tagStr.includes("coğrafya")) {
    return "#10b981";
  } // Emerald
  if (tagStr.includes("vatandaslik") || tagStr.includes("vatandaşlık")) {
    return "#3b82f6";
  } // Blue
  if (tagStr.includes("turkce") || tagStr.includes("türkçe")) {
    return "#f59e0b";
  } // Amber
  if (tagStr.includes("matematik")) {
    return "#ef4444";
  } // Red
  if (tagStr.includes("kpss")) {
    return "#8b5cf6";
  } // Violet
  return "#6366f1"; // Default Indigo
}

/**
 * Compute Backlinks: find all notes that link to target Note Title or ID.
 */
export function getBacklinks(targetNote: Note, allNotes: Note[]): Note[] {
  const targetTitleLower = targetNote.title.trim().toLowerCase();
  return allNotes.filter((n) => {
    if (n.id === targetNote.id) {
      return false;
    }
    const links = extractInternalLinks(n.content);
    return links.some((l) => l.trim().toLowerCase() === targetTitleLower);
  });
}

/**
 * Build 2D Knowledge Graph Nodes and Edges for canvas / SVG rendering.
 * Applies a deterministic circular force-directed layout simulation.
 */
export function buildKnowledgeGraph(
  notes: Note[],
  width = 800,
  height = 500,
  parentIdMap?: Map<string, string>,
): ZettelkastenGraph {
  if (notes.length === 0) {
    return { nodes: [], edges: [] };
  }

  // Title to ID map for link matching
  const titleToIdMap = new Map<string, string>();
  notes.forEach((n) => {
    titleToIdMap.set(n.title.trim().toLowerCase(), n.id);
  });

  const edges: GraphEdge[] = [];
  const edgeSet = new Set<string>();

  // 1. Parent-Child edges (green, solid)
  if (parentIdMap) {
    parentIdMap.forEach((parentId, childId) => {
      if (parentId && childId) {
        const edgeKey = [childId, parentId].sort().join("<->");
        if (!edgeSet.has(edgeKey)) {
          edgeSet.add(edgeKey);
          edges.push({ source: childId, target: parentId, type: "parent" });
        }
      }
    });
  }

  // 2. Wikilink edges (purple, dashed)
  notes.forEach((note) => {
    const rawContent = `${note.content || ""} ${note.cues || ""} ${note.summary || ""}`;
    const internalLinks = extractInternalLinks(rawContent);

    internalLinks.forEach((linkTitle) => {
      const targetId = titleToIdMap.get(linkTitle.toLowerCase());
      if (targetId && targetId !== note.id) {
        const edgeKey = [note.id, targetId].sort().join("<->");
        if (!edgeSet.has(edgeKey)) {
          edgeSet.add(edgeKey);
          edges.push({
            source: note.id,
            target: targetId,
            label: linkTitle,
            type: "wikilink",
          });
        }
      }
    });
  });

  // Calculate degrees (connections count) per node
  const degrees = new Map<string, number>();
  notes.forEach((n) => degrees.set(n.id, 0));
  edges.forEach((e) => {
    degrees.set(e.source, (degrees.get(e.source) || 0) + 1);
    degrees.set(e.target, (degrees.get(e.target) || 0) + 1);
  });

  // Initialize nodes in radial spiral
  const centerX = width / 2;
  const centerY = height / 2;
  const nodesCount = notes.length;

  const nodes: GraphNode[] = notes.map((n, idx) => {
    const angle = (idx / nodesCount) * Math.PI * 2 + (idx % 3) * 0.5;
    const radiusDist = 120 + (idx % 5) * 45;
    const rawContent = `${n.content || ""} ${n.cues || ""} ${n.summary || ""}`;
    const tags = extractTags(rawContent);
    const linkDeg = degrees.get(n.id) || 0;

    return {
      id: n.id,
      title: n.title,
      type: n.type || "note",
      tags,
      x: centerX + Math.cos(angle) * radiusDist,
      y: centerY + Math.sin(angle) * radiusDist,
      vx: 0,
      vy: 0,
      radius: Math.max(16, Math.min(32, 16 + linkDeg * 4)),
      color: getNodeColor(tags, n.type || "note", n.title),
      linksCount: linkDeg,
    };
  });

  // Run 30 iterations of simple force attraction & repulsion layout
  for (let iter = 0; iter < 30; iter++) {
    // Repulsion between nodes
    for (let i = 0; i < nodes.length; i++) {
      for (let j = i + 1; j < nodes.length; j++) {
        const n1 = nodes[i];
        const n2 = nodes[j];
        const dx = n2.x - n1.x;
        const dy = n2.y - n1.y;
        const dist = Math.sqrt(dx * dx + dy * dy) || 1;
        if (dist < 180) {
          const force = ((180 - dist) / dist) * 1.5;
          n1.x -= dx * force * 0.1;
          n1.y -= dy * force * 0.1;
          n2.x += dx * force * 0.1;
          n2.y += dy * force * 0.1;
        }
      }
    }

    // Attraction along edges
    edges.forEach((e) => {
      const source = nodes.find((n) => n.id === e.source);
      const target = nodes.find((n) => n.id === e.target);
      if (source && target) {
        const dx = target.x - source.x;
        const dy = target.y - source.y;
        const dist = Math.sqrt(dx * dx + dy * dy) || 1;
        const force = (dist - 100) * 0.05;
        source.x += dx * force * 0.1;
        source.y += dy * force * 0.1;
        target.x -= dx * force * 0.1;
        target.y -= dy * force * 0.1;
      }
    });

    // Bound to viewport canvas area
    nodes.forEach((n) => {
      n.x = Math.max(40, Math.min(width - 40, n.x));
      n.y = Math.max(40, Math.min(height - 40, n.y));
    });
  }

  return { nodes, edges };
}

